package main

import (
	"context"
	"fmt"
	"strings"

	appllm "github.com/dnd-llm/dnd-llm/internal/application/llm"
	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
	infrallm "github.com/dnd-llm/dnd-llm/internal/infrastructure/llm"
)

// ── Le/effect cases: deed → ONE key of the closed effect catalogue, by MEANING. ──
//
// EffectSelector.Classify is the consequence-sensor: it maps the player's free-form deed
// to a catalogue effect (поджечь/разбить/потушить/… or «никакой») under a grammar, so the
// deterministic core can apply that key's fixed mechanics. It is a genuine perception
// LAYER no other slice produces — kind is coarse routing, charge is person-polarity, the
// raw Verb is text, grounding picks the thing — yet it had NO isolated bench.
//
// CONTRACT (decisive — fixes the bench's scope). In production the sensor is reached ONLY
// via the `other` action kind (executeAction switch → doFreeform → computeVerdict). The
// parser's kind-layer (benched in segment/domain) already routes move/talk/observe/take/
// give/attack AWAY. So look/listen/talk/pick-up deeds NEVER reach this layer — feeding them
// here would test a contract it does not hold (the kind-router owns «no thing changes» for
// those). Hence every case below is an `other`-kind physical deed. «никакой» here is the
// NARROW residual: an `other` deed that touches/contacts a thing but transforms nothing
// (погладить/потрогать/прислониться) — NOT look/talk, which never arrive.
//
// The hard, decisive cases: CONSEQUENCE-verbs that resolve by meaning («затоптать костёр»
// →потушить), and FALSE FRIENDS where the THING's nature must NOT bias the verb («потрогать
// обгоревшую балку» is still just touching → никакой). Held-out from the prompt, which
// carries only definitions (no effect few-shot beyond «поджечь» and the none markers).
//
// want == "" means «никакой» (Classify returns "" for the none sentinel).
//
// DESTRUCTIVE-FORCE deeds score on CLUSTER membership, not the exact leaf (marked ✓≈):
// разбить/сломать/расколоть/раздавить/порвать/погнуть/смять all mean «destroyed or
// deformed by force», and the EXACT leaf is settled downstream by the grounded thing's
// FRACTURE property (a torn letter, a bent poker — entity.RefineForceEffect), NOT by the
// sensor. So the sensor's job for such deeds is only to land in the cluster; demanding a
// specific leaf here would test a distinction the 4B is rightly forbidden to make (it
// cannot read the thing's nature). Non-force effects still score on the exact key.

type effectCase struct {
	deed string
	want string // catalogue key, or "" for «никакой»
	note string // subtype, for the human reading the run
}

var effectCases = []effectCase{
	// positives — verb directly names the effect (varied keys, not leaning on поджечь)
	{"разбить кувшин об пол", "разбить", "прямой глагол"},
	{"опрокинуть бочку с водой", "опрокинуть", "прямой глагол"},
	{"наполнить ведро из колодца", "наполнить", "прямой глагол"},
	{"порвать старое письмо надвое", "порвать", "прямой глагол"},
	{"облить стол элем из кружки", "облить", "прямой глагол"},
	{"заморозить лужу у порога", "заморозить", "прямой глагол"},
	{"поджечь стог сена факелом", "поджечь", "прямой глагол"},
	{"согнуть кочергу о колено", "погнуть", "синоним глагола: согнуть → каталожное «погнуть» (не «смять»)"},
	{"отмыть грязный котелок", "отмыть", "прямой глагол"},
	// positives — CONSEQUENCE-verb resolves by MEANING (verb ≠ effect; the decisive half)
	{"швырнуть глиняную миску в каменную стену", "разбить", "следствие по смыслу"},
	{"затоптать костёр сапогами", "потушить", "следствие по смыслу"},
	{"макнуть горящий факел в бочку с водой", "потушить", "следствие по смыслу"},
	// negatives — «никакой» IN CONTRACT: an `other` deed that contacts but changes nothing
	{"потрогать рукоять меча на стене", "", "никакой: касание без изменения"},
	{"погладить ладонью бок кувшина", "", "никакой: касание без изменения"},
	{"прислониться к дверному косяку", "", "никакой: опора без изменения"},
	// FALSE FRIENDS IN CONTRACT — thing-nature must NOT bias the verb (deed is mere contact)
	{"потрогать обгоревшую балку под потолком", "", "ложный друг: природа вещи (обгорело) vs глагол"},
	{"погладить заиндевевшее стекло", "", "ложный друг: природа вещи (иней) vs глагол"},
	{"провести рукой по треснувшей стене", "", "ложный друг: природа вещи (трещина) vs глагол"},
}

// runEffectDomain benches the FIRST layer in ISOLATION — the deed → influence DOMAIN
// classification (entity.DomainOf the bench's expected leaf) — calling ClassifyDomain
// directly. This is the bench-first-per-layer discipline: the seam the 4B reveals here
// (noun-anchoring → a «содержимое» sink) is measured ALONE, before composing with the
// leaf layer, so the domain prompt is tuned against the real deeds (force-cluster cases
// share one domain, so they score on the exact domain — no ✓≈ needed here).
func runEffectDomain(ctx context.Context, p infrallm.SchemaCompleter, samples int) {
	sel := appllm.NewEffectSelector(p)
	pass, total := 0, 0
	for i, c := range effectCases {
		if c.want == "" {
			continue // «никакой» is a LEAF concern now (no concrete outcome), not a domain — see effect_frame.go
		}
		want := entity.DomainOf(c.want)
		wantLabel := want
		fmt.Printf("\n%s\n#%-2d домен [%s]  (%s)\n   деяние: «%s»\n%s\n",
			strings.Repeat("═", 90), i+1, wantLabel, c.note, c.deed, strings.Repeat("─", 90))
		for s := 1; s <= samples; s++ {
			got, err := sel.ClassifyDomain(ctx, c.deed)
			gotLabel := got
			if gotLabel == "" {
				gotLabel = "никакой"
			}
			mark := "✓"
			switch {
			case err != nil:
				mark = "✗ (err: " + err.Error() + ")"
			case got == want:
				pass++
			default:
				mark = "✗"
			}
			total++
			fmt.Printf("  ⃟%d  domain=%-12s %s\n", s, gotLabel, mark)
		}
	}
	fmt.Printf("\n%s\nИТОГ effect-domain: ✓=%d ✗=%d из %d\n", strings.Repeat("═", 90), pass, total-pass, total)
}

func runEffect(ctx context.Context, p infrallm.SchemaCompleter, samples int) {
	sel := appllm.NewEffectSelector(p)
	pass, total := 0, 0
	for i, c := range effectCases {
		wantLabel := c.want
		if wantLabel == "" {
			wantLabel = "никакой"
		}
		fmt.Printf("\n%s\n#%-2d хотим [%s]  (%s)\n   деяние: «%s»\n%s\n",
			strings.Repeat("═", 90), i+1, wantLabel, c.note, c.deed, strings.Repeat("─", 90))
		for s := 1; s <= samples; s++ {
			got, err := sel.Classify(ctx, c.deed)
			gotLabel := got
			if gotLabel == "" {
				gotLabel = "никакой"
			}
			mark := "✓"
			switch {
			case err != nil:
				mark = "✗ (err: " + err.Error() + ")"
			case got == c.want:
				pass++
			// Destructive-force deed: the sensor need only land SOMEWHERE in the force
			// cluster — the core refines the exact leaf by the grounded thing's FRACTURE
			// property (a torn letter, a bent poker), so any cluster member is correct.
			case entity.IsDestructiveForce(c.want) && entity.IsDestructiveForce(got):
				pass++
				mark = "✓≈" // right cluster, leaf left to fracture
			default:
				mark = "✗"
			}
			total++
			fmt.Printf("  ⃟%d  effect=%-12s %s\n", s, gotLabel, mark)
		}
	}
	fmt.Printf("\n%s\nИТОГ effect: ✓=%d ✗=%d из %d\n", strings.Repeat("═", 90), pass, total-pass, total)
}

