// emptySearcher builds a searcher with an empty local cache and no vector
// store: the deterministic tier finds nothing, isolating the LLM tier.
func emptySearcher() *search.EntitySearcher {
	return search.NewEntitySearcher(nil, search.DefaultEntitySearcherConfig())
}

// Probes for the "everything is an entity" frames: lazy materialization of
// stub entities, the scribe's capture of newly-introduced things, knowledge-
// grounded dialogue, and topic grounding over an entity scope. All four drive
// the exact production code paths (knowledge.GenerateMaterialization,
// knowledge.GenerateCapture, PromptBuilder.BuildDialoguePrompt + DialogueSchema,
// extraction.MentionResolver).

// entityProbes assembles the suite; registered from BuildProbes.
func entityProbes() []Probe {
	return []Probe{
		materializeProbe(),
		scribeProbe(),
		dialogueKnowledgeProbe(),
		topicGroundingProbe(),
		furnishProbe(),
	}
}

