// Fact2 aliases knowledge.Fact for terser case tables.
type Fact2 = knowledge.Fact

// physicalPropsSanity folds the runtime-mint physics invariant into a probe score:
// every author of a NEW entity (the materializer's mentions, the scribe's captures)
// must judge the two physical axes the same way the furnisher does. Two violations,
// each a small multiplicative penalty so a sane run leaves the primary score intact:
//   - LORE must stay propertyless — a legend has neither thermal response nor fracture;
//   - an ITEM must ENGAGE both axes — a discrete carriable object is a solid body, so
//     leaving thermal or fracture «нет»/empty means the model ignored an axis. A
//     SUBSTANCE (a liquid, a powder) or a FEATURE (a river, a current) may legitimately
//     be formless on the fracture axis, so they are not pressed for a mode — same
//     licence the furnisher gives a drink.
// Appends a human-readable issue per violation.
func physicalPropsSanity(score float64, drafts []knowledge.MentionDraft, out *Outcome) float64 {
	for _, d := range drafts {
		kind := entity.Kind(d.Kind)
		if !kind.IsPhysical() {
			if entity.IsThermalMode(d.Thermal) || entity.IsFractureMode(d.Fracture) || entity.IsMeans(d.Source) {
				out.Issues = append(out.Issues, "lore given physical properties: "+d.Name)
				score *= 0.8
			}
			continue
		}
		if kind == entity.KindItem {
			if !entity.IsThermalMode(d.Thermal) {
				out.Issues = append(out.Issues, "item without a thermal response: "+d.Name)
				score *= 0.9
			}
			if !entity.IsFractureMode(d.Fracture) {
				out.Issues = append(out.Issues, "item without a fracture mode: "+d.Name)
				score *= 0.9
			}
		}
	}
	return score
}

func materializeProbe() Probe {
	cases := materializeCases
	return Probe{
		Name:     "entity/materialize",
		Category: "quality",
		Reps:     len(cases) * 2, // each canon twice — materialization runs at T=0.7
		Run: func(ctx context.Context, p llm.LLMProvider, rep int) Outcome {
			tc := cases[rep%len(cases)]

			draft, resp, err := knowledge.GenerateMaterialization(ctx, p, tc.canon)
			if err != nil {
				return failFrame(resp, "generate: %v", err)
			}

			out := Outcome{Resp: resp, Pass: true, HasQuality: true, Fields: map[string]string{
				"entity":    tc.canon.EntityName,
				"backstory": draft.Backstory,
			}}

			// The kind enum is grammar-enforced; a violation means the frame broke.
			validKind := map[string]bool{"item": true, "substance": true, "feature": true, "lore": true}
			for _, m := range draft.Mentions {
				if !validKind[m.Kind] {
					return failFrame(resp, "mention kind %q outside enum", m.Kind)
				}
			}

			score := 0.0
			if n := len([]rune(draft.Backstory)); n >= 80 {
				score += 0.3
			} else {
				out.Issues = append(out.Issues, fmt.Sprintf("backstory only %d runes", n))
			}
			per := 0.3 / float64(len(tc.anchors))
			low := strings.ToLower(draft.Backstory)
			for _, anchor := range tc.anchors {
				if containsAny(low, anchor) {
					score += per
				} else {
					out.Issues = append(out.Issues, fmt.Sprintf("canon anchor %q missing", anchor))
				}
			}
			if strings.TrimSpace(draft.Interactions) != "" {
				score += 0.2
			} else {
				out.Issues = append(out.Issues, "empty interactions")
			}
			mentionsOK := true
			for _, m := range draft.Mentions {
				if strings.TrimSpace(m.Name) == "" || strings.TrimSpace(m.Gist) == "" {
					mentionsOK = false
					out.Issues = append(out.Issues, "mention with empty name/gist")
				}
			}
			if mentionsOK {
				score += 0.2
			}

			// Mentions are born WITH physics now: lore stays propertyless, a solid
			// engages the fracture axis. Sane physics leaves the score untouched.
			out.Quality = physicalPropsSanity(score, draft.Mentions, &out)
			out.Fields["mentions"] = fmt.Sprintf("%d", len(draft.Mentions))
			return out
		},
	}
}

