// scribeCase pairs a story text with the expected captures. expect holds
// substring alternates per expected entity; an empty list means the correct
// answer is "nothing new" (trap cases probe over-capturing).
type scribeCase struct {
	in     knowledge.CaptureInput
	expect []string
}

var scribeKnown = []string{
	"Тихводь", "Старый Колокол", "Хлеб из ночной муки", "Ночная мука", "Вмёрзший груз Изольта",
}

var scribeCases = []scribeCase{
	{
		in: knowledge.CaptureInput{
			Text:        "Возьми с собой фонарь из жёлчного стекла — его делал ещё старый стеклодув, до того как ушёл за реку.",
			SpeakerName: "Мирра Соль", LocationName: "Лунный Брод", KnownNames: scribeKnown,
		},
		// Сам фонарь или его материал — обе сущности валидны для этого текста.
		expect: []string{"фонар|стекл"},
	},
	{
