	},
	{
		in: knowledge.CaptureInput{
			Text:        "Говорят, под мельницей лежит жёрнов первого помола — его никто не смеет трогать.",
			SpeakerName: "Старая Кветка", LocationName: "Мельница на Сваях", KnownNames: scribeKnown,
