func dialogueKnowledgeProbe() Probe {
	cases := dialogueKnowledgeCases
	return Probe{
		Name:     "entity/dialogue-knowledge",
		Category: "quality",
		Reps:     len(cases) * 2,
		Run: func(ctx context.Context, p llm.LLMProvider, rep int) Outcome {
			tc := cases[rep%len(cases)]

			speaker := &actor.Actor{
				Identity: &actor.ActorIdentity{
					Name:  tc.speakerName,
					Race:  actor.RaceHuman,
					Class: tc.speakerClass,
					Level: 2,
					Personality: &actor.ActorPersonality{
						Warmth: 0.7, Extraversion: 0.6, Agreeableness: 0.7,
					},
				},
			}

			pb := appllm.NewPromptBuilder()
			system, user, err := pb.BuildDialoguePrompt(appllm.DialogueContext{
				Speaker:   speaker,
				Topic:     tc.topic,
				Mood:      "спокойное",
				Knowledge: tc.pack,
			})
			if err != nil {
				return failFrame(nil, "build prompt: %v", err)
			}

			// Mirror the production dialogue request exactly (dialogue_service.go).
			req := llm.Request{
				SystemPrompt: system,
				UserPrompt:   user,
				Temperature:  0.8,
				MaxTokens:    384,
				Language:     "ru",
			}
			schema, resp, err := llm.Decode[appllm.DialogueSchema](ctx, p, req)
			if err != nil {
				return failFrame(resp, "decode: %v", err)
			}

			out := Outcome{Resp: resp, Pass: true, HasQuality: true, Fields: map[string]string{
				"topic":   tc.topic,
				"content": schema.Content,
			}}

			score := 0.0
			low := strings.ToLower(schema.Content)
			per := 0.8 / float64(len(tc.anchors))
			for _, anchor := range tc.anchors {
				if containsAny(low, anchor) {
					score += per
				} else {
					out.Issues = append(out.Issues, fmt.Sprintf("knowledge anchor %q missing in reply", anchor))
				}
			}
			if len([]rune(strings.TrimSpace(schema.Content))) >= 40 {
				score += 0.2
			} else {
				out.Issues = append(out.Issues, "reply too short")
			}

			out.Quality = score
			return out
		},
	}
}

