// topicGroundingCase grounds one parsed topic against a location's entity
// scope; want is the expected candidate name ("" = the no-match sentinel).
type topicGroundingCase struct {
	mention string
	want    string
}

var

[…truncated middle of file: 4003 bytes / ~86 lines dropped to fit prompt budget…]

 none expected
}

var furnishCases = []furnishCase{
	{
		name: "Пекарня у моста", typ: "пекарня",
		desc:           "Жаркая пекарня: печь гудит у задней стены, на дощатых полках остывают караваи, в углу мешки муки, пахнет дымом и тестом.",
		wantCats:       []string{"utensil", "misc"},
		wantSource:     "огонь", // the oven is a fire source — a category-orthogonal axis
		wantConsumable: "food",  // the loaves are food — another orthogonal axis
	},
	{
		name: "Ночные Причалы", typ: "причал",
		desc:     "Дощатые мостки над тёмной водой; у свай свалены рыбацкие сети, бочки и просмолённая снасть, на столбе висит фонарь.",
		wantCats: []string{"tool", "misc"},
	},
	{
		name: "Хижина травницы", typ: "хижина",
		desc:     "Тесная каморка: под низким потолком пучки сухих трав, на полках глиняные горшочки с мазями, на столе ступка и нож.",
		wantCats: []string{"misc", "tool", "utensil"},
	},
	{
		name: "Сухой Рынок", typ: "рынок",
		desc:           "Ряды дощатых прилавков под навесами: корзины с репой и рыбой, штуки грубого холста, связки верёвки и глиняная утварь.",
		wantCats:       []string{"misc", "clothing", "utensil"},
		wantConsumable: "food", // репа и рыба — снедь
	},
	{
		// Water-source capability (W3): a place whose defining feature is standing water.
		// «Колодец» is NOT among the prompt's water illustrations (кадка/лохань/бочка/чан),
		// so passing tests that the model GENERALISED the water-source class to a new
		// instance, not memorised an example (removal-test clean). The well is judged on
		// the SOURCE axis (вода), its bucket/yoke on category (utensil/misc) — orthogonal.
		name: "Колодезный двор", typ: "двор",
		desc:       "Тесный двор за домами: посреди каменный колодец с воротом, рядом долблёная поилка для лошадей, у стены прислонены пустые вёдра и коромысло.",
		wantCats:   []string{"utensil", "misc", "tool"},
		wantSource: "вода",
	},
}

func furnishProbe() Probe {
	cases := furnishCases
	return Probe{
		Name:     "entity/furnish",
		Category: "quality",
		Reps:     len(cases) * 2, // each place twice — furnishing runs at T=0.7
		Run: func(ctx context.Context, p llm.LLMProvider, rep int) Outcome {
			tc := cases[rep%len(cases)]

			props, resp, err := knowledge.GenerateFurnishing(ctx, p, worldCanon, "", knowledge.FurnishTarget{
				Name: tc.name, Type: tc.typ, Description: tc.desc,
			})
			if err != nil {
				return failFrame(resp, "furnish: %v", err)
			}
			if len(props) == 0 {
				return failFrame(resp, "no props")
			}

			out := Outcome{Resp: resp, Pass: true, HasQuality: true, Fields: map[string]string{
				"place": tc.name,
				"count": fmt.Sprintf("%d", len(props)),
			}}

			score := 0.0
			// 4–8 things, as the prompt asks (the Go cap is 8; <4 is thin).
			if len(props) >= 4 && len(props) <= 8 {
				score += 0.3
			} else {
				out.Issues = append(out.Issues, fmt.Sprintf("count=%d (want 4-8)", len(props)))
			}
			// Every prop named with a gist, no duplicate names.
			wellFormed, seen := true, map[string]bool{}
			for _, pr := range props {
				if strings.TrimSpace(pr.Name) == "" || strings.TrimSpace(pr.Gist) == "" {
					wellFormed = false
					out.Issues = append(out.Issues, "prop with empty name/gist")
				}
				k := strings.ToLower(strings.TrimSpace(pr.Name))
				if seen[k] {
					wellFormed = false
					out.Issues = append(out.Issues, "duplicate prop name: "+pr.Name)
				}
				seen[k] = true
			}
			if wellFormed {
				score += 0.2
			}
			// At least one category plausible for THIS place (not a specific item).
			cats := map[string]bool{}
			for _, pr := range props {
				cats[strings.ToLower(strings.TrimSpace(pr.Category))] = true
			}
			placeOK := false
			for _, want := range tc.wantCats {
				if cats[want] {
					placeOK = true
					break
				}
			}
			if placeOK {
				score += 0.3
			} else {
				out.Issues = append(out.Issues, fmt.Sprintf("no place-plausible category %v present", tc.wantCats))
			}
			// Orthogonal-axis bookkeeping: which SOURCES and CONSUMABLES appeared, so the
			// place's defining one is checked below. The axes are deliberately NOT cross-
			// constrained (source ⟂ thermal: a stone oven sources fire; consumable ⟂ form:
			// a mug-of-ale is a utensil-сосуд that is consumable:drink — the very overload
			// the split removed, so a vessel-with-fracture-that-is-also-a-drink is now FINE).
			propOK, sawSource, sawConsumable := true, map[string]bool{}, map[string]bool{}
			fractured := 0
			for _, pr := range props {
				if entity.IsMeans(pr.Source) {
					sawSource[pr.Source] = true
				}
				if entity.IsConsumable(pr.Consumable) {
					sawConsumable[pr.Consumable] = true
				}
				if pr.Fracture != "" {
					fractured++
				}
			}
			// Axis CAPABILITY: a place defined by an elemental source (a bakery's oven, a
			// well-yard's well) or a consumable (a market's fare) must yield ≥1 prop carrying
			// it — proof the model USES the orthogonal axis, not that it memorised an example.
			// Folded into the property-sanity budget so a miss actually lowers the score.
			if tc.wantSource != "" && !sawSource[tc.wantSource] {
				propOK = false
				out.Issues = append(out.Issues, fmt.Sprintf("no prop supplies the place's source %q", tc.wantSource))
			}
			if tc.wantConsumable != "" && !sawConsumable[tc.wantConsumable] {
				propOK = false
				out.Issues = append(out.Issues, fmt.Sprintf("no prop carries the place's consumable %q", tc.wantConsumable))
			}
			if propOK {
				score += 0.1
			}
			// The fracture axis must be ENGAGED: a place of takeable solids should yield
			// at least one thing with a fracture mode (else the model ignored the axis).
			if fractured > 0 {
				score += 0.1
			} else {
				out.Issues = append(out.Issues, "no prop carries a fracture mode (axis ignored)")
			}

			out.Quality = score
			names := make([]string, 0, len(props))
			for _, pr := range props {
				names = append(names, fmt.Sprintf("%s[%s]", pr.Name, pr.Category))
			}
			out.Fields["props"] = strings.Join(names, ", ")
			return out
		},
	}
}

package knowledge

import (
	"context"
	"errors"
	"time"

	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	domllm "github.com/dnd-llm/dnd-llm/internal/domain/llm"
	infrallm "github.com/dnd-llm/dnd-llm/internal/infrastructure/llm"
	"github.com/dnd-llm/dnd-llm/internal/infrastructure/search"
	"github.com/google/uuid"
	"go.uber.org/zap"
)

// scribeJobTimeout bounds one whole capture job (a few extraction calls).
const scribeJobTimeout = 60 * time.Second

// NameWarmer queues names for background morphology warm-up. Optional and
// nil-safe (*morph.Service satisfies it); a newly captured or materialized
// entity hands its name over so its paradigm is ready before it first appears
// in a template.
type NameWarmer interface {
	WarmAsync(names ...string)
}

// Capture is one piece of story text produced during a turn.
type Capture struct {
	Text         string
	SpeakerID    domain.ActorID // who said it; zero for narration
	SpeakerName  string
	LocationID   domain.LocationID
	LocationName string
}

// scribeJob is one turn's worth of texts to scan.
type scribeJob struct {
	worldID    domain.WorldID
	tick       domain.Tick
	captures   []Capture
	knownNames []string // actor + location names of the scene (entity names are fetched fresh in the worker)
}

// Scribe captures the new named things the LLM itself introduces into the
// story (an NPC's line inventing «фонарь из жёлчного стекла») and turns them
// into stub entities — "everything is an entity" applied to the model's own
// creativity. It runs strictly off the turn's hot path: one background worker,
// a queue of depth one, and a busy queue drops the job with a log line — the
// GPU belongs to the player's next turn.
type Scribe struct {
	entities entity.Repository
	llm      infrallm.SchemaCompleter
	events   event.EventStore
	searcher *search.EntitySearcher
	morph    NameWarmer // optional
	logger   *zap.Logger
	jobs     chan scribeJob
}

// NewScribe builds the scribe and starts its worker. morph may be nil.
func NewScribe(
	entities entity.Repository,
	completer infrallm.SchemaCompleter,
	events event.EventStore,
	searcher *search.EntitySearcher,
	morph NameWarmer,
	logger *zap.Logger,
) *Scribe {
	if logger == nil {
		logger = zap.NewNop()
	}
	s := &Scribe{
		entities: entities,
		llm:      completer,
		events:   events,
		searcher: searcher,
		morph:    morph,
		logger:   logger,
		jobs:     make(chan scribeJob, 1),
	}
	go s.worker()
	return s
}

// CaptureAsync enqueues a turn's texts for scanning. Non-blocking: when the
// worker is still busy with the previous turn, the job is skipped — captures
// are best-effort enrichment, not bookkeeping the game depends on.
func (s *Scribe) CaptureAsync(worldID domain.WorldID, tick domain.Tick, captures []Capture, knownNames []string) {
	if s == nil || len(captures) == 0 {
		return
	}
	job := scribeJob{worldID: worldID, tick: tick, captures: captures, knownNames: knownNames}
	select {
	case s.jobs <- job:
	default:
		s.logger.Info("scribe busy; skipping turn captures", zap.Int("captures", len(captures)))
	}
}

func (s *Scribe) worker() {
	for job := range s.jobs {
		ctx, cancel := context.WithTimeout(context.Background(), scribeJobTimeout)
		s.process(ctx, job)
		cancel()
	}
}

// process scans each capture and persists genuinely new entities.
func (s *Scribe) process(ctx context.Context, job scribeJob) {
	known := s.knownNames(ctx, job)

	for _, capture := range job.captures {
		if capture.Text == "" {
			continue
		}
		// Only a CHARACTER's spoken words introduce things into the world.
		// Narration (zero speaker) merely describes what the player attempted —
		// capturing it would let the player invent objects into existence
		// («беру со стола драконье яйцо») with the narrator as accomplice.
		if capture.SpeakerID.IsZero() {
			continue
		}
		drafts, _, err := GenerateCapture(ctx, s.llm, CaptureInput{
			Text:         capture.Text,
			SpeakerName:  capture.SpeakerName,
			LocationName: capture.LocationName,
			KnownNames:   known,
		})
		if err != nil {
			s.logger.Warn("scribe capture failed", zap.Error(err))
			continue
		}
		for _, draft := range drafts {
			if name := s.absorb(ctx, job, capture, draft, known); name != "" {
				known = append(known, name)
			}
		}
	}
}

// knownNames assembles the "do not capture" list: every world entity with its
// aliases (fresh from the store — earlier turns may have added some) plus the
// scene's actor and location names supplied by the caller.
func (s *Scribe) knownNames(ctx context.Context, job scribeJob) []string {
	names := append([]string{}, job.knownNames...)
	if list, err := s.entities.ListByWorld(ctx, job.worldID); err == nil {
		for _, e := range list {
			names = append(names, e.Name)
			names = append(names, e.Aliases...)
		}
	}
	return names
}

// absorb persists one captured draft unless it already exists. Returns the
// new entity's name, or "" when nothing was created.
func (s *Scribe) absorb(ctx context.Context, job scribeJob, capture Capture, draft MentionDraft, known []string) string {
	if draft.Name == "" || draft.Gist == "" {
		return ""
	}

	// A captured name must originate from the spoken line: no stem anchor in
	// the text means the model invented it («Мерцающий перочиво»), not heard it.
	if !AnchoredName(draft.Name, capture.Text) {
		s.logger.Info("scribe capture not anchored in the line; dropped",
			zap.String("name", draft.Name), zap.String("speaker", capture.SpeakerName))
		return ""
	}

	// Deduplicate against the whole corpus (entities, actors, locations): the
	// prompt asks the model not to re-capture known things, but the guarantee
	// lives here. Two tiers: word-level canonicalization against every known
	// name and alias («Поток Тихводь» IS «Тихводь», «Росатомный Прилив» IS
	// «Росатый Прилив» — the search cascade scores both below its bar), then
	// the search cascade for phrasings word matching can't see.
	if canon, ok := CanonicalName(draft.Name, known); ok {
		s.logger.Debug("scribe capture is a known thing; dropped",
			zap.String("name", draft.Name), zap.String("canon", canon))
		return ""
	}
	if s.exists(ctx, job.worldID, draft.Name) {
		return ""
	}

	stub := &entity.Entity{
		ID:        domain.NewEntityID(),
		WorldID:   job.worldID,
		Kind:      entity.Kind(draft.Kind),
		Name:      draft.Name,
		Gist:      draft.Gist,
		Lifecycle: entity.LifecycleStub,
		Origin:    entity.OriginScribe,
	}
	// Born WITH its physics: the scribe that heard this thing named also judged how it
	// answers heat, yields to force, holds liquid, and what elemental means it SUPPLIES
	// (a captured well sources water, a brazier fire) — a thing caught from talk is a full
	// physical citizen of the world, not a propertyless husk (lore is skipped inside).
	stub.AuthorPhysics(draft.Thermal, draft.Fracture, draft.Containment, draft.Source, draft.Consumable)
	if err := s.entities.Save(ctx, stub); err != nil {
		if errors.Is(err, entity.ErrDuplicateName) {
			// The DB floor under capture races: the thing already exists — the
			// semantic dedupe above missed it, the constraint did not.
			s.logger.Debug("scribe capture already exists (unique floor); dropped", zap.String("name", draft.Name))
			return ""
		}
		s.logger.Warn("scribe stub save failed", zap.String("name", draft.Name), zap.Error(err))
		return ""
	}

	// Scope: the speaker knows what they said; the thing was spoken of here.
	if !capture.SpeakerID.IsZero() {
		_ = s.entities.AddLink(ctx, entity.Link{
			EntityID: stub.ID, LinkType: entity.LinkKnows,
			SubjectType: entity.SubjectActor, SubjectID: capture.SpeakerID.String(),
		})
	}
	if !capture.LocationID.IsZero() {
		_ = s.entities.AddLink(ctx, entity.Link{
			EntityID: stub.ID, LinkType: entity.LinkLocatedAt,
			SubjectType: entity.SubjectLocation, SubjectID: capture.LocationID.String(),
		})
	}

	s.journal(ctx, stub, capture, job.tick)
	s.index(ctx, job.worldID, stub)
	if s.morph != nil {
		s.morph.WarmAsync(stub.Name)
	}

	s.logger.Info("scribe captured a new entity",
		zap.String("name", stub.Name),
		zap.String("kind", string(stub.Kind)),
		zap.String("speaker", capture.SpeakerName),
	)
	return stub.Name
}

// exists reports whether the name confidently matches anything already known.
func (s *Scribe) exists(ctx context.Context, worldID domain.WorldID, name string) bool {
	if s.searcher == nil {
		return false
	}
	wid, err := uuid.Parse(worldID.String())
	if err != nil {
		return false
	}
	resp, err := s.searcher.Search(ctx, search.SearchRequest{
		Query:      name,
		WorldID:    &wid,
		MaxResults: 1,
	})
	if err != nil || len(resp.Results) == 0 {
		return false
	}
	return float64(resp.Results[0].Score) >= dedupeAcceptScore
}

func (s *Scribe) journal(ctx context.Context, e *entity.Entity, capture Capture, tick domain.Tick) {
	if s.events == nil {
		return
	}
	if tick.IsZero() {
		tick = 1
	}
	var src *domain.ActorID
	if !capture.SpeakerID.IsZero() {
		id := capture.SpeakerID
		src = &id
	}
	evt := event.NewGameEvent(
		event.EventTypeEntityCreated,
		domain.ActorID(e.WorldID), domain.LocationID(e.WorldID), e.WorldID, tick,
		event.EntityLifecycleEventData{
			EntityID:      e.ID.String(),
			Name:          e.Name,
			Kind:          string(e.Kind),
			Gist:          e.Gist,
			Origin:        string(e.Origin),
			SourceActorID: src,
		},
	)
	if err := s.events.Append(ctx, evt); err != nil {
		s.logger.Warn("scribe journal append failed", zap.String("entity", e.Name), zap.Error(err))
	}
}

func (s *Scribe) index(ctx context.Context, worldID domain.WorldID, e *entity.Entity) {
	if s.searcher == nil {
		return
	}
	searchables := []domllm.SearchableEntity{searchableFromEntity(e)}
	s.searcher.AddToLocalCache(worldID.String(), searchables)

	wid, err := uuid.Parse(worldID.String())
	if err != nil {
		return
	}
	if err := s.searcher.IndexEntities(ctx, searchables, &wid, nil); err != nil {
		s.logger.Warn("scribe vector indexing failed", zap.Error(err))
	}
}

package knowledge

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"

	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/actor"
	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	domllm "github.com/dnd-llm/dnd-llm/internal/domain/llm"
	"github.com/dnd-llm/dnd-llm/internal/domain/world"
	infrallm "github.com/dnd-llm/dnd-llm/internal/infrastructure/llm"
	"github.com/dnd-llm/dnd-llm/internal/infrastructure/persistence"
	"github.com/dnd-llm/dnd-llm/internal/infrastructure/search"
	"github.com/google/uuid"
	"go.uber.org/zap"
)

// materializeTimeout bounds the synchronous first-touch call. The live stack
// (llmbench entity/materialize) shows p50 ≈ 13s, p95 ≈ 15s at the 420-rune
// budget; beyond the cap the entity honestly stays a stub and the turn
// proceeds on its gist.
const materializeTimeout = 25 * time.Second

// dedupeAcceptScore is the search score at which a generated mention is
// considered an existing entity rather than a new stub.
const dedupeAcceptScore = 0.9

// Materializer turns stub entities into materialized ones: one grammar-framed
// LLM call produces the backstory, interactions and new mentions; mentions are
// deduplicated against the corpus and born as stubs; everything is persisted,
// journaled and indexed.
type Materializer struct {
	entities entity.Repository
	worlds   world.WorldRepository
	actors   actor.ActorRepository
	llm      infrallm.SchemaCompleter
	events   event.EventStore
	searcher *search.EntitySearcher
	graph    persistence.GraphStore // optional, best-effort mirror
	morph    NameWarmer             // optional
	logger   *zap.Logger

	// Background materialization: a turn that touches several first-seen stubs
	// must not serialize an LLM call per stub into its own latency. Extras beyond
	// the per-turn synchronous budget are enqueued here and deepened by a single
	// worker, ready by a later touch (the stub's gist shows immediately meanwhile).
	queue    chan domain.EntityID
	inflight sync.Map // domain.EntityID -> struct{}, dedups queued/in-progress stubs
}

// asyncQueueSize bounds the background materialization backlog. A turn rarely
// touches more than a handful of fresh stubs; this is generous headroom before
// the queue sheds load (a shed stub simply materializes on a later touch).
const asyncQueueSize = 64

// NewMaterializer builds a Materializer. graph and morph may be nil.
func NewMaterializer(
	entities entity.Repository,
	worlds world.WorldRepository,
	actors actor.ActorRepository,
	completer infrallm.SchemaCompleter,
	events event.EventStore,
	searcher *search.EntitySearcher,
	graph persistence.GraphStore,
	morph NameWarmer,
	logger *zap.Logger,
) *Materializer {
	if logger == nil {
		logger = zap.NewNop()
	}
	m := &Materializer{
		entities: entities, worlds: worlds, actors: actors,
		llm: completer, events: events, searcher: searcher, graph: graph,
		morph: morph, logger: logger,
		queue: make(chan domain.EntityID, asyncQueueSize),
	}
	go m.drainQueue()
	return m
}

// AsyncMaterialize schedules a stub for background materialization instead of
// blocking the caller's turn. The stub's gist is what the player sees now; its
// full backstory lands by a later touch. A stub already queued/in-progress, or no
// longer a stub, is a no-op (dedup), so repeated touches across ticks never pile
// up duplicate work. Best-effort: a full queue sheds the request (a later touch
// re-enqueues).
func (m *Materializer) AsyncMaterialize(e *entity.Entity) {
	if e == nil || e.Lifecycle != entity.LifecycleStub {
		return
	}
	if _, loaded := m.inflight.LoadOrStore(e.ID, struct{}{}); loaded {
		return
	}
	select {
	case m.queue <- e.ID:
	default:
		m.inflight.Delete(e.ID) // backlog full; let a later touch retry
	}
}

// drainQueue is the single background worker. One materialization at a time keeps
// the LLM pressure bounded and preserves the turn-based feel (deepening trails
// play by a beat rather than thundering in parallel).
func (m *Materializer) drainQueue() {
	for id := range m.queue {
		m.materializeInBackground(id)
	}
}

// materializeInBackground re-fetches the stub fresh (another path may have
// materialized it meanwhile) and gives it its story on a detached context, so the
// work survives the turn that scheduled it ending. Failure is non-fatal: the
// entity honestly stays a stub on its gist.
func (m *Materializer) materializeInBackground(id domain.EntityID) {
	defer m.inflight.Delete(id)
	e, err := m.entities.FindByID(context.Background(), id)
	if err != nil || e == nil || e.Lifecycle != entity.LifecycleStub {
		return
	}
	if _, err := m.Materialize(context.Background(), e); err != nil {
		m.logger.Debug("background materialization failed",
			zap.String("entity", e.Name), zap.Error(err))
	}
}

// Materialize gives a stub its own story. Returns the updated entity; on any
// failure the caller keeps the stub and its gist (honest degradation).
func (m *Materializer) Materialize(ctx context.Context, e *entity.Entity) (*entity.Entity, error) {
	if e.Lifecycle != entity.LifecycleStub {
		return e, nil
	}

	ctx, cancel := context.WithTimeout(ctx, materializeTimeout)
	defer cancel()

	canon, tick, err := m.assembleCanon(ctx, e)
	if err != nil {
		return nil, fmt.Errorf("assemble canon: %w", err)
	}

	draft, _, err := GenerateMaterialization(ctx, m.llm, canon)
	if err != nil {
		return nil, err
	}

	born := m.absorbMentions(ctx, e, draft, tick)

	e.Backstory = draft.Backstory
	e.SetInteractions(draft.Interactions)
	e.Lifecycle = entity.LifecycleMaterialized
	if err := m.entities.Save(ctx, e); err != nil {
		return nil, fmt.Errorf("save materialized entity: %w", err)
	}

	m.journal(ctx, e, event.EventTypeEntityMaterialized, nil, tick)
	m.index(ctx, e.WorldID, append(born, e))
	m.mirror(ctx, e, born)

	m.logger.Info("entity materialized",
		zap.String("entity", e.Name),
		zap.Int("new_mentions", len(born)),
	)
	return e, nil
}

// assembleCanon gathers the facts the generation must not contradict, plus
// the world's current tick for journal events (validation rejects tick 0).
func (m *Materializer) assembleCanon(ctx context.Context, e *entity.Entity) (Canon, domain.Tick, error) {
	canon := Canon{
		EntityName: e.Name,
		EntityKind: string(e.Kind),
		Gist:       e.Gist,
	}

	tick := domain.Tick(1)
	if w, err := m.worlds.FindByID(ctx, e.WorldID); err == nil {
		canon.WorldDescription = w.Description
		canon.Era = w.Era
		canon.CityName = w.Name
		if !w.GameTime.Tick.IsZero() {
			tick = w.GameTime.Tick
		}
	}

	if linked, err := m.entities.ListLinked(ctx, e.ID, entity.LinkMentions); err == nil {
		for _, le := range linked {
			if len(canon.MentionedIn) == relatedMax {
				break
			}
			canon.MentionedIn = append(canon.MentionedIn, Fact{Name: le.Name, Gist: le.Gist})
		}
	}

	if links, err := m.entities.ListLinks(ctx, e.ID); err == nil {
		for _, l := range links {
			if l.LinkType != entity.LinkOwner || l.SubjectType != entity.SubjectActor {
				continue
			}
			if owner, err := m.actors.FindByID(ctx, domain.ActorID(l.SubjectID)); err == nil && owner.Identity != nil {
				canon.OwnerNote = owner.Identity.Name
				if owner.Identity.Background != "" {
					canon.OwnerNote += " — " + owner.Identity.Background
				}
			}
			break
		}
	}
	return canon, tick, nil
}

// absorbMentions turns the draft's mentions into links: a mention anchored in
// the generated backstory and colliding with a known name links to (or is
// dropped for) that canon; a confident semantic match links to the existing
// entity; anything genuinely new is born as a stub (origin=materializer,
// town-knowledge scope — the story has been told aloud). Returns the newborn
// stubs. This is the net that used to be missing — «Росатомный Прилив» was
// born here as a distorted twin of the canon «Росатый Прилив».
func (m *Materializer) absorbMentions(ctx context.Context, parent *entity.Entity, draft MaterializeDraft, tick domain.Tick) []*entity.Entity {
	entityByName, personNames := m.knownNameIndex(ctx, parent.WorldID)
	sourceText := draft.Backstory + " " + draft.Interactions

	var born []*entity.Entity
	for _, mention := range draft.Mentions {
		if mention.Name == "" || mention.Gist == "" {
			continue
		}

		// A mention must originate from the story that introduced it.
		if !AnchoredName(mention.Name, sourceText) {
			m.logger.Info("mention not anchored in the backstory; dropped",
				zap.String("mention", mention.Name), zap.String("parent", parent.Name))
			continue
		}

		// Word-level canonicalization: a collision with a known entity links
		// to the canon instead of birthing a distorted twin; a collision with
		// a person or place drops the mention — people are not thing-entities.
		var targetID domain.EntityID
		if canon, ok := CanonicalName(mention.Name, keysOf(entityByName)); ok {
			targetID = entityByName[canon]
			m.logger.Debug("mention canonicalized",
				zap.String("mention", mention.Name), zap.String("canon", canon))
		} else if _, ok := CanonicalName(mention.Name, personNames); ok {
			continue
		}

		if targetID == "" {
			targetID = m.findExisting(ctx, parent.WorldID, mention.Name)
		}
		if targetID == "" {
			// Born DORMANT: a mention stub gets NO knows|world link — knowledge
			// spreads only through what is actually SPOKEN (the scribe catches
			// said words; an unspoken LLM draft is not town knowledge). The stub
			// stays reachable through its mentions link — the snowball's 1-hop —
			// and matures only when the player pulls that thread. This is what
			// stopped «Долгая Правда»-style phantoms from flooding NPC chatter.
			stub := &entity.Entity{
				ID:        domain.NewEntityID(),
				WorldID:   parent.WorldID,
				Kind:      entity.Kind(mention.Kind),
				Name:      mention.Name,
				Gist:      mention.Gist,
				Lifecycle: entity.LifecycleStub,
				Origin:    entity.OriginMaterializer,
			}
			// Born WITH its physics: the author that named this mention judged how it
			// answers heat, yields to force, holds liquid, and what elemental means it
			// SUPPLIES (a mentioned well sources water, a hearth fire) — so a force/fire/
			// water deed on it resolves the same as on any authored thing — no second-class
			// runtime births (lore is skipped inside).
			stub.AuthorPhysics(mention.Thermal, mention.Fracture, mention.Containment, mention.Source, mention.Consumable)
			switch err := m.entities.Save(ctx, stub); {
			case err == nil:
				m.journal(ctx, stub, event.EventTypeEntityCreated, nil, tick)
				if m.morph != nil {
					m.morph.WarmAsync(stub.Name)
				}
				born = append(born, stub)
				targetID = stub.ID
			case errors.Is(err, entity.ErrDuplicateName):
				// A twin won the race to this name — link to it instead.
				if targetID = m.findExisting(ctx, parent.WorldID, mention.Name); targetID == "" {
					continue
				}
			default:
				m.logger.Warn("saving mention stub failed", zap.String("name", mention.Name), zap.Error(err))
				continue
			}
		}

		if err := m.entities.AddLink(ctx, entity.Link{
			EntityID:    targetID,
			LinkType:    entity.LinkMentions,
			SubjectType: entity.SubjectEntity,
			SubjectID:   parent.ID.String(),
		}); err != nil {
			m.logger.Warn("linking mention failed", zap.String("name", mention.Name), zap.Error(err))
		}
	}
	return born
}

// knownNameIndex assembles the canonicalization corpus: every world entity
// (with aliases) mapped to its ID, plus the names of people — a mention
// colliding with the miller must not spawn a thing-entity shadowing him.
func (m *Materializer) knownNameIndex(ctx context.Context, worldID domain.WorldID) (map[string]domain.EntityID, []string) {
	entityByName := map[string]domain.EntityID{}
	if list, err := m.entities.ListByWorld(ctx, worldID); err == nil {
		for _, e := range list {
			entityByName[e.Name] = e.ID
			for _, a := range e.Aliases {
				entityByName[a] = e.ID
			}
		}
	}
	var people []string
	if m.actors != nil {
		if actors, err := m.actors.FindByWorld(ctx, worldID); err == nil {
			for _, a := range actors {
				if a.Identity == nil {
					continue
				}
				people = append(people, a.Identity.Name)
				people = append(people, a.Identity.Aliases...)
			}
		}
	}
	return entityByName, people
}

// keysOf projects the name index to its names for collision scanning.
func keysOf(m map[string]domain.EntityID) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	return out
}

// findExisting checks whether a mention already names a known world entity.
func (m *Materializer) findExisting(ctx context.Context, worldID domain.WorldID, name string) domain.EntityID {
	if m.searcher == nil {
		return ""
	}
	wid, err := uuid.Parse(worldID.String())
	if err != nil {
		return ""
	}
	resp, err := m.searcher.Search(ctx, search.SearchRequest{
		Query:      name,
		WorldID:    &wid,
		MaxResults: 1,
	})
	if err != nil || len(resp.Results) == 0 {
		return ""
	}
	top := resp.Results[0]
	if float64(top.Score) < dedupeAcceptScore {
		return ""
	}
	// Actors and locations also count as "already exists" — a mention of the
	// miller must not spawn a thing-entity shadowing him — but only entity
	// types may be linked as mentions.
	switch top.Entity.Type {
	case domllm.TypeItem, domllm.TypeFeature, domllm.TypeLore:
		return domain.EntityID(top.Entity.ID)
	default:
		return domain.EntityID("") // exists, but not a world entity: just don't link
	}
}

// journal appends the lifecycle event, world-as-actor (the reseed-marker
// pattern); best-effort — the entities table is the state of record.
func (m *Materializer) journal(ctx context.Context, e *entity.Entity, et event.EventType, sourceActor *domain.ActorID, tick domain.Tick) {
	if m.events == nil {
		return
	}
	evt := event.NewGameEvent(
		et,
		domain.ActorID(e.WorldID), domain.LocationID(e.WorldID), e.WorldID, tick,
		event.EntityLifecycleEventData{
			EntityID:      e.ID.String(),
			Name:          e.Name,
			Kind:          string(e.Kind),
			Gist:          e.Gist,
			Origin:        string(e.Origin),
			SourceActorID: sourceActor,
		},
	)
	if err := m.events.Append(ctx, evt); err != nil {
		m.logger.Warn("entity journal append failed", zap.String("entity", e.Name), zap.Error(err))
	}
}

// index registers entities in the search corpus: the local cache immediately,
// the vector index best-effort.
func (m *Materializer) index(ctx context.Context, worldID domain.WorldID, entities []*entity.Entity) {
	if m.searcher == nil || len(entities) == 0 {
		return
	}
	searchables := make([]domllm.SearchableEntity, 0, len(entities))
	for _, e := range entities {
		searchables = append(searchables, searchableFromEntity(e))
	}
	m.searcher.AddToLocalCache(worldID.String(), searchables)

	wid, err := uuid.Parse(worldID.String())
	if err != nil {
		return
	}
	if err := m.searcher.IndexEntities(ctx, searchables, &wid, nil); err != nil {
		m.logger.Warn("entity vector indexing failed", zap.Error(err))
	}
}

// mirror writes the graph reflection of the materialization, best-effort.
func (m *Materializer) mirror(ctx context.Context, e *entity.Entity, born []*entity.Entity) {
	if m.graph == nil {
		return
	}
	upsert := func(ent *entity.Entity) {
		node := persistence.GraphNode{
			ID:     persistence.NodeID(ent.ID),
			Type:   persistence.NodeTypeEntity,
			Labels: []string{string(ent.Kind)},
			Properties: map[string]interface{}{
				"name": ent.Name,
				"gist": ent.Gist,
				"kind": string(ent.Kind),
			},
		}
		if err := m.graph.AddNode(ctx, node); err != nil {
			if uerr := m.graph.UpdateNode(ctx, node.ID, node.Properties); uerr != nil {
				m.logger.Warn("entity graph mirror failed", zap.String("entity", ent.Name), zap.Error(uerr))
			}
		}
	}
	upsert(e)
	for _, stub := range born {
		upsert(stub)
		if err := m.graph.AddEdge(ctx, persistence.GraphEdge{
			FromID: persistence.NodeID(e.ID),
			ToID:   persistence.NodeID(stub.ID),
			Type:   persistence.EdgeMentions,
			Weight: 1.0,
		}); err != nil {
			m.logger.Warn("entity graph edge failed", zap.String("entity", stub.Name), zap.Error(err))
		}
	}
}

// searchableFromEntity mirrors extraction.SearchableFromEntity locally to
// avoid an application-layer import cycle (extraction imports knowledge for
// nothing today, but the indexer side already owns the world reindex; this
// covers the incremental path).
func searchableFromEntity(e *entity.Entity) domllm.SearchableEntity {
	var st domllm.SearchableType
	switch e.Kind {
	case entity.KindFeature:
		st = domllm.TypeFeature
	case entity.KindLore:
		st = domllm.TypeLore
	default:
		st = domllm.TypeItem
	}
	return domllm.SearchableEntity{
		ID:          string(e.ID),
		Name:        e.Name,
		Aliases:     e.Aliases,
		Type:        st,
		Subtype:     string(e.Kind),
		Description: e.Gist,
		Category:    st.ToCategory(),
		IsKnown:     true,
	}
}

