func scribeProbe() Probe {
	cases := scribeCases
	return Probe{
		Name:     "entity/scribe",
		Category: "quality",
		Reps:     len(cases),
		Run: func(ctx context.Context, p llm.LLMProvider, rep int) Outcome {
			tc := cases[rep%len(cases)]

			got, resp, err := knowledge.GenerateCapture(ctx, p, tc.in)
			if err != nil {
				return failFrame(resp, "capture: %v", err)
			}

			out := Outcome{Resp: resp, Pass: true, HasQuality: true, Fields: map[string]string{
				"text": tc.in.Text,
			}}
			names := make([]string, 0, len(got))
			for _, g := range got {
				names = append(names, g.Name)
			}
			out.Fields["captured"] = strings.Join(names, "; ")

			// Quality = F1 over the expected set; for trap cases (expect nothing)
			// quality is binary silence.
			if len(tc.expect) == 0 {
				if len(got) == 0 {
					out.Quality = 1
				} else {
					out.Issues = append(out.Issues, fmt.Sprintf("captured %v, expected nothing", names))
				}
				return out
			}

			matched := 0
			for _, want := range tc.expect {
				found := false
				for _, g := range got {
					if containsAny(strings.ToLower(g.Name), want) {
						found = true
						break
					}
				}
				if found {
					matched++
				} else {
					out.Issues = append(out.Issues, fmt.Sprintf("missed %q", want))
				}
			}
			spurious := 0
			for _, g := range got {
				ok := false
				for _, want := range tc.expect {
					if containsAny(strings.ToLower(g.Name), want) {
						ok = true
						break
					}
				}
				if !ok {
					spurious++
					out.Issues = append(out.Issues, fmt.Sprintf("spurious capture %q", g.Name))
				}
			}

			recall := float64(matched) / float64(len(tc.expect))
			precision := 1.0
			if len(got) > 0 {
				precision = float64(len(got)-spurious) / float64(len(got))
			}
			if recall+precision > 0 {
				out.Quality = 2 * recall * precision / (recall + precision)
			}
			// Captures are born WITH physics now: a caught solid engages the fracture
			// axis, a caught legend stays propertyless. Sane physics leaves F1 intact.
			out.Quality = physicalPropsSanity(out.Quality, got, &out)
			return out
		},
	}
}

