func furnishProbe() Probe {
	cases := furnishCases
	return Probe{
		Name:     "entity/furnish",
		Category: "quality",
		Reps:     len(cases) * 2, // each place twice — furnishing runs at T=0.7
		Run: func(ctx context.Context, p llm.LLMProvider, rep int) Outcome {
			tc := cases[rep%len(cases)]

			props, resp, err := knowledge.GenerateFurnishing(ctx, p, worldCanon, "", knowledge.FurnishTarget{
				Name: tc.name, Type: tc.typ, Description: tc.desc,
			})
			if err != nil {
				return failFrame(resp, "furnish: %v", err)
			}
			if len(props) == 0 {
				return failFrame(resp, "no props")
			}

			out := Outcome{Resp: resp, Pass: true, HasQuality: true, Fields: map[string]string{
				"place": tc.name,
				"count": fmt.Sprintf("%d", len(props)),
			}}

			score := 0.0
			// 4–8 things, as the prompt asks (the Go cap is 8; <4 is thin).
			if len(props) >= 4 && len(props) <= 8 {
				score += 0.3
			} else {
				out.Issues = append(out.Issues, fmt.Sprintf("count=%d (want 4-8)", len(props)))
			}
			// Every prop named with a gist, no duplicate names.
			wellFormed, seen := true, map[string]bool{}
			for _, pr := range props {
				if strings.TrimSpace(pr.Name) == "" || strings.TrimSpace(pr.Gist) == "" {
					wellFormed = false
					out.Issues = append(out.Issues, "prop with empty name/gist")
				}
				k := strings.ToLower(strings.TrimSpace(pr.Name))
				if seen[k] {
					wellFormed = false
					out.Issues = append(out.Issues, "duplicate prop name: "+pr.Name)
				}
				seen[k] = true
			}
			if wellFormed {
				score += 0.2
			}
			// At least one category plausible for THIS place (not a specific item).
			cats := map[string]bool{}
			for _, pr := range props {
				cats[strings.ToLower(strings.TrimSpace(pr.Category))] = true
			}
			placeOK := false
			for _, want := range tc.wantCats {
				if cats[want] {
					placeOK = true
					break
				}
			}
			if placeOK {
				score += 0.3
			} else {
				out.Issues = append(out.Issues, fmt.Sprintf("no place-plausible category %v present", tc.wantCats))
			}
			// Orthogonal-axis bookkeeping: which SOURCES and CONSUMABLES appeared, so the
			// place's defining one is checked below. The axes are deliberately NOT cross-
			// constrained (source ⟂ thermal: a stone oven sources fire; consumable ⟂ form:
			// a mug-of-ale is a utensil-сосуд that is consumable:drink — the very overload
			// the split removed, so a vessel-with-fracture-that-is-also-a-drink is now FINE).
			propOK, sawSource, sawConsumable := true, map[string]bool{}, map[string]bool{}
			fractured := 0
			for _, pr := range props {
				if entity.IsMeans(pr.Source) {
					sawSource[pr.Source] = true
				}
				if entity.IsConsumable(pr.Consumable) {
					sawConsumable[pr.Consumable] = true
				}
				if pr.Fracture != "" {
					fractured++
				}
			}
			// Axis CAPABILITY: a place defined by an elemental source (a bakery's oven, a
			// well-yard's well) or a consumable (a market's fare) must yield ≥1 prop carrying
			// it — proof the model USES the orthogonal axis, not that it memorised an example.
			// Folded into the property-sanity budget so a miss actually lowers the score.
			if tc.wantSource != "" && !sawSource[tc.wantSource] {
				propOK = false
				out.Issues = append(out.Issues, fmt.Sprintf("no prop supplies the place's source %q", tc.wantSource))
			}
			if tc.wantConsumable != "" && !sawConsumable[tc.wantConsumable] {
				propOK = false
				out.Issues = append(out.Issues, fmt.Sprintf("no prop carries the place's consumable %q", tc.wantConsumable))
			}
			if propOK {
				score += 0.1
			}
			// The fracture axis must be ENGAGED: a place of takeable solids should yield
			// at least one thing with a fracture mode (else the model ignored the axis).
			if fractured > 0 {
				score += 0.1
			} else {
				out.Issues = append(out.Issues, "no prop carries a fracture mode (axis ignored)")
			}

			out.Quality = score
			names := make([]string, 0, len(props))
			for _, pr := range props {
				names = append(names, fmt.Sprintf("%s[%s]", pr.Name, pr.Category))
			}
			out.Fields["props"] = strings.Join(names, ", ")
			return out
		},
	}
}

package entity

import "testing"

// thingWithFracture builds a thing whose fracture-mode property is set.
func thingWithFracture(mode string) *Entity {
	e := &Entity{Name: "вещь", Kind: KindItem}
	e.SetFracture(mode)
	return e
}

// TestRefineForceEffect: the sensor lands anywhere in the destructive-force cluster by
// the deed's gross intent; the core snaps it to the leaf the thing's FRACTURE PROPERTY
// dictates. This is where #4 (a torn letter must not «shatter») and #8 (a bent poker
// must not «break») are fixed deterministically — the leaf the 4B cannot pick.
func TestRefineForceEffect(t *testing.T) {
	cases := []struct {
		name   string
		mode   string
		sensor string // the (possibly wrong) leaf the LLM picked
		want   string // the fracture-correct leaf the core commits
	}{
		// #4: a fibrous thing the sensor read as «разбить» tears, never shatters.
		{"волокнистое рвётся, не бьётся", FractureFibrous, EffectShatter, EffectTear},
		// #8: a ductile thing the sensor read as «сломать» bends — DAMAGED, not RUINED.
		{"ковкое гнётся, не ломается", FractureDuctile, EffectBreak, EffectBend},
		// brittle shatters whatever force-verb was used (even a bend-intent).
		{"хрупкое бьётся в осколки", FractureBrittle, EffectTear, EffectShatter},
		{"хрупкое: согнуть всё равно бьётся", FractureBrittle, EffectBend, EffectShatter},
		// rigid breaks; friable crushes; pliable crumples.
		{"жёсткое ломается", FractureRigid, EffectShatter, EffectBreak},
		{"рыхлое крошится", FractureFriable, EffectCrush, EffectCrush},
		{"мягкое сминается", FracturePliable, EffectShatter, EffectCrumple},
	}
	for _, c := range cases {
		got := RefineForceEffect(c.sensor, thingWithFracture(c.mode))
		if got != c.want {
			t.Errorf("%s: RefineForceEffect(%q, %s) = %q, want %q", c.name, c.sensor, c.mode, got, c.want)
		}
	}
}

// TestRefineForceEffect_Passthrough: the refiner touches ONLY the destructive-force
// cluster of a thing WITH a fracture mode — a specific deed, a non-force effect, or a
// thing with no fracture mode keeps the sensor's pick.
func TestRefineForceEffect_Passthrough(t *testing.T) {
	cases := []struct {
		name  string
		key   string
		thing *Entity
	}{
		{"не-force эффект не трогаем (облить)", EffectSoak, thingWithFracture(FractureDuctile)},
		{"специфичное деяние проходит (проткнуть)", EffectPierce, thingWithFracture(FractureRigid)},
		{"царапина проходит (поцарапать)", EffectScratch, thingWithFracture(FractureBrittle)},
		{"без режима излома — пик сенсора как есть", EffectShatter, &Entity{Name: "вещь", Kind: KindItem}},
		{"nil-вещь — пик сенсора как есть", EffectBreak, nil},
	}
	for _, c := range cases {
		if got := RefineForceEffect(c.key, c.thing); got != c.key {
			t.Errorf("%s: RefineForceEffect(%q) = %q, want passthrough %q", c.name, c.key, got, c.key)
		}
	}
}

// TestRefinedSeverityEmergesFromCatalogue: the severity is not asserted by the refiner —
// it FALLS OUT of the leaf's catalogue Integrity. A ductile thing bending is Damaged
// (still stands); a brittle one shattering is Ruined. This is why #8 matters
// mechanically: the wrong leaf would raise a load-bearing thing to Ruined and wrongly
// close its location.
func TestRefinedSeverityEmergesFromCatalogue(t *testing.T) {
	if EffectIntegrity(RefineForceEffect(EffectBreak, thingWithFracture(FractureDuctile))) != IntegrityDamaged {
		t.Error("a ductile thing under force must end DAMAGED (bent), not RUINED")
	}
	if EffectIntegrity(RefineForceEffect(EffectTear, thingWithFracture(FractureBrittle))) != IntegrityRuined {
		t.Error("a brittle thing under force must end RUINED (shattered)")
	}
}

// TestAuthorPhysics: the one mint primitive every runtime author goes through records
// both axes for a PHYSICAL kind (item/substance/feature) and SKIPS immaterial lore — a
// legend has no body to burn or break, so it must stay propertyless even if an author
// (or a hallucinating model) hands it a flammable=true / a fracture mode.
func TestAuthorPhysics(t *testing.T) {
	for _, k := range []Kind{KindItem, KindSubstance, KindFeature} {
		e := &Entity{Name: "вещь", Kind: k}
		e.AuthorPhysics(ThermalIgnites, FractureRigid, ContainmentSolid, MeansFire, ConsumableFood)
		if !e.CatchesFire() {
			t.Errorf("%s: AuthorPhysics(горит) must make it catch fire", k)
		}
		if e.StateText(StateFracture) != FractureRigid {
			t.Errorf("%s: AuthorPhysics must record the fracture mode", k)
		}
		if !e.Supplies(MeansFire) {
			t.Errorf("%s: AuthorPhysics must record the source means", k)
		}
		if e.Consumable() != ConsumableFood {
			t.Errorf("%s: AuthorPhysics must record the consumable mode", k)
		}
	}
	lore := &Entity{Name: "предание", Kind: KindLore}
	lore.AuthorPhysics(ThermalIgnites, FractureRigid, ContainmentVessel, MeansFire, ConsumableFood)
	if lore.StateText(StateThermal) != "" || lore.StateText(StateFracture) != "" ||
		lore.StateText(StateContainment) != "" || lore.Source() != "" || lore.Consumable() != "" {
		t.Error("lore has no body: AuthorPhysics must leave it without physical properties")
	}
}

// TestFractureModesClosed: every mode maps to a real catalogue effect, and an unknown
// mode (a material NAME — exactly what the property axis forbids) is rejected.
func TestFractureModesClosed(t *testing.T) {
	for _, m := range FractureModes() {
		if !IsFractureMode(m) {
			t.Errorf("mode %q reported by FractureModes but not IsFractureMode", m)
		}
		if _, ok := EffectFor(fractureLeaf[m]); !ok {
			t.Errorf("mode %q maps to %q which is not a catalogue effect", m, fractureLeaf[m])
		}
	}
	e := &Entity{Name: "вещь", Kind: KindItem}
	e.SetFracture("гранитное") // a material name, not a fracture mode
	if e.StateText(StateFracture) != "" {
		t.Error("SetFracture must reject a non-mode (no material names in the fracture axis)")
	}
}

