// TestFractureEnumMatchesModes guards the static fracture enum tags against drifting
// from entity.FractureModes() — the property vocabulary has ONE source of truth, and
// EVERY minting author's grammar literal must mirror it (plus the «нет» sentinel for
// the formless, which is not a mode). Both authoring schemas carry the axis: the
// furnisher's PropDraft (takeables) and the shared MentionDraft (the materializer's
// mentions and the scribe's captures).
func TestFractureEnumMatchesModes(t *testing.T) {
	for _, draft := range []any{PropDraft{}, MentionDraft{}} {
		typ := reflect.TypeOf(draft)
		f, _ := typ.FieldByName("Fracture")
		inEnum := map[string]bool{}
		for _, e := range strings.Split(f.Tag.Get("enum"), ",") {
			inEnum[e] = true
			if e != "нет" && !entity.IsFractureMode(e) {
				t.Errorf("%s: enum value %q is not a fracture mode", typ.Name(), e)
			}
		}
		if !inEnum["нет"] {
			t.Errorf("%s: fracture enum must carry the «нет» sentinel for the formless", typ.Name())
		}
		for _, m := range entity.FractureModes() {
			if !inEnum[m] {
				t.Errorf("%s: fracture mode %q missing from enum tag", typ.Name(), m)
			}
		}
	}
}

// TestContainmentEnumMatchesForms guards both authoring schemas' «containment» enum
// literals against drifting from entity.ContainmentForms() — the liquid-form vocabulary
// has ONE source of truth. MentionDraft additionally carries «нет» (its mentions may be
// immaterial lore); PropDraft does not (the furnisher only authors physical props).
