// fakeCompleter returns a canned JSON body and records whether it was called —
// the test asserts that an authored or already-furnished place never reaches
// the LLM.
type fakeCompleter struct {
	body   string
	calls  int
	failOn bool // when true, Decode is expected NOT to be called
	t      *testing.T
}

func (f *fakeCompleter) CompleteWithSchema(_ context.Context, _ llm.Request, _ any) (*llm.Response, error) {
	f.calls++
	if f.failOn {
		f.t.Fatalf("LLM must not be called for this case")
	}
	return &llm.Response{Content: f.body}, nil
}

func furnishBody(props ...PropDraft) string {
	b, _ := json.Marshal(FurnishDraft{Props: props})
	return string(b)
}

// recordingStore captures the saved location so the test can assert the fund
// landed on state and was persisted.
type recordingStore struct {
	saved *persistence.LocationState
}

func (r *recordingStore) SaveLocationState(_ context.Context, loc *persistence.LocationState) error {
	r.saved = loc
	return nil
