func TestPropsFromDrafts_Normalises(t *testing.T) {
	drafts := []PropDraft{
		{Name: "  Факел  ", Aliases: "светильник, огонь", Gist: "горит", Category: "TOOL", Source: "огонь", Value: 0},
		{Name: "Факел", Gist: "дубликат по имени"},                            // duplicate name → dropped
		{Name: "", Gist: "безымянный"},                                        // nameless → dropped
		{Name: "Кружка", Category: "nonsense", Source: "nonsense", Value: -5}, // bad category/source → "", neg value → 0
	}
	props := propsFromDrafts(drafts)
	if len(props) != 2 {
		t.Fatalf("want 2 props, got %d: %+v", len(props), props)
	}
	if props[0].Name != "Факел" || props[0].Category != "tool" {
		t.Errorf("first prop trimmed/lowercased wrong: %+v", props[0])
	}
	if props[0].Source != "огонь" {
		t.Errorf("source means must round-trip, got %q", props[0].Source)
	}
	if len(props[0].Aliases) != 2 {
		t.Errorf("aliases not split: %+v", props[0].Aliases)
	}
	if props[1].Category != "" {
		t.Errorf("invalid category must clamp to empty, got %q", props[1].Category)
	}
	if props[1].Source != "" {
		t.Errorf("invalid source must clamp to empty, got %q", props[1].Source)
	}
	if props[1].Value != 0 {
		t.Errorf("negative value must clamp to 0, got %d", props[1].Value)
	}
}

