func TestEnsureFund_BarePlaceFurnishedAndPersisted(t *testing.T) {
	llmFake := &fakeCompleter{
		body: furnishBody(
			PropDraft{Name: "Факел", Gist: "горит", Category: "tool", Source: "огонь", Consumable: "нет", Thermal: "горит", Fracture: "жёсткое", Containment: "сплошное"},
			PropDraft{Name: "Табурет", Gist: "деревянный", Category: "misc", Source: "нет", Consumable: "нет", Thermal: "горит", Fracture: "жёсткое", Containment: "сплошное"},
		),
		t: t,
	}
	store := &recordingStore{}
	f := NewFurnisher(llmFake, store, nil)
	loc := &persistence.LocationState{
		Name: "Пустой зал",
		Type: "tavern",
		State: location.LocationStateData{
			Description: "прокуренный общий зал",
		},
	}

	props := f.EnsureFund(context.Background(), "речной городок", "", loc)
	if len(props) != 2 {
		t.Fatalf("want 2 furnished props, got %d", len(props))
	}
	if llmFake.calls != 1 {
		t.Errorf("want exactly 1 LLM call, got %d", llmFake.calls)
	}
	if !IsFurnished(loc.State) {
		t.Error("location must be marked furnished")
	}
	if got := PropsFromState(loc.State); len(got) != 2 {
		t.Errorf("fund must land on live state, got %d", len(got))
	}
	if store.saved == nil {
		t.Error("furnished fund must be persisted")
	}

	// Second reach: fund is now present, no further LLM call.
	llmFake.failOn = true
	props2 := f.EnsureFund(context.Background(), "речной городок", "", loc)
	if len(props2) != 2 {
		t.Errorf("second call must return the same fund, got %d", len(props2))
	}
}

func TestEnsureFund_BareAfterFurnishingNotRetried(t *testing.T) {
	// LLM yields nothing usable → fund stays empty but the marker is set, so a
	// genuinely bare place is never re-furnished on the next reach.
	llmFake := &fakeCompleter{body: furnishBody(), t: t}
	f := NewFurnisher(llmFake, &recordingStore{}, nil)
	loc := &persistence.LocationState{Name: "Голый угол", State: location.LocationStateData{}}

	if got := f.EnsureFund(context.Background(), "мир", "", loc); len(got) != 0 {
		t.Errorf("empty furnishing must yield no props, got %+v", got)
	}
	if !IsFurnished(loc.State) {
		t.Error("place must be marked furnished even with an empty fund")
	}
	llmFake.failOn = true
	if got := f.EnsureFund(context.Background(), "мир", "", loc); len(got) != 0 {
		t.Errorf("furnished-but-bare place must not be re-furnished, got %+v", got)
	}
}

