func furnishProbe() Probe {
	cases := furnishCases
	return Probe{
		Name:     "entity/furnish",
		Category: "quality",
		Reps:     len(cases) * 2, // each place twice — furnishing runs at T=0.7
		Run: func(ctx context.Context, p llm.LLMProvider, rep int) Outcome {
			tc := cases[rep%len(cases)]

			props, resp, err := knowledge.GenerateFurnishing(ctx, p, worldCanon, "", knowledge.FurnishTarget{
				Name: tc.name, Type: tc.typ, Description: tc.desc,
			})
			if err != nil {
				return failFrame(resp, "furnish: %v", err)
			}
			if len(props) == 0 {
				return failFrame(resp, "no props")
			}

			out := Outcome{Resp: resp, Pass: true, HasQuality: true, Fields: map[string]string{
				"place": tc.name,
				"count": fmt.Sprintf("%d", len(props)),
			}}

			score := 0.0
			// 4–8 things, as the prompt asks (the Go cap is 8; <4 is thin).
			if len(props) >= 4 && len(props) <= 8 {
				score += 0.3
			} else {
				out.Issues = append(out.Issues, fmt.Sprintf("count=%d (want 4-8)", len(props)))
			}
			// Every prop named with a gist, no duplicate names.
			wellFormed, seen := true, map[string]bool{}
			for _, pr := range props {
				if strings.TrimSpace(pr.Name) == "" || strings.TrimSpace(pr.Gist) == "" {
					wellFormed = false
					out.Issues = append(out.Issues, "prop with empty name/gist")
				}
				k := strings.ToLower(strings.TrimSpace(pr.Name))
				if seen[k] {
					wellFormed = false
					out.Issues = append(out.Issues, "duplicate prop name: "+pr.Name)
				}
				seen[k] = true
			}
			if wellFormed {
				score += 0.2
			}
			// At least one category plausible for THIS place (not a specific item).
			cats := map[string]bool{}
			for _, pr := range props {
				cats[strings.ToLower(strings.TrimSpace(pr.Category))] = true
			}
			placeOK := false
			for _, want := range tc.wantCats {
				if cats[want] {
					placeOK = true
					break
				}
			}
			if placeOK {
				score += 0.3
			} else {
				out.Issues = append(out.Issues, fmt.Sprintf("no place-plausible category %v present", tc.wantCats))
			}
			// Orthogonal-axis bookkeeping: which SOURCES and CONSUMABLES appeared, so the
			// place's defining one is checked below. The axes are deliberately NOT cross-
			// constrained (source ⟂ thermal: a stone oven sources fire; consumable ⟂ form:
			// a mug-of-ale is a utensil-сосуд that is consumable:drink — the very overload
			// the split removed, so a vessel-with-fracture-that-is-also-a-drink is now FINE).
			propOK, sawSource, sawConsumable := true, map[string]bool{}, map[string]bool{}
			fractured := 0
			for _, pr := range props {
				if entity.IsMeans(pr.Source) {
					sawSource[pr.Source] = true
				}
				if entity.IsConsumable(pr.Consumable) {
					sawConsumable[pr.Consumable] = true
				}
				if pr.Fracture != "" {
					fractured++
				}
			}
			// Axis CAPABILITY: a place defined by an elemental source (a bakery's oven, a
			// well-yard's well) or a consumable (a market's fare) must yield ≥1 prop carrying
			// it — proof the model USES the orthogonal axis, not that it memorised an example.
			// Folded into the property-sanity budget so a miss actually lowers the score.
			if tc.wantSource != "" && !sawSource[tc.wantSource] {
				propOK = false
				out.Issues = append(out.Issues, fmt.Sprintf("no prop supplies the place's source %q", tc.wantSource))
			}
			if tc.wantConsumable != "" && !sawConsumable[tc.wantConsumable] {
				propOK = false
				out.Issues = append(out.Issues, fmt.Sprintf("no prop carries the place's consumable %q", tc.wantConsumable))
			}
			if propOK {
				score += 0.1
			}
			// The fracture axis must be ENGAGED: a place of takeable solids should yield
			// at least one thing with a fracture mode (else the model ignored the axis).
			if fractured > 0 {
				score += 0.1
			} else {
				out.Issues = append(out.Issues, "no prop carries a fracture mode (axis ignored)")
			}

			out.Quality = score
			names := make([]string, 0, len(props))
			for _, pr := range props {
				names = append(names, fmt.Sprintf("%s[%s]", pr.Name, pr.Category))
			}
			out.Fields["props"] = strings.Join(names, ", ")
			return out
		},
	}
}

package knowledge

import (
	"context"
	"testing"

	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
)

// waterMeans is a stand-in water source the mutator tests hand to ApplyEffect to
// stand for «вода была средством» — its mere presence carries the wetting signature.
func newWaterMeans() *entity.Entity {
	e := &entity.Entity{Kind: entity.KindFeature, Name: "Бочка с водой"}
	e.SetSource(entity.MeansWater)
	return e
}

var waterMeans = newWaterMeans()

// TestMutator_ExtinguishWithWater: extinguishing a burning thing WITH WATER drops the
// hazard markers (the fire is actually out — stops spreading and flooring fear) AND
// leaves it WET (doused/cooled), so it does not instantly reignite and dries over time.
// The «пар+жар» physics assembled from real mechanics: fire out + wet (won't catch) +
// steam (the means-rich Fact). The thing survives scorched rather than consumed.
func TestMutator_ExtinguishWithWater(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	thing := &entity.Entity{
		ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindItem,
		Name: "Табурет", Gist: "табурет",
	}
	thing.SetFlammable(true)
	if err := repo.Save(ctx, thing); err != nil {
		t.Fatal(err)
	}

	// Ignite → it becomes a standing hazard with a recorded ignition tick.
	if err := mut.Ignite(ctx, thing.ID, 10); err != nil {
		t.Fatal(err)
	}
	if thing.StateText(entity.StateHazard) == "" {
		t.Fatal("ignite must set the hazard marker")
	}
	if _, ok := thing.HazardSince(); !ok {
		t.Fatal("ignite must stamp the ignition tick")
	}

	// Extinguish WITH WATER → the hazard ends; the thing survives scorched AND wet.
	if _, err := mut.ApplyEffect(ctx, thing.ID, entity.EffectExtingush, entity.EffectNote(entity.EffectExtingush), 12, waterMeans); err != nil {
		t.Fatal(err)
	}
	if thing.StateText(entity.StateHazard) != "" {
		t.Errorf("extinguish must clear the hazard, got %q", thing.StateText(entity.StateHazard))
	}
	if _, ok := thing.HazardSince(); ok {
		t.Error("extinguish must clear the ignition timestamp too")
	}
	if thing.StateText(entity.StateCondition) != entity.EffectNote(entity.EffectExtingush) {
		t.Errorf("extinguish must leave a scorched condition, got %q", thing.StateText(entity.StateCondition))
	}
	if !thing.IsWet() {
		t.Error("an extinguished-with-water thing must be left wet (resists reignition)")
	}
	if thing.CatchesFire() {
		t.Error("a just-extinguished (wet) thing must NOT instantly reignite")
	}
}

// TestMutator_ExtinguishBySmother: putting out a fire WITHOUT water (a smother, means
// nil) still ends the hazard — extinguishing's means is OPTIONAL — but leaves the thing
// DRY (no water was applied, so no wetting, no steam). The means-dependent half of the
// liquid domain: the same deed, a different outcome by what was at hand.
func TestMutator_ExtinguishBySmother(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	thing := &entity.Entity{
		ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindItem,
		Name: "Тюк соломы", Gist: "тюк",
	}
	thing.SetFlammable(true)
	if err := repo.Save(ctx, thing); err != nil {
		t.Fatal(err)
	}
	if err := mut.Ignite(ctx, thing.ID, 10); err != nil {
		t.Fatal(err)
	}

	// Smother (no water means) → fire out, but the thing is NOT wet.
	if _, err := mut.ApplyEffect(ctx, thing.ID, entity.EffectExtingush, entity.EffectNote(entity.EffectExtingush), 12, nil); err != nil {
		t.Fatal(err)
	}
	if thing.StateText(entity.StateHazard) != "" {
		t.Errorf("smothering must still clear the hazard, got %q", thing.StateText(entity.StateHazard))
	}
	if thing.IsWet() {
		t.Error("a smothered (waterless) fire must leave the thing DRY — no water was applied")
	}
}

// TestMutator_ConsumeSpendsTheMorsel: eating a discrete morsel leaves inedible remains
// (consumable cleared, an apple core); drinking from a vessel empties it AND clears the
// drink — the body survives, re-fillable. Either way a finite ration feeds exactly once
// (the consume path's default branch then refuses the spent thing). Idempotent.
func TestMutator_ConsumeSpendsTheMorsel(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	apple := &entity.Entity{ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindItem, Name: "Яблоко", Gist: "яблоко"}
	apple.SetConsumable(entity.ConsumableFood)
	if err := repo.Save(ctx, apple); err != nil {
		t.Fatal(err)
	}
	if err := mut.Consume(ctx, apple.ID, 5); err != nil {
		t.Fatal(err)
	}
	if apple.Consumable() != "" {
		t.Error("an eaten morsel must no longer be edible")
	}
	if apple.StateText(entity.StateCondition) != eatenNote {
		t.Errorf("an eaten morsel leaves remains, got %q", apple.StateText(entity.StateCondition))
	}
	// Idempotent: the core can't be eaten again.
	if err := mut.Consume(ctx, apple.ID, 6); err != nil {
		t.Fatal(err)
	}

	mug := &entity.Entity{ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindItem, Name: "Кружка эля", Gist: "кружка"}
	mug.SetContainment(entity.ContainmentVessel)
	mug.Fill(entity.MeansWater) // served full
	mug.SetConsumable(entity.ConsumableDrink)
	if err := repo.Save(ctx, mug); err != nil {
		t.Fatal(err)
	}
	if err := mut.Consume(ctx, mug.ID, 7); err != nil {
		t.Fatal(err)
	}
	if mug.Consumable() != "" || mug.IsFull() {
		t.Error("a drunk vessel must be empty AND no longer a drink")
	}
	if !mug.IsVessel() || mug.StateText(entity.StateCondition) != drunkNote {
		t.Errorf("the mug's body survives, drained — got vessel=%v cond=%q", mug.IsVessel(), mug.StateText(entity.StateCondition))
	}
}

// TestMutator_RestoreMendsRuin: Restore is the inverse of Ruin — a ruined structure
// returns to sound (so the habitability reflex reopens its place), carrying a healed
// condition; a structure that was never ruined is left untouched (idempotent).
func TestMutator_RestoreMendsRuin(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	docks := &entity.Entity{
		ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindFeature,
		Name: "Причалы", Gist: "несущая пристань",
	}
	if err := repo.Save(ctx, docks); err != nil {
		t.Fatal(err)
	}

	// A front's doom ruins it (the ford freezes shut).
	if err := mut.Ruin(ctx, docks.ID, 10); err != nil {
		t.Fatal(err)
	}
	if !docks.IsRuined() {
		t.Fatal("ruin must mark the structure ruined")
	}

	// The remedy mends it: sound again, healed condition recorded.
	if err := mut.Restore(ctx, docks.ID, 12); err != nil {
		t.Fatal(err)
	}
	if docks.IsRuined() {
		t.Error("restore must clear the ruined state so the place reopens")
	}
	if docks.StateText(entity.StateCondition) != restoredCondition {
		t.Errorf("restore must leave a healed condition, got %q", docks.StateText(entity.StateCondition))
	}

	// Idempotent: restoring an unbroken thing is a clean no-op (no false "restored" mark).
	sound := &entity.Entity{ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Name: "Скамья"}
	if err := repo.Save(ctx, sound); err != nil {
		t.Fatal(err)
	}
	if err := mut.Restore(ctx, sound.ID, 13); err != nil {
		t.Fatal(err)
	}
	if sound.StateText(entity.StateCondition) == restoredCondition {
		t.Error("restoring a thing that was never ruined must leave it untouched")
	}
}

// TestMutator_MeltReDerivesToFormless: melting a fusible thing changes its FORM, so
// the applied effect re-derives the affordances — the puddle is heat-inert and has NO
// fracture (the candle's мягкое is CLEARED). Properties follow STATE, and the state changed.
func TestMutator_MeltReDerivesToFormless(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	candle := &entity.Entity{
		ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindItem,
		Name: "Свеча", Gist: "сальная свеча",
	}
	candle.SetThermal(entity.ThermalFusible)
	candle.SetFracture(entity.FracturePliable)
	if err := repo.Save(ctx, candle); err != nil {
		t.Fatal(err)
	}

	if _, err := mut.ApplyEffect(ctx, candle.ID, entity.EffectMelt, entity.EffectNote(entity.EffectMelt), 5, nil); err != nil {
		t.Fatal(err)
	}
	if candle.StateText(entity.StateThermal) != entity.ThermalInert {
		t.Errorf("a melted thing is heat-inert, got %q", candle.StateText(entity.StateThermal))
	}
	if candle.StateText(entity.StateFracture) != "" {
		t.Errorf("a formless puddle has no fracture — the stale мягкое must be cleared, got %q", candle.StateText(entity.StateFracture))
	}
}

// TestMutator_BurnOutCrumbles: a burned-out husk crumbles (рыхлое) instead of snapping
// like the intact beam, and cannot reignite — the burn-out path re-derives BOTH
// affordances through the same phase-change primitive the melt path uses.
func TestMutator_BurnOutCrumbles(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	beam := &entity.Entity{
		ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindFeature,
		Name: "Балка", Gist: "несущая балка",
	}
	beam.SetThermal(entity.ThermalIgnites)
	beam.SetFracture(entity.FractureRigid)
	if err := repo.Save(ctx, beam); err != nil {
		t.Fatal(err)
	}

	if err := mut.BurnOut(ctx, beam.ID, 7); err != nil {
		t.Fatal(err)
	}
	if beam.CatchesFire() {
		t.Error("a cinder cannot reignite")
	}
	if beam.StateText(entity.StateFracture) != entity.FractureFriable {
		t.Errorf("a charred husk crumbles (рыхлое), no longer snaps, got %q", beam.StateText(entity.StateFracture))
	}
}

// TestMutator_DouseClearsHazardLeavesWet: rain (Douse) puts a fire out leaving the thing WET and
// intact — the hazard is cleared, it cannot immediately reignite (wet suppresses CatchesFire), and
// it is NOT charred to a friable cinder (that is BurnOut). Idempotent on a thing no longer alight.
func TestMutator_DouseClearsHazardLeavesWet(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	shed := &entity.Entity{
		ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindFeature,
		Name: "Навес", Gist: "дощатый навес",
	}
	shed.SetThermal(entity.ThermalIgnites)
	shed.SetFracture(entity.FractureRigid)
	shed.SetHazard(entity.EffectBurn, 3) // alight
	if err := repo.Save(ctx, shed); err != nil {
		t.Fatal(err)
	}

	if err := mut.Douse(ctx, shed.ID, 9); err != nil {
		t.Fatal(err)
	}
	if shed.StateText(entity.StateHazard) != "" {
		t.Errorf("rain must clear the hazard (stop the fire), got %q", shed.StateText(entity.StateHazard))
	}
	if !shed.IsWet() {
		t.Error("rain leaves the thing WET — it cannot immediately reignite")
	}
	if shed.CatchesFire() {
		t.Error("a wet thing does not catch fire (water beats fire)")
	}
	if shed.StateText(entity.StateFracture) == entity.FractureFriable {
		t.Error("douse must NOT char the thing to a friable cinder — that is BurnOut")
	}

	// Idempotent: dousing a thing no longer alight is a no-op.
	if err := mut.Douse(ctx, shed.ID, 10); err != nil {
		t.Fatalf("re-dousing a dead fire must be a no-op, got %v", err)
	}
}

// TestMutator_FillEmptyTracksContents: наполнить fills a vessel, опустошить empties it
// — the contents state the verdict's vessel gates protect.
func TestMutator_FillEmptyTracksContents(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	bucket := &entity.Entity{
		ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindItem,
		Name: "Ведро", Gist: "деревянное ведро",
	}
	bucket.SetContainment(entity.ContainmentVessel)
	if err := repo.Save(ctx, bucket); err != nil {
		t.Fatal(err)
	}

	if _, err := mut.ApplyEffect(ctx, bucket.ID, entity.EffectFill, entity.EffectNote(entity.EffectFill), 3, waterMeans); err != nil {
		t.Fatal(err)
	}
	if !bucket.IsFull() {
		t.Error("наполнить must fill the vessel")
	}
	// Filled WITH water (наполнить requires water), the bucket is now a PORTABLE water
	// source — carry it to a fire and it extinguishes, away from any standing water.
	if bucket.ContentKind() != entity.MeansWater || !bucket.Supplies(entity.MeansWater) {
		t.Errorf("a water-filled bucket must supply water, kind=%q", bucket.ContentKind())
	}
	if _, err := mut.ApplyEffect(ctx, bucket.ID, entity.EffectEmpty, entity.EffectNote(entity.EffectEmpty), 4, nil); err != nil {
		t.Fatal(err)
	}
	if bucket.IsFull() {
		t.Error("опустошить must empty the vessel")
	}
}

// TestMutator_DousingWetsAndDryingDries: водой beats fire mechanically — dousing a
// flammable thing leaves it WET (CatchesFire suppressed), a deliberate drying or the
// tick's DryOut sheds the water and its flammability returns.
func TestMutator_DousingWetsAndDryingDries(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	stool := &entity.Entity{
		ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindItem,
		Name: "Табурет", Gist: "деревянный табурет",
	}
	stool.SetThermal(entity.ThermalIgnites)
	if err := repo.Save(ctx, stool); err != nil {
		t.Fatal(err)
	}

	// Dousing → wet → will not catch fire. (Soak's water means is mandatory, so the
	// verdict only reaches here with water — the mutator wets regardless of the arg.)
	if _, err := mut.ApplyEffect(ctx, stool.ID, entity.EffectSoak, entity.EffectNote(entity.EffectSoak), 5, waterMeans); err != nil {
		t.Fatal(err)
	}
	if !stool.IsWet() {
		t.Fatal("dousing must leave the thing wet")
	}
	if stool.CatchesFire() {
		t.Error("a doused flammable thing must NOT catch fire")
	}

	// The tick's dry-out sheds the water; flammability returns.
	if err := mut.DryOut(ctx, stool.ID, 40); err != nil {
		t.Fatal(err)
	}
	if stool.IsWet() {
		t.Error("DryOut must shed the wetness")
	}
	if !stool.CatchesFire() {
		t.Error("a dried thing's flammability must return")
	}
}

package entity

import "testing"

// thingWithThermal builds a thing whose thermal-response property is set.
func thingWithThermal(mode string) *Entity {
	e := &Entity{Name: "вещь", Kind: KindItem}
	e.SetThermal(mode)
	return e
}

// TestRefineHeatEffect: an applied-heat deed resolves to the leaf the thing's THERMAL
// response dictates — the heat twin of RefineForceEffect. A fusible thing melts under
// any heat deed; a flammable thing burns even one phrased as «melt»; an inert (or
// unjudged) thing keeps the pick so the verdict's fusible gate can fizzle it.
func TestRefineHeatEffect(t *testing.T) {
	cases := []struct {
		name    string
		thermal string
		sensor  string // the heat leaf the LLM picked
		want    string // the thermal-correct leaf the core commits
	}{
		// fusible: ANY heat deed melts it (a tallow candle one tried to set alight).
		{"плавится: поджечь → растопить", ThermalFusible, EffectBurn, EffectMelt},
		{"плавится: растопить → растопить", ThermalFusible, EffectMelt, EffectMelt},
		{"плавится: обуглить → растопить", ThermalFusible, EffectChar, EffectMelt},
		// ignites: it burns even when the deed said «melt»; char stays char.
		{"горит: растопить → поджечь", ThermalIgnites, EffectMelt, EffectBurn},
		{"горит: поджечь → поджечь", ThermalIgnites, EffectBurn, EffectBurn},
		{"горит: обуглить → обуглить", ThermalIgnites, EffectChar, EffectChar},
		// inert: pick kept (the gate downstream makes melt impotent on stone).
		{"стойкое: растопить остаётся (гейт финалит)", ThermalInert, EffectMelt, EffectMelt},
		{"стойкое: поджечь остаётся (гейт горючести финалит)", ThermalInert, EffectBurn, EffectBurn},
	}
	for _, c := range cases {
		if got := RefineHeatEffect(c.sensor, thingWithThermal(c.thermal)); got != c.want {
			t.Errorf("%s: RefineHeatEffect(%q, %s) = %q, want %q", c.name, c.sensor, c.thermal, got, c.want)
		}
	}
}

// TestRefineHeatEffect_Passthrough: the refiner touches ONLY the applied-heat cluster —
// a non-heat effect, a thing with no thermal response, or a nil thing keeps the pick.
func TestRefineHeatEffect_Passthrough(t *testing.T) {
	cases := []struct {
		name  string
		key   string
		thing *Entity
	}{
		{"не-heat эффект не трогаем (разбить)", EffectShatter, thingWithThermal(ThermalFusible)},
		{"не-heat эффект не трогаем (потушить)", EffectExtingush, thingWithThermal(ThermalIgnites)},
		{"без теплового ответа — пик как есть", EffectMelt, &Entity{Name: "вещь", Kind: KindItem}},
		{"nil-вещь — пик как есть", EffectBurn, nil},
	}
	for _, c := range cases {
		if got := RefineHeatEffect(c.key, c.thing); got != c.key {
			t.Errorf("%s: RefineHeatEffect(%q) = %q, want passthrough %q", c.name, c.key, got, c.key)
		}
	}
}

// TestThermalProjectsCatchesFire: CatchesFire is now the IGNITES projection of the one
// thermal axis — горит burns, плавится/стойкое do not, an unjudged thing falls to its
// category default. This is the contract the fire-spread relies on, unchanged by the
// axis generalisation.
func TestThermalProjectsCatchesFire(t *testing.T) {
	if !thingWithThermal(ThermalIgnites).CatchesFire() {
		t.Error("горит must catch fire")
	}
	if thingWithThermal(ThermalFusible).CatchesFire() {
		t.Error("плавится must NOT catch fire (it melts, not burns)")
	}
	if thingWithThermal(ThermalInert).CatchesFire() {
		t.Error("стойкое must NOT catch fire")
	}
}

// TestShiftPhase_ReDerivesAndClears: a transformation that changes a thing's FORM
// re-derives BOTH affordances — and CLEARS the axis on which the new form has no
// response, so a stale value never lies. This is the dynamic answer to «a material's
// response depends on its state»: melt a soft, fusible candle and the formless puddle
// no longer melts (inert) nor shatters (no fracture); burn a rigid beam and the husk
// crumbles (friable) instead of snapping.
func TestShiftPhase_ReDerivesAndClears(t *testing.T) {
	candle := &Entity{Name: "свеча", Kind: KindItem}
	candle.SetThermal(ThermalFusible)
	candle.SetFracture(FracturePliable)
	candle.ShiftPhase(ThermalInert, "") // melt → formless puddle
	if candle.StateText(StateThermal) != ThermalInert {
		t.Errorf("melt must re-derive thermal to inert, got %q", candle.StateText(StateThermal))
	}
	if candle.StateText(StateFracture) != "" {
		t.Error("a formless puddle has no fracture — the stale мягкое must be CLEARED")
	}

	beam := &Entity{Name: "балка", Kind: KindFeature}
	beam.SetThermal(ThermalIgnites)
	beam.SetFracture(FractureRigid)
	beam.ShiftPhase(ThermalInert, FractureFriable) // burn out → charred husk
	if beam.CatchesFire() {
		t.Error("a cinder cannot reignite")
	}
	if beam.StateText(StateFracture) != FractureFriable {
		t.Error("a charred husk crumbles (рыхлое), no longer snaps (жёсткое)")
	}
}

// TestEffectPhaseShift: a phase-CHANGING effect declares its resulting form; an effect
// that leaves the material unchanged declares none.
func TestEffectPhaseShift(t *testing.T) {
	if ps := EffectPhaseShift(EffectMelt); ps == nil || ps.Thermal != ThermalInert || ps.Fracture != "" {
		t.Errorf("melt must leave a formless, heat-inert puddle, got %+v", ps)
	}
	if EffectPhaseShift(EffectShatter) != nil {
		t.Error("shattering does not change a thing's material form — no phase shift")
	}
	if EffectPhaseShift(EffectStain) != nil {
		t.Error("a stain marks the surface, it does not change the form — no phase shift")
	}
}

// TestThermalModesClosed: every mode is recognised, and SetThermal rejects a non-mode
// (a material name — exactly what the property axis forbids), like SetFracture.
func TestThermalModesClosed(t *testing.T) {
	for _, m := range ThermalModes() {
		if !IsThermalMode(m) {
			t.Errorf("mode %q reported by ThermalModes but not IsThermalMode", m)
		}
	}
	e := &Entity{Name: "вещь", Kind: KindItem}
	e.SetThermal("каменное") // a material name, not a thermal mode
	if e.StateText(StateThermal) != "" {
		t.Error("SetThermal must reject a non-mode (no material names in the thermal axis)")
	}
}

