func runState(ctx context.Context, p infrallm.SchemaCompleter, samples int) {
	for i, c := range stateCases {
		fmt.Printf("\n%s\n#%-2d хотим [%s]  держит=%q  снимает=%q\n   «%s»\n%s\n",
			strings.Repeat("═", 90), i+1, c.want, c.normHas, c.normNot, c.utterance, strings.Repeat("─", 90))
		for s := 1; s <= samples; s++ {
			emo, eErr := extraction.DetectState(ctx, p, c.utterance)
			deeds, dErr := extraction.StripState(ctx, p, c.utterance)
			if eErr != nil || dErr != nil {
				fmt.Printf("  ⃟%d ✗ emotion=%v strip=%v\n", s, eErr, dErr)
				continue
			}
			low := strings.ToLower(deeds)
			emoOK := emo == c.want
			hasOK := c.normHas == "" || strings.Contains(low, strings.ToLower(c.normHas))
			notOK := c.normNot == "" || !strings.Contains(low, strings.ToLower(c.normNot))
			mark := "✓"
			if !emoOK || !hasOK || !notOK {
				mark = "✗"
			}
			detail := ""
			if !emoOK {
				detail += " [эмоция]"
			}
			if !hasOK {
				detail += " [потерял деяние]"
			}
			if !notOK {
				detail += " [состояние не снято]"
			}
			fmt.Printf("  ⃟%d  %-12s → «%s»  %s%s\n", s, emo, deeds, mark, detail)
		}
	}
}

