var parsePhrases = []string{
	"бью стражника и отступаю к стене",
	"хватаю Мирру за плечо и сильно трясу её",
	"если стражник обернётся, бью его рукоятью по затылку",
	"не притрагиваюсь к золоту, только разглядываю печать на сундуке",
	"пытаюсь выломать дверь плечом",
	"что лежит на этом столе?",
	"иду к двери, нет, сначала гашу свечу",
	"покупаю у торговца фонарь за пять монет",
	"осматриваю площадь, потом иду к колодцу и заглядываю внутрь",
	// Inconsequential self/flavour deeds: clear, but no world stakes. These bounced live
	// to "Опиши действие подробнее" — extractAction emitted "other" with an EMPTY topic, so
	// doFreeform had no deed to render. The deed IS stated; the topic must carry its
	// infinitive («потянуться», «постучать по столу») so it lands as a harmless beat.
	"потягиваюсь и разминаю плечи",
	"стучу костяшками по столу",
	"переминаюсь с ноги на ногу",
	// Pure MOVE with a destination — must parse as ONE move (action=move, where=the place),
	// NOT leak the destination into a speech/topic deed (the confab-on-move seam: a left-behind
	// NPC must not answer as if asked about the place the player is walking TO).
	"иду на Сухой Рынок",
	"направляюсь к старой пристани",
	// Self-locative exploration — «обхожу рынок» is looking around the place you ARE, NOT
	// relocating to a new one. Must NOT classify as move (which would bounce "Куда именно?"
	// on an empty destination); it is observe/explore HERE.
	"обхожу рынок и разглядываю товары",
}

func runParse(ctx context.Context, p infrallm.SchemaCompleter, samples int) {
	parser := extraction.NewIntentParser(p)
	for i, phrase := range parsePhrases {
		fmt.Printf("\n%s\n#%-2d  «%s»\n%s\n", strings.Repeat("═", 90), i+1, phrase, strings.Repeat("─", 90))
		for s := 1; s <= samples; s++ {
			pt, _, err := parser.Parse(ctx, phrase, extraction.ParseContext{})
			if err != nil {
				fmt.Printf("  ⃟%d ✗ %v\n", s, err)
				continue
			}
			fmt.Printf("  ⃟%d\n", s)
			for j, a := range pt.Actions {
				mod := a.Modality
				if mod == "" {
					mod = "actual"
				}
				if strings.TrimSpace(a.Trigger) != "" {
					mod += " «" + a.Trigger + "»"
				}
				fmt.Printf("    [%d] %s/%s  [%s]\n", j+1, a.Action, a.Charge, mod)
				for _, r := range []struct{ k, v string }{
					{"who", a.Who}, {"where", a.Where}, {"topic", a.Topic}, {"utterance", a.Utterance},
					{"target", a.Target}, {"instrument", a.Instrument}, {"payment", a.Payment}, {"duration", a.Duration},
				} {
					if r.v != "" {
						fmt.Printf("          %s → %s\n", r.k, r.v)
					}
				}
				if a.Covert {
					fmt.Printf("          covert → true\n")
				}
			}
		}
	}
}

