package player

import (
	"context"
	"strings"
	"testing"

	"github.com/dnd-llm/dnd-llm/internal/application/extraction"
	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/actor"
	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
)

// groundedMentions builds a turn's grounded set from text→id (who-kind) pairs, so a
// verdict test can exercise the consumption path the way groundTurn feeds it.
func groundedWho(pairs map[string]domain.ActorID) *extraction.MentionSet {
	ms := extraction.NewMentionSet()
	for text, id := range pairs {
		ms.Add(text, string(id), extraction.MentionWho)
	}
	return ms
}

// TestMeansResolverCoversCatalogue: every means a catalogue effect can REQUIRE must be a
// real means the resolver knows how to carry, or the verdict's means resolver would
// silently never find the source (a hard-required deed fizzling forever, an optional one
// always smothering). The means model's two halves — what an effect needs (entity
// catalogue) and how the scene supplies it (player package) — must agree.
func TestMeansResolverCoversCatalogue(t *testing.T) {
	for _, key := range entity.EffectKeys() {
		req := effectRequires(key)
		if req == entity.MeansNone {
			continue
		}
		if !entity.IsMeans(req) {
			t.Errorf("effect %q requires %q which is not a real means", key, req)
		}
		if _, ok := mustCarryMeans[req]; !ok {
			t.Errorf("effect %q requires means %q with no carry rule to resolve it", key, req)
		}
	}
	// Fire is carried to its target; water is splashed in place — the carriability
	// asymmetry that lets a fixed river serve as a water means but not a fire one.
	if !mustCarryMeans[entity.MeansFire] {
		t.Error("a flame must be carried to what it burns")
	}
	if mustCarryMeans[entity.MeansWater] {
		t.Error("water need not be carried — it is splashed from where it sits")
	}
}

// TestMeansSpentByUse: a CONTAINED supply (a filled bucket of water — no intrinsic
// source) is spent on use, so the next fire needs a refill; an INTRINSIC source (a river,
// a torch) is inexhaustible; an empty/absent means or the deed's own freshly-filled target
// is not drained.
func TestMeansSpentByUse(t *testing.T) {
	bucket := &entity.Entity{ID: domain.NewEntityID(), Name: "Ведро", Kind: entity.KindItem}
	bucket.SetContainment(entity.ContainmentVessel)
	bucket.Fill(entity.MeansWater)
	if !meansSpentByUse(bucket, nil) {
		t.Error("a filled water bucket (contained supply) must be spent on use")
	}

	river := &entity.Entity{ID: domain.NewEntityID(), Name: "Река", Kind: entity.KindFeature}
	river.SetSource(entity.MeansWater)
	if meansSpentByUse(river, nil) {
		t.Error("an intrinsic source (a river) is inexhaustible — never spent")
	}

	empty := &entity.Entity{ID: domain.NewEntityID(), Name: "Пустое ведро", Kind: entity.KindItem}
	empty.SetContainment(entity.ContainmentVessel)
	if meansSpentByUse(empty, nil) {
		t.Error("an empty vessel has nothing to spend")
	}
	if meansSpentByUse(nil, nil) {
		t.Error("no means, nothing to spend")
	}

	// The deed filled THIS vessel (means == target) — it must not be drained the same turn.
	if meansSpentByUse(bucket, bucket) {
		t.Error("a just-filled target vessel must not be immediately drained")
	}
}

// Каталог эффектов: ключ → детерминированные свойства (нота, опасность, средство).
func TestEffectCatalogue(t *testing.T) {
	burn, ok := entity.EffectFor(entity.EffectBurn)
	if !ok || !burn.Hazard || burn.Requires != entity.MeansFire {
		t.Errorf("поджечь must be a hazard requiring fire: %+v", burn)
	}
	shatter, ok := entity.EffectFor(entity.EffectShatter)
	if !ok || shatter.Hazard || shatter.Requires != entity.MeansNone {
		t.Errorf("разбить must be a harmless bare-hands effect: %+v", shatter)
	}
	if !entity.IsHazardEffect(entity.EffectBurn) || entity.IsHazardEffect(entity.EffectPaint) {
		t.Error("hazard classification: fire yes, paint no")
	}
	// Extinguishing needs an active fire; nothing else carries the precondition,
	// so re-applying a settled effect never overwrites a committed condition.
	if !entity.EffectNeedsHazard(entity.EffectExtingush) {
		t.Error("потушить must require an active fire (RequiresHazard)")
	}
	if entity.EffectNeedsHazard(entity.EffectBurn) || entity.EffectNeedsHazard(entity.EffectShatter) {
		t.Error("only extinguish needs an active fire — burn/shatter do not")
	}
	// Catch-fire effects need a flammable thing (arson shares the spread's gate);
	// non-fire effects do not (you can shatter a clay mug).
	if !entity.EffectNeedsFlammable(entity.EffectBurn) || !entity.EffectNeedsFlammable(entity.EffectChar) {
		t.Error("burn/char must require a flammable target")
	}
	if entity.EffectNeedsFlammable(entity.EffectShatter) || entity.EffectNeedsFlammable(entity.EffectMelt) {
		t.Error("only catch-fire effects need flammability — shatter/melt do not")
	}
	if _, ok := entity.EffectFor("телепортировать"); ok {
		t.Error("an off-catalogue effect must not resolve")
	}
}

// Импульс эмоций: floor-семантика мимо blend, эскалация пересчитывается.
func TestApplyEmotionImpulse_FloorsAndEscalation(t *testing.T) {
	bs := actor.NewBehaviorSystem()
	victim := mkActor(tAnna, "Анна", 0.5, 0)

	changed := bs.ApplyEmotionImpulse(victim, map[actor.EmotionType]float32{
		actor.EmotionFear:  0.85,
		actor.EmotionAnger: 0.35,
	})
	if !changed {
		t.Fatal("impulse must change a calm actor")
	}
	tone := victim.State.Emotional.CurrentTone
	if tone.Emotions[actor.EmotionFear] < 0.85 {
		t.Errorf("fear = %.2f, want floor 0.85 (the old blend×0.3 landed at ~0.1 — the toothless-violence bug)", tone.Emotions[actor.EmotionFear])
	}
	if victim.State.Emotional.EscalationLevel == actor.EscalationNeutral {
		t.Error("escalation must leave neutral after a 0.85 fear impulse")
	}

	// Floor, не перезапись: более сильная текущая эмоция не гасится.
	tone.Emotions[actor.EmotionFear] = 0.9
	bs.ApplyEmotionImpulse(victim, map[actor.EmotionType]float32{actor.EmotionFear: 0.5})
	if tone.Emotions[actor.EmotionFear] != 0.9 {
		t.Errorf("a weaker impulse must not dampen existing fear: %.2f", tone.Emotions[actor.EmotionFear])
	}
}

