// computeVerdict: цель-человек + враждебный заряд = assault; без цели — plain.
func TestComputeVerdict_AssaultAndPlain(t *testing.T) {
	grom := mkActor(tGrom, "Старый Гром", 0.5, 0)
	player := mkActor(tPlayer, "Вася", 0.5, 0)
	tc := &turnContext{player: player, roster: []*actor.Actor{grom},
		mentions: groundedWho(map[string]domain.ActorID{"грома": tGrom})}
	s := &TurnService{} // knowledge=nil: вещи не заземляются, люди — да

	v := s.computeVerdict(context.Background(), tc, extractedDeed{
		Deed: "плюнуть в лицо", Target: "грома", Charge: chargeHostile,
	})
	if v.kind != verdictAssault || v.targetNPC == nil || v.targetNPC.ID != tGrom {
		t.Errorf("hostile deed on a person must be assault, got kind=%d", v.kind)
	}

	v = s.computeVerdict(context.Background(), tc, extractedDeed{
		Deed: "потянуться и размять плечи", Charge: "нейтрально",
	})
	if v.kind != verdictPlain || len(v.facts) == 0 {
		t.Errorf("neutral deed must be plain with facts, got kind=%d facts=%v", v.kind, v.facts)
	}

	// Враждебность на вещь без средств — честный отказ.
	v = s.computeVerdict(context.Background(), tc, extractedDeed{
		Deed: "поджечь таверну", Target: "таверна", Charge: chargeHostile,
	})
	if v.kind != verdictPlain && v.kind != verdictImpotent {
		t.Errorf("ungrounded entity target must degrade safely, got kind=%d", v.kind)
	}
}

// TestComputeVerdict_PersonInWhoSlot guards the kindness/assault robustness: the
// parser puts the person of an interpersonal deed in the Who slot (and the deed
// is the bare verb — «обнять»), not Target. The verdict must still find them, so
// a hug is a kindness and a shove an assault rather than "ничего не меняется".
func TestComputeVerdict_PersonInWhoSlot(t *testing.T) {
	grom := mkActor(tGrom, "Старый Гром", 0.5, 0)
	player := mkActor(tPlayer, "Вася", 0.5, 0)
	tc := &turnContext{player: player, roster: []*actor.Actor{grom},
		mentions: groundedWho(map[string]domain.ActorID{"Грома": tGrom})}
	s := &TurnService{} // selector/knowledge nil: no thing grounds, so the person-fallback decides

	v := s.computeVerdict(context.Background(), tc, extractedDeed{
		Deed: "обнять", Who: "Грома", Charge: chargeFriendly,
	})
	if v.kind != verdictKindness || v.targetNPC == nil || v.targetNPC.ID != tGrom {
		t.Errorf("friendly deed with the person in Who must be a kindness, got kind=%d target=%v", v.kind, v.targetNPC)
	}

	v = s.computeVerdict(context.Background(), tc, extractedDeed{
		Deed: "толкнуть", Who: "Грома", Charge: chargeHostile,
	})
	if v.kind != verdictAssault || v.targetNPC == nil {
		t.Errorf("hostile deed with the person in Who must be an assault, got kind=%d", v.kind)
	}

	// No person anywhere → still degrades safely (plain/impotent), not a panic.
	v = s.computeVerdict(context.Background(), tc, extractedDeed{
		Deed: "потянуться", Charge: "нейтрально",
	})
	if v.kind != verdictPlain {
		t.Errorf("a deed naming no one must stay plain, got kind=%d", v.kind)
	}
}

