	silven.State.StateContext = &actor.IdleContext{Location: square} // present, here with the player

	tc := &turnContext{player: player, roster: []*actor.Actor{mirra, silven},
		mentions: groundedWho(map[string]domain.ActorID{
			"Мирра":           tMirra,
			"обнять Сильвена": tSilven, // the deed text the grounding pass tied to a PRESENT soul
			"Сильвен":         tSilven,
		})}
	s := &TurnService{}

	// The fix: a named-but-absent addressee finds NO target — never retargets to a present soul.
	if p := s.deedPerson(context.Background(), tc, extractedDeed{Who: "Мирра", Deed: "обнять Сильвена", Charge: chargeFriendly}); p != nil {
		t.Errorf("a hug for an ABSENT named person must find no target, got %s", p.GetName())
	}
	// A named, present addressee is found as before.
	if p := s.deedPerson(context.Background(), tc, extractedDeed{Who: "Сильвен", Charge: chargeFriendly}); p == nil || p.ID != tSilven {
		t.Errorf("a named present addressee must be found, got %v", p)
	}
	// The deed-text fallback still fires when the parser folded the addressee in (Who empty).
	if p := s.deedPerson(context.Background(), tc, extractedDeed{Who: "", Deed: "обнять Сильвена", Charge: chargeFriendly}); p == nil || p.ID != tSilven {
		t.Errorf("an empty Who must still fall back to the folded deed addressee, got %v", p)
	}
}

package knowledge

import (
	"context"
	"testing"

	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
)

// waterMeans is a stand-in water source the mutator tests hand to ApplyEffect to
// stand for «вода была средством» — its mere presence carries the wetting signature.
func newWaterMeans() *entity.Entity {
	e := &entity.Entity{Kind: entity.KindFeature, Name: "Бочка с водой"}
	e.SetSource(entity.MeansWater)
	return e
}

var waterMeans = newWaterMeans()

// TestMutator_ExtinguishWithWater: extinguishing a burning thing WITH WATER drops the
// hazard markers (the fire is actually out — stops spreading and flooring fear) AND
// leaves it WET (doused/cooled), so it does not instantly reignite and dries over time.
// The «пар+жар» physics assembled from real mechanics: fire out + wet (won't catch) +
// steam (the means-rich Fact). The thing survives scorched rather than consumed.
func TestMutator_ExtinguishWithWater(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	thing := &entity.Entity{
		ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindItem,
		Name: "Табурет", Gist: "табурет",
	}
	thing.SetFlammable(true)
	if err := repo.Save(ctx, thing); err != nil {
		t.Fatal(err)
	}

	// Ignite → it becomes a standing hazard with a recorded ignition tick.
	if err := mut.Ignite(ctx, thing.ID, 10); err != nil {
		t.Fatal(err)
	}
	if thing.StateText(entity.StateHazard) == "" {
		t.Fatal("ignite must set the hazard marker")
	}
	if _, ok := thing.HazardSince(); !ok {
		t.Fatal("ignite must stamp the ignition tick")
	}

	// Extinguish WITH WATER → the hazard ends; the thing survives scorched AND wet.
	if _, err := mut.ApplyEffect(ctx, thing.ID, entity.EffectExtingush, entity.EffectNote(entity.EffectExtingush), 12, waterMeans); err != nil {
		t.Fatal(err)
	}
	if thing.StateText(entity.StateHazard) != "" {
		t.Errorf("extinguish must clear the hazard, got %q", thing.StateText(entity.StateHazard))
	}
	if _, ok := thing.HazardSince(); ok {
		t.Error("extinguish must clear the ignition timestamp too")
	}
	if thing.StateText(entity.StateCondition) != entity.EffectNote(entity.EffectExtingush) {
		t.Errorf("extinguish must leave a scorched condition, got %q", thing.StateText(entity.StateCondition))
	}
	if !thing.IsWet() {
		t.Error("an extinguished-with-water thing must be left wet (resists reignition)")
	}
	if thing.CatchesFire() {
		t.Error("a just-extinguished (wet) thing must NOT instantly reignite")
	}
}

// TestMutator_ExtinguishBySmother: putting out a fire WITHOUT water (a smother, means
// nil) still ends the hazard — extinguishing's means is OPTIONAL — but leaves the thing
// DRY (no water was applied, so no wetting, no steam). The means-dependent half of the
// liquid domain: the same deed, a different outcome by what was at hand.
func TestMutator_ExtinguishBySmother(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	thing := &entity.Entity{
		ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindItem,
		Name: "Тюк соломы", Gist: "тюк",
	}
	thing.SetFlammable(true)
	if err := repo.Save(ctx, thing); err != nil {
		t.Fatal(err)
	}
	if err := mut.Ignite(ctx, thing.ID, 10); err != nil {
		t.Fatal(err)
	}

	// Smother (no water means) → fire out, but the thing is NOT wet.
	if _, err := mut.ApplyEffect(ctx, thing.ID, entity.EffectExtingush, entity.EffectNote(entity.EffectExtingush), 12, nil); err != nil {
		t.Fatal(err)
	}
	if thing.StateText(entity.StateHazard) != "" {
		t.Errorf("smothering must still clear the hazard, got %q", thing.StateText(entity.StateHazard))
	}
	if thing.IsWet() {
		t.Error("a smothered (waterless) fire must leave the thing DRY — no water was applied")
	}
}

// TestMutator_ConsumeSpendsTheMorsel: eating a discrete morsel leaves inedible remains
// (consumable cleared, an apple core); drinking from a vessel empties it AND clears the
// drink — the body survives, re-fillable. Either way a finite ration feeds exactly once
// (the consume path's default branch then refuses the spent thing). Idempotent.
func TestMutator_ConsumeSpendsTheMorsel(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	apple := &entity.Entity{ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindItem, Name: "Яблоко", Gist: "яблоко"}
	apple.SetConsumable(entity.ConsumableFood)
	if err := repo.Save(ctx, apple); err != nil {
		t.Fatal(err)
	}
	if err := mut.Consume(ctx, apple.ID, 5); err != nil {
		t.Fatal(err)
	}
	if apple.Consumable() != "" {
		t.Error("an eaten morsel must no longer be edible")
	}
	if apple.StateText(entity.StateCondition) != eatenNote {
		t.Errorf("an eaten morsel leaves remains, got %q", apple.StateText(entity.StateCondition))
	}
	// Idempotent: the core can't be eaten again.
	if err := mut.Consume(ctx, apple.ID, 6); err != nil {
		t.Fatal(err)
	}

	mug := &entity.Entity{ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindItem, Name: "Кружка эля", Gist: "кружка"}
	mug.SetContainment(entity.ContainmentVessel)
	mug.Fill(entity.MeansWater) // served full
	mug.SetConsumable(entity.ConsumableDrink)
	if err := repo.Save(ctx, mug); err != nil {
		t.Fatal(err)
	}
	if err := mut.Consume(ctx, mug.ID, 7); err != nil {
		t.Fatal(err)
	}
	if mug.Consumable() != "" || mug.IsFull() {
		t.Error("a drunk vessel must be empty AND no longer a drink")
	}
	if !mug.IsVessel() || mug.StateText(entity.StateCondition) != drunkNote {
		t.Errorf("the mug's body survives, drained — got vessel=%v cond=%q", mug.IsVessel(), mug.StateText(entity.StateCondition))
	}
}

// TestMutator_RestoreMendsRuin: Restore is the inverse of Ruin — a ruined structure
// returns to sound (so the habitability reflex reopens its place), carrying a healed
// condition; a structure that was never ruined is left untouched (idempotent).
func TestMutator_RestoreMendsRuin(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	docks := &entity.Entity{
		ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindFeature,
		Name: "Причалы", Gist: "несущая пристань",
	}
	if err := repo.Save(ctx, docks); err != nil {
		t.Fatal(err)
	}

	// A front's doom ruins it (the ford freezes shut).
	if err := mut.Ruin(ctx, docks.ID, 10); err != nil {
		t.Fatal(err)
	}
	if !docks.IsRuined() {
		t.Fatal("ruin must mark the structure ruined")
	}

	// The remedy mends it: sound again, healed condition recorded.
	if err := mut.Restore(ctx, docks.ID, 12); err != nil {
		t.Fatal(err)
	}
	if docks.IsRuined() {
		t.Error("restore must clear the ruined state so the place reopens")
	}
	if docks.StateText(entity.StateCondition) != restoredCondition {
		t.Errorf("restore must leave a healed condition, got %q", docks.StateText(entity.StateCondition))
	}

	// Idempotent: restoring an unbroken thing is a clean no-op (no false "restored" mark).
	sound := &entity.Entity{ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Name: "Скамья"}
	if err := repo.Save(ctx, sound); err != nil {
		t.Fatal(err)
	}
	if err := mut.Restore(ctx, sound.ID, 13); err != nil {
		t.Fatal(err)
	}
	if sound.StateText(entity.StateCondition) == restoredCondition {
		t.Error("restoring a thing that was never ruined must leave it untouched")
	}
}

// TestMutator_MeltReDerivesToFormless: melting a fusible thing changes its FORM, so
// the applied effect re-derives the affordances — the puddle is heat-inert and has NO
// fracture (the candle's мягкое is CLEARED). Properties follow STATE, and the state changed.
func TestMutator_MeltReDerivesToFormless(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	candle := &entity.Entity{
		ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindItem,
		Name: "Свеча", Gist: "сальная свеча",
	}
	candle.SetThermal(entity.ThermalFusible)
	candle.SetFracture(entity.FracturePliable)
	if err := repo.Save(ctx, candle); err != nil {
		t.Fatal(err)
	}

	if _, err := mut.ApplyEffect(ctx, candle.ID, entity.EffectMelt, entity.EffectNote(entity.EffectMelt), 5, nil); err != nil {
		t.Fatal(err)
	}
	if candle.StateText(entity.StateThermal) != entity.ThermalInert {
		t.Errorf("a melted thing is heat-inert, got %q", candle.StateText(entity.StateThermal))
	}
	if candle.StateText(entity.StateFracture) != "" {
		t.Errorf("a formless puddle has no fracture — the stale мягкое must be cleared, got %q", candle.StateText(entity.StateFracture))
	}
}

// TestMutator_BurnOutCrumbles: a burned-out husk crumbles (рыхлое) instead of snapping
// like the intact beam, and cannot reignite — the burn-out path re-derives BOTH
// affordances through the same phase-change primitive the melt path uses.
func TestMutator_BurnOutCrumbles(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	beam := &entity.Entity{
		ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindFeature,
		Name: "Балка", Gist: "несущая балка",
	}
	beam.SetThermal(entity.ThermalIgnites)
	beam.SetFracture(entity.FractureRigid)
	if err := repo.Save(ctx, beam); err != nil {
		t.Fatal(err)
	}

	if err := mut.BurnOut(ctx, beam.ID, 7); err != nil {
		t.Fatal(err)
	}
	if beam.CatchesFire() {
		t.Error("a cinder cannot reignite")
	}
	if beam.StateText(entity.StateFracture) != entity.FractureFriable {
		t.Errorf("a charred husk crumbles (рыхлое), no longer snaps, got %q", beam.StateText(entity.StateFracture))
	}
}

// TestMutator_DouseClearsHazardLeavesWet: rain (Douse) puts a fire out leaving the thing WET and
// intact — the hazard is cleared, it cannot immediately reignite (wet suppresses CatchesFire), and
// it is NOT charred to a friable cinder (that is BurnOut). Idempotent on a thing no longer alight.
func TestMutator_DouseClearsHazardLeavesWet(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	shed := &entity.Entity{
		ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindFeature,
		Name: "Навес", Gist: "дощатый навес",
	}
	shed.SetThermal(entity.ThermalIgnites)
	shed.SetFracture(entity.FractureRigid)
	shed.SetHazard(entity.EffectBurn, 3) // alight
	if err := repo.Save(ctx, shed); err != nil {
		t.Fatal(err)
	}

	if err := mut.Douse(ctx, shed.ID, 9); err != nil {
		t.Fatal(err)
	}
	if shed.StateText(entity.StateHazard) != "" {
		t.Errorf("rain must clear the hazard (stop the fire), got %q", shed.StateText(entity.StateHazard))
	}
	if !shed.IsWet() {
		t.Error("rain leaves the thing WET — it cannot immediately reignite")
	}
	if shed.CatchesFire() {
		t.Error("a wet thing does not catch fire (water beats fire)")
	}
	if shed.StateText(entity.StateFracture) == entity.FractureFriable {
		t.Error("douse must NOT char the thing to a friable cinder — that is BurnOut")
	}

	// Idempotent: dousing a thing no longer alight is a no-op.
	if err := mut.Douse(ctx, shed.ID, 10); err != nil {
		t.Fatalf("re-dousing a dead fire must be a no-op, got %v", err)
	}
}

// TestMutator_FillEmptyTracksContents: наполнить fills a vessel, опустошить empties it
// — the contents state the verdict's vessel gates protect.
func TestMutator_FillEmptyTracksContents(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	bucket := &entity.Entity{
		ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindItem,
		Name: "Ведро", Gist: "деревянное ведро",
	}
	bucket.SetContainment(entity.ContainmentVessel)
	if err := repo.Save(ctx, bucket); err != nil {
		t.Fatal(err)
	}

	if _, err := mut.ApplyEffect(ctx, bucket.ID, entity.EffectFill, entity.EffectNote(entity.EffectFill), 3, waterMeans); err != nil {
		t.Fatal(err)
	}
	if !bucket.IsFull() {
		t.Error("наполнить must fill the vessel")
	}
	// Filled WITH water (наполнить requires water), the bucket is now a PORTABLE water
	// source — carry it to a fire and it extinguishes, away from any standing water.
	if bucket.ContentKind() != entity.MeansWater || !bucket.Supplies(entity.MeansWater) {
		t.Errorf("a water-filled bucket must supply water, kind=%q", bucket.ContentKind())
	}
	if _, err := mut.ApplyEffect(ctx, bucket.ID, entity.EffectEmpty, entity.EffectNote(entity.EffectEmpty), 4, nil); err != nil {
		t.Fatal(err)
	}
	if bucket.IsFull() {
		t.Error("опустошить must empty the vessel")
	}
}

// TestMutator_DousingWetsAndDryingDries: водой beats fire mechanically — dousing a
// flammable thing leaves it WET (CatchesFire suppressed), a deliberate drying or the
// tick's DryOut sheds the water and its flammability returns.
func TestMutator_DousingWetsAndDryingDries(t *testing.T) {
	repo := newFakeRepo()
	mut := NewMutator(repo, nil, nil)
	ctx := context.Background()

	stool := &entity.Entity{
		ID: domain.NewEntityID(), WorldID: domain.WorldID("w"), Kind: entity.KindItem,
		Name: "Табурет", Gist: "деревянный табурет",
	}
	stool.SetThermal(entity.ThermalIgnites)
	if err := repo.Save(ctx, stool); err != nil {
		t.Fatal(err)
	}

	// Dousing → wet → will not catch fire. (Soak's water means is mandatory, so the
	// verdict only reaches here with water — the mutator wets regardless of the arg.)
	if _, err := mut.ApplyEffect(ctx, stool.ID, entity.EffectSoak, entity.EffectNote(entity.EffectSoak), 5, waterMeans); err != nil {
		t.Fatal(err)
	}
	if !stool.IsWet() {
		t.Fatal("dousing must leave the thing wet")
	}
	if stool.CatchesFire() {
		t.Error("a doused flammable thing must NOT catch fire")
	}

	// The tick's dry-out sheds the water; flammability returns.
	if err := mut.DryOut(ctx, stool.ID, 40); err != nil {
		t.Fatal(err)
	}
	if stool.IsWet() {
		t.Error("DryOut must shed the wetness")
	}
	if !stool.CatchesFire() {
		t.Error("a dried thing's flammability must return")
	}
}

package knowledge

import (
	"context"
	"fmt"
	"strconv"

	"github.com/dnd-llm/dnd-llm/internal/application/social"
	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/actor"
	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	"github.com/dnd-llm/dnd-llm/internal/domain/front"
	"go.uber.org/zap"
)

// DoomApplier lands a story front's authored doom as a REAL world change — the
// play-side adapter (satisfying weaver.Doom) that maps the closed consequence
// catalogue to live mechanics: a ruined structure closes a location (habitability),
// a catalogue effect changes a thing (the mutator), a soured feeling turns an NPC
// against the player (relationships). It never narrates a doom — that is the front's
// authored prose; this only mutates the world.
type DoomApplier struct {
	entities entity.Repository
	actors   actor.ActorRepository
	mutator  *Mutator
	events   event.EventStore
	logger   *zap.Logger
}

// NewDoomApplier builds the adapter over the entity + actor repositories, the mutator
// and the event store (the disposition doom journals the relationship change there).
func NewDoomApplier(entities entity.Repository, actors actor.ActorRepository, mutator *Mutator, events event.EventStore, logger *zap.Logger) *DoomApplier {
	if logger == nil {
		logger = zap.NewNop()
	}
	return &DoomApplier{entities: entities, actors: actors, mutator: mutator, events: events, logger: logger}
}

// Apply commits the consequence's real outcome. Returns an error when the outcome
// cannot be applied (an unknown target, an unimplemented type) so the weaver logs it
// rather than pretending the world changed.
func (a *DoomApplier) Apply(ctx context.Context, worldID domain.WorldID, c front.Consequence, tick domain.Tick) error {
	switch c.Type {
	case front.ConsequenceRuinLocation:
		return a.ruinLocation(ctx, worldID, domain.LocationID(c.Target), tick)
	case front.ConsequenceRestoreLocation:
		return a.restoreLocation(ctx, worldID, domain.LocationID(c.Target), tick)
	case front.ConsequenceChangeEntity:
		return a.changeEntity(ctx, domain.EntityID(c.Target), c.Detail, tick)
	case front.ConsequenceShiftDisposition:
		return a.shiftDisposition(ctx, worldID, domain.ActorID(c.Target), c.Detail, tick)
	case front.ConsequenceShiftTownDisposition:
		return a.shiftTownDisposition(ctx, worldID, domain.ActorID(c.Target), c.Detail, tick)
	case front.ConsequenceShiftBond:
		return a.shiftBond(ctx, worldID, domain.ActorID(c.Target), domain.ActorID(c.Partner), c.Detail, tick)
	case front.ConsequenceRevealKnowledge:
		return a.revealKnowledge(ctx, worldID, domain.EntityID(c.Target), tick)
	case front.ConsequenceUpdateGist:
		return a.updateGist(ctx, domain.EntityID(c.Target), c.Detail, tick)
	default:
		return fmt.Errorf("doom consequence %q has no applier", c.Type)
	}
}

// revealKnowledge makes an authored truth COMMON KNOWLEDGE — the epistemic doom. The
// target is a lore entity (the authored answer to a mystery, born unknown — in nobody's
// scope). Granting it a world-knows link is the same mechanic a city_wide seed entity
// uses: the truth now surfaces in every actor's knowledge scope (ListKnownBy folds in
// world-knows as common knowledge), so NPCs reference it and the player learns it by
// asking. A discovery is a new knowledge EDGE in the graph, not a counter — this is what
// gives an investigate/gather_info goal a real product. Idempotent: AddLink upserts, so a
// replay re-applies it harmlessly.
func (a *DoomApplier) revealKnowledge(ctx context.Context, worldID domain.WorldID, id domain.EntityID, tick domain.Tick) error {
	truth, err := a.entities.FindByID(ctx, id)
	if err != nil {
		return fmt.Errorf("reveal_knowledge: load truth %s: %w", id, err)
	}
	if err := a.entities.AddLink(ctx, entity.Link{
		EntityID:    id,
		LinkType:    entity.LinkKnows,
		SubjectType: entity.SubjectWorld,
		SubjectID:   worldID.String(),
	}); err != nil {
		return fmt.Errorf("reveal_knowledge: grant world-knows %s: %w", id, err)
	}
	a.logger.Info("knowledge revealed", zap.String("truth", truth.Name), zap.String("entity", id.String()))
	return nil
}

// IsWorldKnown reports whether a truth is ALREADY common knowledge — a world-knows link exists.
// The read side of revealKnowledge, mirroring TruthReader.IsWorldKnown over the same repository, so
// a consumer that already holds the applier (the goal-outcome path) can ask «is this discovery still
// news?» without a second dependency. A gather_info goal whose authored reveal already happened (the
// player, or another seeker, uncovered the truth first) must not re-narrate it as a fresh find.
func (a *DoomApplier) IsWorldKnown(ctx context.Context, id domain.EntityID) (bool, error) {
	links, err := a.entities.ListLinks(ctx, id)
	if err != nil {
		return false, err
	}
	for _, l := range links {
		if l.LinkType == entity.LinkKnows && l.SubjectType == entity.SubjectWorld {
			return true, nil
		}
	}
	return false, nil
}

// updateGist rewrites a lore entity's gist to a new authored text — the EPISTEMIC CURRENCY a
// favourable front resolution lands so its WORLD-KNOWN Discovery reads in the PAST («река ЗАМИРАЛА
// из-за груза; теперь убран, течёт свободно»), not as an ongoing crisis the player already fixed.
// Measured: the small model faithfully reads the current gist, so a past-tense rewrite is what makes
// dialogue reflect the resolution (a mutable CONDITION did NOT — the model weighs the gist). A direct
// persisted write, not event-folded (entities are stored state, reset only by reseed); silent (the
// resolution narrates its own prose). Idempotent and best-effort.
func (a *DoomApplier) updateGist(ctx context.Context, id domain.EntityID, gist string, _ domain.Tick) error {
	if gist == "" {
		return nil
	}
	e, err := a.entities.FindByID(ctx, id)
	if err != nil {
		return fmt.Errorf("update_gist: load %s: %w", id, err)
	}
	if e.Gist == gist {
		return nil // already in place — a replay or double-apply is a no-op
	}
	e.Gist = gist
	if err := a.entities.Save(ctx, e); err != nil {
		return fmt.Errorf("update_gist: persist %s: %w", id, err)
	}
	a.logger.Info("lore gist rewritten on favourable resolution", zap.String("entity", id.String()), zap.String("name", e.Name))
	return nil
}

// ruinLocation destroys the location's LOAD-BEARING structure(s), so the habitability
// reflex closes the place — a ford that freezes shut, a hall that falls. Reuses the
// authored «несущее» role the structure carries.
func (a *DoomApplier) ruinLocation(ctx context.Context, worldID domain.WorldID, loc domain.LocationID, tick domain.Tick) error {
	present, err := a.entities.ListPresentAt(ctx, worldID, loc, nil)
	if err != nil {
		return fmt.Errorf("list structures at %s: %w", loc, err)
	}
	ruined := 0
	for _, e := range present {
		if !e.IsLoadBearing() {
			continue
		}
		if err := a.mutator.Ruin(ctx, e.ID, tick); err != nil {
			a.logger.Warn("ruin structure failed", zap.String("entity", e.Name), zap.Error(err))
			continue
		}
		ruined++
	}
	if ruined == 0 {
		return fmt.Errorf("ruin_location %s: no load-bearing structure to destroy", loc)
	}
	return nil
}

// restoreLocation MENDS the location's ruined load-bearing structure(s), so the
// habitability reflex reopens the place — the deliberate inverse of ruinLocation (a
// frozen-shut ford cleared, a fallen hall raised). Best-effort and idempotent: a
// place with nothing ruined is simply left as-is (the remedy still resolves
// favourably and narrates), so restoring BEFORE the doom ever fell is a clean no-op
// rather than an error — unlike ruin, healing nothing is success, not failure.
func (a *DoomApplier) restoreLocation(ctx context.Context, worldID domain.WorldID, loc domain.LocationID, tick domain.Tick) error {
	present, err := a.entities.ListPresentAt(ctx, worldID, loc, nil)
	if err != nil {
		return fmt.Errorf("list structures at %s: %w", loc, err)
	}
	for _, e := range present {
		if !e.IsLoadBearing() {
			continue
		}
		if err := a.mutator.Restore(ctx, e.ID, tick); err != nil {
			a.logger.Warn("restore structure failed", zap.String("entity", e.Name), zap.Error(err))
		}
	}
	return nil
}

// changeEntity drives a thing through a catalogue effect (the same mutator path a
// player deed takes) — a thing breaks, spoils, freezes. Detail is the effect key.
func (a *DoomApplier) changeEntity(ctx context.Context, id domain.EntityID, effect string, tick domain.Tick) error {
	note := entity.EffectNote(effect)
	if note == "" {
		return fmt.Errorf("change_entity: unknown effect %q", effect)
	}
	// A front's doom applies the effect impersonally (a collapse, a frost) — no wielded
	// means; a means-optional effect (a fire going out) thus takes its no-means outcome.
	_, err := a.mutator.ApplyEffect(ctx, id, effect, note, tick, nil)
	return err
}

// shiftDisposition sours (or warms) an NPC's standing feeling toward the player — the
// social doom: the town's ferryman, watching the player ignore the drowning crisis,
// comes to distrust them for good. Detail is the signed delta (e.g. "-35"). Reuses the
// shared relationship primitive and journals the change like any other, so the soured
// trust persists, replays, and colours every later exchange.
func (a *DoomApplier) shiftDisposition(ctx context.Context, worldID domain.WorldID, targetID domain.ActorID, detail string, tick domain.Tick) error {
	delta, err := strconv.Atoi(detail)
	if err != nil {
		return fmt.Errorf("shift_disposition: detail %q is not a signed delta: %w", detail, err)
	}
	target, err := a.actors.FindByID(ctx, targetID)
	if err != nil {
		return fmt.Errorf("shift_disposition: load target %s: %w", targetID, err)
	}
	players, err := a.actors.FindByType(ctx, actor.ActorTypePlayer)
	if err != nil || len(players) == 0 {
		return fmt.Errorf("shift_disposition: no player to turn against (%v)", err)
	}
	player := players[0]

	events := social.ShiftRelationship(target, player, delta, "перелом", worldID, tick)
	if err := a.actors.Update(ctx, target); err != nil {
		return fmt.Errorf("shift_disposition: persist %s: %w", target.ID, err)
	}
	for _, evt := range events {
		if err := a.events.Append(ctx, evt); err != nil {
			a.logger.Warn("shift_disposition: journal relationship change failed", zap.Error(err))
		}
	}
	return nil
}

// shiftTownDisposition turns the WHOLE town's standing feeling toward one NPC — the
// social doom where suspicion (or gratitude) spreads through the streets: every living
// townsperson's feeling toward the target shifts by Detail (a signed delta). The NPC↔NPC
// counterpart of shiftDisposition, for outcomes between townsfolk — a scapegoat shunned,
// a hero embraced. Reuses the shared relationship primitive per person and journals each
// change, so the new standing persists and replays.
func (a *DoomApplier) shiftTownDisposition(ctx context.Context, worldID domain.WorldID, targetID domain.ActorID, detail string, tick domain.Tick) error {
	delta, err := strconv.Atoi(detail)
	if err != nil {
		return fmt.Errorf("shift_town_disposition: detail %q is not a signed delta: %w", detail, err)
	}
	target, err := a.actors.FindByID(ctx, targetID)
	if err != nil {
		return fmt.Errorf("shift_town_disposition: load target %s: %w", targetID, err)
	}
	town, err := a.actors.FindByWorld(ctx, worldID)
	if err != nil {
		return fmt.Errorf("shift_town_disposition: load town: %w", err)
	}
	shifted := 0
	for _, npc := range town {
		if npc.ID == targetID || npc.Type == actor.ActorTypePlayer {
			continue // the target does not turn on themselves; the player is not "the town"
		}
		events := social.ShiftRelationship(npc, target, delta, "молва", worldID, tick)
		if err := a.actors.Update(ctx, npc); err != nil {
			a.logger.Warn("shift_town_disposition: persist failed", zap.String("npc", npc.ID.String()), zap.Error(err))
			continue
		}
		for _, evt := range events {
			if err := a.events.Append(ctx, evt); err != nil {
				a.logger.Warn("shift_town_disposition: journal failed", zap.Error(err))
			}
		}
		shifted++
	}
	if shifted == 0 {
		return fmt.Errorf("shift_town_disposition: no townsfolk to turn")
	}
	return nil
}

// shiftBond turns the MUTUAL feeling between two named NPCs by the same signed delta in
// BOTH directions — a bond is mutual, so reconciling (or estranging) them moves each
// toward (or from) the other symmetrically. Reuses the shared relationship primitive and
// journals each side, so the new standing persists and replays. The two must be distinct
// real NPCs (a bond needs two souls); a self-bond or a missing party is an authoring error.
func (a *DoomApplier) shiftBond(ctx context.Context, worldID domain.WorldID, aID, bID domain.ActorID, detail string, tick domain.Tick) error {
	delta, err := strconv.Atoi(detail)
	if err != nil {
		return fmt.Errorf("shift_bond: detail %q is not a signed delta: %w", detail, err)
	}
	if aID == bID || aID == "" || bID == "" {
		return fmt.Errorf("shift_bond: needs two distinct NPCs, got %q and %q", aID, bID)
	}
	first, err := a.actors.FindByID(ctx, aID)
	if err != nil {
		return fmt.Errorf("shift_bond: load %s: %w", aID, err)
	}
	second, err := a.actors.FindByID(ctx, bID)
	if err != nil {
		return fmt.Errorf("shift_bond: load %s: %w", bID, err)
	}
	events := social.ShiftRelationship(first, second, delta, "перемена", worldID, tick)
	events = append(events, social.ShiftRelationship(second, first, delta, "перемена", worldID, tick)...)
	if err := a.actors.Update(ctx, first); err != nil {
		return fmt.Errorf("shift_bond: persist %s: %w", first.ID, err)
	}
	if err := a.actors.Update(ctx, second); err != nil {
		return fmt.Errorf("shift_bond: persist %s: %w", second.ID, err)
	}
	for _, evt := range events {
		if err := a.events.Append(ctx, evt); err != nil {
			a.logger.Warn("shift_bond: journal relationship change failed", zap.Error(err))
		}
	}
	return nil
}

