// grantJusticeDrives gives a wronged StoryNPC a SEEK-JUSTICE drive against the
// offender, whose fulfilment marks the wrongdoer (ShiftTownDisposition). Granted
// once; the player and the dead get none.
func TestGrantJusticeDrives(t *testing.T) {
	const (
		world = domain.WorldID("w")
		loc   = domain.LocationID("l")
	)
	now := domain.Tick(50)
	victim := bodied(loc, 20)
	victim.Type = actor.ActorTypeStoryNPC
	offender := bodied(loc, 20)
	guard := guarding(bodied(domain.LocationID("guardhouse"), 20), domain.LocationID("guardhouse"))

	store := &fakeEventStore{events: []*event.GameEvent{
		damageEvent(victim.ID, actorPtr(offender.ID), "attack", loc, world, now),
	}}
	tracker := appgoal.NewGoalTracker()
	p := &TickProcessor{eventStore: store, goalTracker: tracker}
	byID := map[domain.ActorID]*actor.Actor{victim.ID: victim, offender.ID: offender, guard.ID: guard}

	events := p.grantJusticeDrives(context.Background(), domain.GameTime{Tick: now}, world, byID)

	g := tracker.Active(victim.ID)
	if g == nil || g.Type != goaldom.GoalTypeSeekJustice {
		t.Fatalf("a wronged soul must take up a justice drive, got %v", g)
	}
	// Seek justice routes toward the LAW (the guard), not the attacker — the report
	// loop's first leg. WHO answers (the offender) lives in the Outcome, not the target.
	if g.Target.ActorID == nil || *g.Target.ActorID != guard.ID {
		t.Errorf("the drive must route toward the guard, got %v", g.Target.ActorID)
	}
	if g.Outcome == nil || g.Outcome.Type != front.ConsequenceShiftTownDisposition || g.Outcome.Target != string(offender.ID) {
		t.Errorf("fulfilment must turn the town against the offender, got %+v", g.Outcome)
	}
	if g.Outcome != nil && g.Outcome.Detail != "-20" {
		t.Errorf("the crime's sanction delta: got %q want -20", g.Outcome.Detail)
	}
	if !hasObservation(events) {
		t.Error("a closed status beat must surface")
	}

	// Idempotent: a second strike does not re-stamp the drive.
	before := tracker.Active(victim.ID).ID
	store.events = append(store.events, damageEvent(victim.ID, actorPtr(offender.ID), "attack", loc, world, now))
	p.grantJusticeDrives(context.Background(), domain.GameTime{Tick: now}, world, byID)
	if tracker.Active(victim.ID).ID != before {
		t.Error("an already-pursued justice drive must not be re-granted")
	}
}

// TestPickLawward: a wronged soul seeking justice heads toward a GUARD (the law) —
// never the attacker, never a non-guard — deterministically (sorted), and nowhere when
// the town has no watch.
func TestPickLawward(t *testing.T) {
	loc := domain.LocationID("ford")
	post := domain.LocationID("guardhouse")

	victim := bodied(loc, 20)
	offender := bodied(loc, 20)
	townsperson := bodied(loc, 20) // not a guard
	guardA := guarding(bodied(post, 20), post)
	guardB := guarding(bodied(post, 20), post)
	byID := map[domain.ActorID]*actor.Actor{
		victim.ID: victim, offender.ID: offender, townsperson.ID: townsperson,
		guardA.ID: guardA, guardB.ID: guardB,
	}

	got := pickLawward(byID, victim.ID, offender.ID)
	if got == nil {
		t.Fatal("with guards present, a victim must have a lawman to seek")
	}
	if *got != guardA.ID && *got != guardB.ID {
		t.Errorf("the lawward must be a GUARD (not victim/offender/townsperson), got %s", *got)
	}
	if again := pickLawward(byID, victim.ID, offender.ID); again == nil || *again != *got {
		t.Error("pickLawward must be deterministic across calls (sorted, not map-order)")
	}

	// No watch: nowhere to report (the goal still grants, but routes nowhere).
	noGuards := map[domain.ActorID]*actor.Actor{victim.ID: victim, offender.ID: offender, townsperson.ID: townsperson}
	if pickLawward(noGuards, victim.ID, offender.ID) != nil {
		t.Error("no guard about → no lawward to seek")
	}

	// The offending guard is excluded — you don't report to your own attacker.
	rogue := guarding(bodied(loc, 20), loc)
	if pickLawward(map[domain.ActorID]*actor.Actor{victim.ID: victim, rogue.ID: rogue}, victim.ID, rogue.ID) != nil {
		t.Error("the offending guard must be excluded — nowhere else to go")
	}
}

// TestProcessJusticeReports: a wronged soul who has REACHED the guard they sought files
// the crime — the law learns of it (the offender goes on the guard's confront-on-sight
// ledger), the seeking ends, and the guard is marked dirty to persist. A victim NOT yet
// co-located with the guard files nothing.
func TestProcessJusticeReports(t *testing.T) {
	const world = domain.WorldID("w")
	post := domain.LocationID("guardhouse")
	now := domain.GameTime{Tick: 60}

	mkSeeker := func(victimLoc domain.LocationID, guardID, offenderID domain.ActorID, tr *appgoal.GoalTracker) *actor.Actor {
		v := bodied(victimLoc, 20)
		v.Type = actor.ActorTypeStoryNPC
		g := goaldom.NewGoal(v.ID, goaldom.GoalTypeSeekJustice, "добиться правосудия", goaldom.PriorityHigh, now)
		off := offenderID
		gd := guardID
		g.Target = goaldom.GoalTarget{ActorID: &gd}
		g.Outcome = &front.Consequence{Type: front.ConsequenceShiftTownDisposition, Target: string(off), Detail: "-20"}
		tr.Add(v.ID, g)
		return v
	}

	offender := bodied(post, 20)

	// Reached the guard: the report lands.
	tr := appgoal.NewGoalTracker()
	guard := guarding(bodied(post, 20), post)
	victim := mkSeeker(post, guard.ID, offender.ID, tr) // same location as the guard
	p := &TickProcessor{goalTracker: tr}
	byID := map[domain.ActorID]*actor.Actor{victim.ID: victim, guard.ID: guard, offender.ID: offender}

	events, dirty := p.processJusticeReports(context.Background(), now, world, byID)
	if !dirty[guard.ID] {
		t.Error("a guard who took a report must be persisted (their ledger changed)")
	}
	if tr.Active(victim.ID) != nil {
		t.Error("the seeking ends once the report is filed")
	}
	if rel := guard.State.Social.GetRelationship(offender.ID); rel == nil || rel.Respect > actor.CrimeWitnessRespect {
		t.Errorf("the law must now hold the offender on its confront-on-sight ledger, got %+v", rel)
	}
	if !hasObservation(events) {
		t.Error("filing a report must surface a beat")
	}
	// Stage 3: the guard who took the report goes AFTER the offender (an apprehend drive).
	if gp := tr.Active(guard.ID); gp == nil || gp.Type != goaldom.GoalTypeApprehend ||
		gp.Target.ActorID == nil || *gp.Target.ActorID != offender.ID {
		t.Errorf("the reporting guard must take up pursuit of the offender, got %v", gp)
	}

	// Not yet reached: no report, the drive persists.
	tr2 := appgoal.NewGoalTracker()
	guard2 := guarding(bodied(post, 20), post)
	seeker2 := mkSeeker(domain.LocationID("ford"), guard2.ID, offender.ID, tr2) // far from the guard
	p2 := &TickProcessor{goalTracker: tr2}
	byID2 := map[domain.ActorID]*actor.Actor{seeker2.ID: seeker2, guard2.ID: guard2, offender.ID: offender}
	_, dirty2 := p2.processJusticeReports(context.Background(), now, world, byID2)
	if dirty2[guard2.ID] || tr2.Active(seeker2.ID) == nil {
		t.Error("a victim who has not reached the guard files nothing — the drive persists")
	}
}

// TestGrantGuardPursuit: a guard set on a known offender takes up an APPREHEND drive
// toward them (routes there via existing goal-movement), granted once — a guard already
// hunting that offender is not re-stamped.
func TestGrantGuardPursuit(t *testing.T) {
	now := domain.GameTime{Tick: 70}
	guard := guarding(bodied(domain.LocationID("post"), 20), domain.LocationID("post"))
	offender := bodied(domain.LocationID("ford"), 20)
	tr := appgoal.NewGoalTracker()

	grantGuardPursuit(tr, guard, offender.ID, offender.State.GetCurrentLocation(), now)
	g := tr.Active(guard.ID)
	if g == nil || g.Type != goaldom.GoalTypeApprehend || g.Target.ActorID == nil || *g.Target.ActorID != offender.ID {
		t.Fatalf("a guard must take up pursuit of the offender, got %v", g)
	}
	if g.Type.IsOngoing() {
		t.Error("apprehend is a bounded milestone, not a standing post — the guard returns to rounds")
	}

	// Idempotent: re-granting the SAME pursuit does not replace the running goal.
	before := g.ID
	grantGuardPursuit(tr, guard, offender.ID, offender.State.GetCurrentLocation(), now)
	if tr.Active(guard.ID).ID != before {
		t.Error("a guard already hunting this offender must not be re-stamped")
	}
}

// TestProcessApprehensions: a pursuing guard who REACHES the offender makes the collar —
// the offender comes to dread the watch, a beat surfaces, and the apprehend drive
// completes. A guard not yet caught up keeps hunting.
func TestProcessApprehensions(t *testing.T) {
	const world = domain.WorldID("w")
	now := domain.GameTime{Tick: 80}
	loc := domain.LocationID("alley")

	mkHunter := func(guardLoc domain.LocationID, offenderID domain.ActorID, tr *appgoal.GoalTracker) *actor.Actor {
		guard := guarding(bodied(guardLoc, 20), domain.LocationID("post"))
		grantGuardPursuit(tr, guard, offenderID, guardLoc, now)
		return guard
	}

	// Caught up: the collar lands.
	offender := bodied(loc, 20)
	offender.Type = actor.ActorTypeStoryNPC
	tr := appgoal.NewGoalTracker()
	guard := mkHunter(loc, offender.ID, tr) // same location as the offender
	p := &TickProcessor{goalTracker: tr}
	byID := map[domain.ActorID]*actor.Actor{guard.ID: guard, offender.ID: offender}

	events, dirty := p.processApprehensions(context.Background(), now, world, byID)
	if !dirty[offender.ID] {
		t.Error("a collared offender's lasting fear must be persisted")
	}
	if rel := offender.State.Social.GetRelationship(guard.ID); rel == nil || rel.Fear < apprehendFear {
		t.Errorf("a caught soul must come to dread the watch, got %+v", rel)
	}
	// Taken into custody: held fast (movement-locked) — actually detained, not just scolded.
	if !offender.State.Physical.Health.HasCondition(actor.ConditionRestrained) {
		t.Error("a collared offender must be taken into custody (restrained)")
	}
	if offender.State.CanMove() {
		t.Error("a detained offender is movement-locked until they wrestle loose")
	}
	if tr.Active(guard.ID) != nil {
		t.Error("the apprehend drive completes on the collar — the guard returns to rounds")
	}
	if !hasObservation(events) {
		t.Error("the collar must surface a beat")
	}

	// Not caught up: the hunt continues.
	offender2 := bodied(loc, 20)
	offender2.Type = actor.ActorTypeStoryNPC
	tr2 := appgoal.NewGoalTracker()
	guard2 := mkHunter(domain.LocationID("far"), offender2.ID, tr2) // elsewhere
	p2 := &TickProcessor{goalTracker: tr2}
	byID2 := map[domain.ActorID]*actor.Actor{guard2.ID: guard2, offender2.ID: offender2}
	_, dirty2 := p2.processApprehensions(context.Background(), now, world, byID2)
	if dirty2[offender2.ID] || tr2.Active(guard2.ID) == nil {
		t.Error("a guard not yet caught up makes no collar — the hunt continues")
	}
}

// TestRefreshPursuitTrail: the watch tracks by SIGHTINGS, not telepathy — an offender seen
// by ANY guard refreshes every hunter's last-known place to that spot; an offender no guard
// can see leaves the trail frozen at the last sighting (the hunter heads to a cold scene).
func TestRefreshPursuitTrail(t *testing.T) {
	now := domain.GameTime{Tick: 90}
	a, b, stale := domain.LocationID("a"), domain.LocationID("b"), domain.LocationID("scene")
	offender := bodied(b, 20) // currently at b

	// A hunter at a, whose trail is stale (last knew the offender at the scene).
	tr := appgoal.NewGoalTracker()
	hunter := guarding(bodied(a, 20), domain.LocationID("post"))
	grantGuardPursuit(tr, hunter, offender.ID, stale, now)
	// A spotter standing WITH the offender at b — the watch has eyes on them.
	spotter := guarding(bodied(b, 20), domain.LocationID("post"))
	grantGuardPursuit(tr, spotter, offender.ID, stale, now)

	p := &TickProcessor{goalTracker: tr}
	byID := map[domain.ActorID]*actor.Actor{hunter.ID: hunter, spotter.ID: spotter, offender.ID: offender}
	p.refreshPursuitTrail(byID, now)

	if loc := tr.Active(hunter.ID).Target.LocationID; loc == nil || *loc != b {
		t.Errorf("a sighting (spotter with the offender at b) must refresh the hunter's trail to b, got %v", loc)
	}

	// No eyes on the offender: the trail freezes at the last sighting (cold scene).
	lone := bodied(b, 20) // the offender, alone, no guard co-located
	tr2 := appgoal.NewGoalTracker()
	hunter2 := guarding(bodied(a, 20), domain.LocationID("post"))
	grantGuardPursuit(tr2, hunter2, lone.ID, stale, now)
	p2 := &TickProcessor{goalTracker: tr2}
	p2.refreshPursuitTrail(map[domain.ActorID]*actor.Actor{hunter2.ID: hunter2, lone.ID: lone}, now)
	if loc := tr2.Active(hunter2.ID).Target.LocationID; loc == nil || *loc != stale {
		t.Errorf("with no guard seeing the offender, the trail stays cold at the last sighting, got %v", loc)
	}
}

// TestPursuitGivesUpWhenTrailColdTooLong: a hunt whose trail stays cold past pursuitPatience is
// ABANDONED — the watch returns to post rather than chase a ghost forever (without this, once
// routine guards joined the hunt the whole watch would desert its posts on any unsolved crime).
func TestPursuitGivesUpWhenTrailColdTooLong(t *testing.T) {
	const world = domain.WorldID("w")
	start := domain.GameTime{Tick: 100}
	scene := domain.LocationID("scene")

	guard := guarding(bodied(scene, 20), domain.LocationID("post"))
	offender := bodied(domain.LocationID("gone"), 20) // slipped away for good — never seen again
	tr := appgoal.NewGoalTracker()
	grantGuardPursuit(tr, guard, offender.ID, scene, start)
	p := &TickProcessor{goalTracker: tr}
	byID := map[domain.ActorID]*actor.Actor{guard.ID: guard}

	deadline := start.Add(pursuitPatience)

	// Still within patience: the hunt holds.
	if evts := p.expireColdPursuits(domain.NewGameTimeAt(deadline.Tick-1), world, byID); len(evts) != 0 {
		t.Fatalf("a trail still within patience must NOT be given up, got %d beats", len(evts))
	}
	if tr.Active(guard.ID) == nil {
		t.Fatalf("the pursuit must still be active within patience")
	}

	// Past patience with no sighting: the hunt is abandoned, with one terse beat.
	evts := p.expireColdPursuits(domain.NewGameTimeAt(deadline.Tick+1), world, byID)
	if len(evts) != 1 || evts[0].Type != event.EventTypeObservation {
		t.Fatalf("a cold trail past patience must be abandoned with one observation beat, got %v", evts)
	}
	if g := tr.Active(guard.ID); g != nil && g.Type == goaldom.GoalTypeApprehend {
		t.Errorf("the abandoned pursuit must be dropped, but it is still active")
	}
}

// TestSightingRenewsPursuitPatience: a fresh sighting pushes the give-up horizon out, so a
// quarry kept in view is chased indefinitely — only the COLD stretch runs out, not the hunt.
func TestSightingRenewsPursuitPatience(t *testing.T) {
	const world = domain.WorldID("w")
	start := domain.GameTime{Tick: 100}
	b := domain.LocationID("b")

	offender := bodied(b, 20)
	guard := guarding(bodied(b, 20), domain.LocationID("post")) // co-located with the offender → a sighting
	tr := appgoal.NewGoalTracker()
	grantGuardPursuit(tr, guard, offender.ID, domain.LocationID("scene"), start)
	p := &TickProcessor{goalTracker: tr}
	byID := map[domain.ActorID]*actor.Actor{guard.ID: guard, offender.ID: offender}

	// A sighting just before the ORIGINAL deadline renews patience from that moment.
	original := start.Add(pursuitPatience)
	p.refreshPursuitTrail(byID, domain.NewGameTimeAt(original.Tick-1))

	// Past the ORIGINAL deadline but within the RENEWED one: the hunt holds, not abandoned.
	if evts := p.expireColdPursuits(domain.NewGameTimeAt(original.Tick+1), world, byID); len(evts) != 0 {
		t.Fatalf("a sighting must renew patience past the original deadline, got %d give-ups", len(evts))
	}
	if tr.Active(guard.ID) == nil {
		t.Errorf("the renewed pursuit must still be active")
	}
}

// TestApprehendColdTrailSearches: a hunter who has reached the last-known place and found
// it COLD (the offender not in sight) does not trudge back to post — it SEARCHES, wandering
// the vicinity toward where people (and clues) are, until a sighting reheats the trail.
func TestApprehendColdTrailSearches(t *testing.T) {
	now := domain.GameTime{Tick: 100}
	scene, post, market := domain.LocationID("scene"), domain.LocationID("post"), domain.LocationID("market")

	guard := guarding(bodied(scene, 20), post) // at the cold last-known scene; home post is elsewhere
	townsfolk := bodied(market, 20)            // company — the one lively spot the search heads for
	offender := bodied(market, 20)             // slipped into the market crowd (unknown to the guard)

	tr := appgoal.NewGoalTracker()
	grantGuardPursuit(tr, guard, offender.ID, scene, now) // last-known == here → trail is cold
	p := &TickProcessor{goalTracker: tr}
	// The market is the SOLE occupied venue away from the cold scene, so the wandering search
	// has one deterministic target — toward company, where clues and the melted-in quarry are.
	byID := map[domain.ActorID]*actor.Actor{guard.ID: guard, offender.ID: offender, townsfolk.ID: townsfolk}

	dest, forced := p.purposefulDestination(guard, now, byID)
	if dest == post || dest == scene || dest.IsZero() {
		t.Errorf("a cold trail must make the guard SEARCH the vicinity, not return to post or stand still, got %q", dest)
	}
	if dest != market {
		t.Errorf("the search heads toward company (where clues and the quarry are), want %q got %q", market, dest)
	}
	if forced {
		t.Errorf("a cold-trail SEARCH is exploratory dwelling, not forced presence — it must respect venue capacity")
	}
}

// The player seeks redress by command, not by an autonomous drive; a non-StoryNPC
// victim gets no justice goal.
func TestGrantJusticeDrives_SkipsNonStoryNPC(t *testing.T) {
	const (
		world = domain.WorldID("w")
		loc   = domain.LocationID("l")
	)
	now := domain.Tick(50)
	player := bodied(loc, 20)
	player.Type = actor.ActorTypePlayer
	offender := bodied(loc, 20)

	store := &fakeEventStore{events: []*event.GameEvent{
		damageEvent(player.ID, actorPtr(offender.ID), "attack", loc, world, now),
	}}
	tracker := appgoal.NewGoalTracker()
	p := &TickProcessor{eventStore: store, goalTracker: tracker}
	byID := map[domain.ActorID]*actor.Actor{player.ID: player, offender.ID: offender}

	p.grantJusticeDrives(context.Background(), domain.GameTime{Tick: now}, world, byID)
	if tracker.Active(player.ID) != nil {
		t.Error("the player carries no autonomous justice drive")
	}
}

package turn

import (
	"context"
	"testing"

	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/actor"
	"github.com/dnd-llm/dnd-llm/internal/domain/check"
	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
)

// bodied builds an actor with a real combat body (HP) at a place — able to strike and be struck.
func bodied(loc domain.LocationID, hp int) *actor.Actor {
	id := domain.NewActorID()
	st := actor.NewActorState(id, hp, domain.GameTime{})
	st.StateContext = &actor.IdleContext{Location: loc}
	return &actor.Actor{ID: id, State: st}
}

func damageEvent(victim domain.ActorID, source *domain.ActorID, src string, loc domain.LocationID, world domain.WorldID, tick domain.Tick) *event.GameEvent {
	return event.NewGameEvent(event.EventTypeDamageTaken, victim, loc, world, tick,
		event.DamageEventData{VictimID: victim, SourceID: source, Damage: 4, DamageType: "physical", Source: src})
}

// freshStrikeVictims folds only THIS tick's deliberate (source "attack") named blows into
// victim→attacker; fire/environment, sourceless and stale blows provoke no counter.
func TestFreshStrikeVictims(t *testing.T) {
	const (
		world = domain.WorldID("w")
		loc   = domain.LocationID("l")
	)
	now := domain.Tick(100)
	victim, attacker := domain.NewActorID(), domain.NewActorID()

	store := &fakeEventStore{events: []*event.GameEvent{
		damageEvent(victim, actorPtr(attacker), "attack", loc, world, now),                // a real blow → counts
		damageEvent(domain.NewActorID(), actorPtr(attacker), "fire", loc, world, now),     // fire → ignored
		damageEvent(domain.NewActorID(), nil, "attack", loc, world, now),                  // no striker → ignored
		damageEvent(domain.NewActorID(), actorPtr(attacker), "attack", loc, world, now-1), // stale → ignored
	}}

	got := freshStrikeVictims(context.Background(), store, world, now)
	if len(got) != 1 {
		t.Fatalf("only the fresh, named, deliberate blow should count: got %d entries %v", len(got), got)
	}
	if got[victim] != attacker {
		t.Errorf("victim should map to its attacker: got %v", got[victim])
	}
}

// resolveRetaliation commits the counter's harm and a closed status beat; a landed counter drops
// the target's HP and journals a DamageTaken sourced to the counter-striker.
func TestResolveRetaliation_LandsAndBeats(t *testing.T) {
	const (
		world = domain.WorldID("w")
		loc   = domain.LocationID("l")
	)
	clean := func(_ int64, _ int, pos check.Position) check.Outcome {
		return check.Outcome{Tier: check.Clean, Position: pos}
	}
	p := &TickProcessor{checkRoll: clean}
	npc := bodied(loc, 20)
	target := bodied(loc, 20)
	before := target.State.Physical.Health.Current

	events := p.resolveRetaliation(context.Background(), npc, target, domain.GameTime{Tick: 5}, world)

	var harmed, beat bool
	for _, e := range events {
		switch e.Type {
		case event.EventTypeDamageTaken:
			harmed = true
		case event.EventTypeObservation:
			beat = true
		}
	}
	if !harmed {
		t.Error("a clean counter must journal harm on the target")
	}
	if !beat {
		t.Error("a counter must surface a closed status beat")
	}
	if target.State.Physical.Health.Current >= before {
		t.Errorf("a landed counter must drop the target's HP: before=%d after=%d", before, target.State.Physical.Health.Current)
	}
}

// heldGear reads an actor's OWNED gear (weapon armament + parry/armour defence), strictly
// holder-owned via ListOwnedPresentAt — so a counter-strike uses the NPC's own weapon, not the
// racked blades of the room.
func TestHeldGear_OwnedOnly(t *testing.T) {
	loc := domain.LocationID("l")
	guard := bodied(loc, 20)
	weapon := &entity.Entity{ID: domain.NewEntityID(), Name: "Сабля", Category: entity.CategoryWeapon}
	mail := &entity.Entity{ID: domain.NewEntityID(), Name: "Кольчуга",
		State: entity.EntityState{Tags: []string{"броня"}}}

	p := &TickProcessor{hazards: &fakeHazards{owned: map[domain.ActorID][]*entity.Entity{
		guard.ID: {weapon, mail},
	}}}
	armament, defence, load := p.heldGear(context.Background(), domain.WorldID("w"), guard)
	if armament != 2 { // CategoryWeapon.MartialForce
		t.Errorf("a wielded weapon must lend armament 2, got %d", armament)
	}
	if defence != 3 { // sabre ParryGuard 1 + mail ArmorRating 2
		t.Errorf("parry+armour must lend defence 3, got %d", defence)
	}
	if load <= 0 { // a wielded weapon + worn mail have heft — feeds the counter-strike hindrance
		t.Errorf("held gear must sum a carried load, got %d", load)
	}

	// An empty-handed actor lends nothing — no leaked co-located gear.
	bare := bodied(loc, 20)
	if a, d, l := p.heldGear(context.Background(), domain.WorldID("w"), bare); a != 0 || d != 0 || l != 0 {
		t.Errorf("bare-handed must lend 0/0/0, got %d/%d/%d", a, d, l)
	}
}

func TestRetaliationHelpers(t *testing.T) {
	loc := domain.LocationID("l")
	if retaliationBeat(actor.ViolenceResult{TargetHarm: actor.HarmNone}) == retaliationBeat(actor.ViolenceResult{TargetHarm: actor.HarmWounded}) {
		t.Error("a whiffed counter must read differently from a landed one")
	}

	able := bodied(loc, 20)
	if !canFightBack(able) {
		t.Error("a healthy actor can fight back")
	}
	if isSenseless(able) {
		t.Error("a healthy actor is not senseless")
	}
	down := bodied(loc, 20)
	down.State.Physical.BecomeUnconscious()
	if canFightBack(down) {
		t.Error("a senseless actor cannot fight back")
	}
	if !isSenseless(down) {
		t.Error("an unconscious actor is senseless")
	}

	here, there := bodied(loc, 20), bodied(domain.LocationID("o"), 20)
	if !coLocatedActors(able, here) {
		t.Error("actors in the same place are co-located")
	}
	if coLocatedActors(able, there) {
		t.Error("actors in different places are not co-located")
	}
}

