package turn

import (
	"context"
	"testing"

	appgoal "github.com/dnd-llm/dnd-llm/internal/application/goal"
	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/actor"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	"github.com/dnd-llm/dnd-llm/internal/domain/front"
	goaldom "github.com/dnd-llm/dnd-llm/internal/domain/goal"
)

// grantJusticeDrives gives a wronged StoryNPC a SEEK-JUSTICE drive against the
// offender, whose fulfilment marks the wrongdoer (ShiftTownDisposition). Granted
// once; the player and the dead get none.
func TestGrantJusticeDrives(t *testing.T) {
	const (
		world = domain.WorldID("w")
		loc   = domain.LocationID("l")
	)
	now := domain.Tick(50)
	victim := bodied(loc, 20)
	victim.Type = actor.ActorTypeStoryNPC
	offender := bodied(loc, 20)
	guard := guarding(bodied(domain.LocationID("guardhouse"), 20), domain.LocationID("guardhouse"))

	store := &fakeEventStore{events: []*event.GameEvent{
		damageEvent(victim.ID, actorPtr(offender.ID), "attack", loc, world, now),
	}}
	tracker := appgoal.NewGoalTracker()
	p := &TickProcessor{eventStore: store, goalTracker: tracker}
	byID := map[domain.ActorID]*actor.Actor{victim.ID: victim, offender.ID: offender, guard.ID: guard}

	events := p.grantJusticeDrives(context.Background(), domain.GameTime{Tick: now}, world, byID)

	g := tracker.Active(victim.ID)
	if g == nil || g.Type != goaldom.GoalTypeSeekJustice {
		t.Fatalf("a wronged soul must take up a justice drive, got %v", g)
	}
	// Seek justice routes toward the LAW (the guard), not the attacker — the report
	// loop's first leg. WHO answers (the offender) lives in the Outcome, not the target.
	if g.Target.ActorID == nil || *g.Target.ActorID != guard.ID {
		t.Errorf("the drive must route toward the guard, got %v", g.Target.ActorID)
	}
	if g.Outcome == nil || g.Outcome.Type != front.ConsequenceShiftTownDisposition || g.Outcome.Target != string(offender.ID) {
		t.Errorf("fulfilment must turn the town against the offender, got %+v", g.Outcome)
	}
	if g.Outcome != nil && g.Outcome.Detail != "-20" {
		t.Errorf("the crime's sanction delta: got %q want -20", g.Outcome.Detail)
	}
	if !hasObservation(events) {
		t.Error("a closed status beat must surface")
	}

	// Idempotent: a second strike does not re-stamp the drive.
	before := tracker.Active(victim.ID).ID
	store.events = append(store.events, damageEvent(victim.ID, actorPtr(offender.ID), "attack", loc, world, now))
	p.grantJusticeDrives(context.Background(), domain.GameTime{Tick: now}, world, byID)
	if tracker.Active(victim.ID).ID != before {
		t.Error("an already-pursued justice drive must not be re-granted")
	}
}

// TestPickLawward: a wronged soul seeking justice heads toward a GUARD (the law) —
// never the attacker, never a non-guard — deterministically (sorted), and nowhere when
// the town has no watch.
func TestPickLawward(t *testing.T) {
	loc := domain.LocationID("ford")
	post := domain.LocationID("guardhouse")

	victim := bodied(loc, 20)
	offender := bodied(loc, 20)
	townsperson := bodied(loc, 20) // not a guard
	guardA := guarding(bodied(post, 20), post)
	guardB := guarding(bodied(post, 20), post)
	byID := map[domain.ActorID]*actor.Actor{
		victim.ID: victim, offender.ID: offender, townsperson.ID: townsperson,
		guardA.ID: guardA, guardB.ID: guardB,
	}

	got := pickLawward(byID, victim.ID, offender.ID)
	if got == nil {
		t.Fatal("with guards present, a victim must have a lawman to seek")
	}
	if *got != guardA.ID && *got != guardB.ID {
		t.Errorf("the lawward must be a GUARD (not victim/offender/townsperson), got %s", *got)
	}
	if again := pickLawward(byID, victim.ID, offender.ID); again == nil || *again != *got {
		t.Error("pickLawward must be deterministic across calls (sorted, not map-order)")
	}

	// No watch: nowhere to report (the goal still grants, but routes nowhere).
	noGuards := map[domain.ActorID]*actor.Actor{victim.ID: victim, offender.ID: offender, townsperson.ID: townsperson}
	if pickLawward(noGuards, victim.ID, offender.ID) != nil {
		t.Error("no guard about → no lawward to seek")
	}

	// The offending guard is excluded — you don't report to your own attacker.
	rogue := guarding(bodied(loc, 20), loc)
	if pickLawward(map[domain.ActorID]*actor.Actor{victim.ID: victim, rogue.ID: rogue}, victim.ID, rogue.ID) != nil {
		t.Error("the offending guard must be excluded — nowhere else to go")
	}
}

// TestProcessJusticeReports: a wronged soul who has REACHED the guard they sought files
// the crime — the law learns of it (the offender goes on the guard's confront-on-sight
// ledger), the seeking ends, and the guard is marked dirty to persist. A victim NOT yet
// co-located with the guard files nothing.
func TestProcessJusticeReports(t *testing.T) {
	const world = domain.WorldID("w")
	post := domain.LocationID("guardhouse")
	now := domain.GameTime{Tick: 60}

	mkSeeker := func(victimLoc domain.LocationID, guardID, offenderID domain.ActorID, tr *appgoal.GoalTracker) *actor.Actor {
		v := bodied(victimLoc, 20)
		v.Type = actor.ActorTypeStoryNPC
		g := goaldom.NewGoal(v.ID, goaldom.GoalTypeSeekJustice, "добиться правосудия", goaldom.PriorityHigh, now)
		off := offenderID
		gd := guardID
		g.Target = goaldom.GoalTarget{ActorID: &gd}
		g.Outcome = &front.Consequence{Type: front.ConsequenceShiftTownDisposition, Target: string(off), Detail: "-20"}
		tr.Add(v.ID, g)
		return v
	}

	offender := bodied(post, 20)

	// Reached the guard: the report lands.
	tr := appgoal.NewGoalTracker()
	guard := guarding(bodied(post, 20), post)
	victim := mkSeeker(post, guard.ID, offender.ID, tr) // same location as the guard
	p := &TickProcessor{goalTracker: tr}
	byID := map[domain.ActorID]*actor.Actor{victim.ID: victim, guard.ID: guard, offender.ID: offender}

	events, dirty := p.processJusticeReports(context.Background(), now, world, byID)
	if !dirty[guard.ID] {
		t.Error("a guard who took a report must be persisted (their ledger changed)")
	}
	if tr.Active(victim.ID) != nil {
		t.Error("the seeking ends once the report is filed")
	}
	if rel := guard.State.Social.GetRelationship(offender.ID); rel == nil || rel.Respect > actor.CrimeWitnessRespect {
		t.Errorf("the law must now hold the offender on its confront-on-sight ledger, got %+v", rel)
	}
	if !hasObservation(events) {
		t.Error("filing a report must surface a beat")
	}
	// Stage 3: the guard who took the report goes AFTER the offender (an apprehend drive).
	if gp := tr.Active(guard.ID); gp == nil || gp.Type != goaldom.GoalTypeApprehend ||
		gp.Target.ActorID == nil || *gp.Target.ActorID != offender.ID {
		t.Errorf("the reporting guard must take up pursuit of the offender, got %v", gp)
	}

	// Not yet reached: no report, the drive persists.
	tr2 := appgoal.NewGoalTracker()
	guard2 := guarding(bodied(post, 20), post)
	seeker2 := mkSeeker(domain.LocationID("ford"), guard2.ID, offender.ID, tr2) // far from the guard
	p2 := &TickProcessor{goalTracker: tr2}
	byID2 := map[domain.ActorID]*actor.Actor{seeker2.ID: seeker2, guard2.ID: guard2, offender.ID: offender}
	_, dirty2 := p2.processJusticeReports(context.Background(), now, world, byID2)
	if dirty2[guard2.ID] || tr2.Active(seeker2.ID) == nil {
		t.Error("a victim who has not reached the guard files nothing — the drive persists")
	}
}

// TestGrantGuardPursuit: a guard set on a known offender takes up an APPREHEND drive
// toward them (routes there via existing goal-movement), granted once — a guard already
// hunting that offender is not re-stamped.
func TestGrantGuardPursuit(t *testing.T) {
	now := domain.GameTime{Tick: 70}
	guard := guarding(bodied(domain.LocationID("post"), 20), domain.LocationID("post"))
	offender := bodied(domain.LocationID("ford"), 20)
	tr := appgoal.NewGoalTracker()

	grantGuardPursuit(tr, guard, offender.ID, offender.State.GetCurrentLocation(), now)
	g := tr.Active(guard.ID)
	if g == nil || g.Type != goaldom.GoalTypeApprehend || g.Target.ActorID == nil || *g.Target.ActorID != offender.ID {
		t.Fatalf("a guard must take up pursuit of the offender, got %v", g)
	}
	if g.Type.IsOngoing() {
		t.Error("apprehend is a bounded milestone, not a standing post — the guard returns to rounds")
	}

	// Idempotent: re-granting the SAME pursuit does not replace the running goal.
	before := g.ID
	grantGuardPursuit(tr, guard, offender.ID, offender.State.GetCurrentLocation(), now)
	if tr.Active(guard.ID).ID != before {
		t.Error("a guard already hunting this offender must not be re-stamped")
	}
}

// TestProcessApprehensions: a pursuing guard who REACHES the offender makes the collar —
// the offender comes to dread the watch, a beat surfaces, and the apprehend drive
// completes. A guard not yet caught up keeps hunting.
func TestProcessApprehensions(t *testing.T) {
	const world = domain.WorldID("w")
	now := domain.GameTime{Tick: 80}
	loc := domain.LocationID("alley")

	mkHunter := func(guardLoc domain.LocationID, offenderID domain.ActorID, tr *appgoal.GoalTracker) *actor.Actor {
		guard := guarding(bodied(guardLoc, 20), domain.LocationID("post"))
		grantGuardPursuit(tr, guard, offenderID, guardLoc, now)
		return guard
	}

	// Caught up: the collar lands.
	offender := bodied(loc, 20)
	offender.Type = actor.ActorTypeStoryNPC
	tr := appgoal.NewGoalTracker()
	guard := mkHunter(loc, offender.ID, tr) // same location as the offender
	p := &TickProcessor{goalTracker: tr}
	byID := map[domain.ActorID]*actor.Actor{guard.ID: guard, offender.ID: offender}

	events, dirty := p.processApprehensions(context.Background(), now, world, byID)
	if !dirty[offender.ID] {
		t.Error("a collared offender's lasting fear must be persisted")
	}
	if rel := offender.State.Social.GetRelationship(guard.ID); rel == nil || rel.Fear < apprehendFear {
		t.Errorf("a caught soul must come to dread the watch, got %+v", rel)
	}
	// Taken into custody: held fast (movement-locked) — actually detained, not just scolded.
	if !offender.State.Physical.Health.HasCondition(actor.ConditionRestrained) {
		t.Error("a collared offender must be taken into custody (restrained)")
	}
	if offender.State.CanMove() {
		t.Error("a detained offender is movement-locked until they wrestle loose")
	}
	if tr.Active(guard.ID) != nil {
		t.Error("the apprehend drive completes on the collar — the guard returns to rounds")
	}
	if !hasObservation(events) {
		t.Error("the collar must surface a beat")
	}

	// Not caught up: the hunt continues.
	offender2 := bodied(loc, 20)
	offender2.Type = actor.ActorTypeStoryNPC
	tr2 := appgoal.NewGoalTracker()
	guard2 := mkHunter(domain.LocationID("far"), offender2.ID, tr2) // elsewhere
	p2 := &TickProcessor{goalTracker: tr2}
	byID2 := map[domain.ActorID]*actor.Actor{guard2.ID: guard2, offender2.ID: offender2}
	_, dirty2 := p2.processApprehensions(context.Background(), now, world, byID2)
	if dirty2[offender2.ID] || tr2.Active(guard2.ID) == nil {
		t.Error("a guard not yet caught up makes no collar — the hunt continues")
	}
}

// TestRefreshPursuitTrail: the watch tracks by SIGHTINGS, not telepathy — an offender seen
// by ANY guard refreshes every hunter's last-known place to that spot; an offender no guard
// can see leaves the trail frozen at the last sighting (the hunter heads to a cold scene).
func TestRefreshPursuitTrail(t *testing.T) {
	now := domain.GameTime{Tick: 90}
	a, b, stale := domain.LocationID("a"), domain.LocationID("b"), domain.LocationID("scene")
	offender := bodied(b, 20) // currently at b

	// A hunter at a, whose trail is stale (last knew the offender at the scene).
	tr := appgoal.NewGoalTracker()
	hunter := guarding(bodied(a, 20), domain.LocationID("post"))
	grantGuardPursuit(tr, hunter, offender.ID, stale, now)
	// A spotter standing WITH the offender at b — the watch has eyes on them.
	spotter := guarding(bodied(b, 20), domain.LocationID("post"))
	grantGuardPursuit(tr, spotter, offender.ID, stale, now)

	p := &TickProcessor{goalTracker: tr}
	byID := map[domain.ActorID]*actor.Actor{hunter.ID: hunter, spotter.ID: spotter, offender.ID: offender}
	p.refreshPursuitTrail(byID, now)

	if loc := tr.Active(hunter.ID).Target.LocationID; loc == nil || *loc != b {
		t.Errorf("a sighting (spotter with the offender at b) must refresh the hunter's trail to b, got %v", loc)
	}

	// No eyes on the offender: the trail freezes at the last sighting (cold scene).
	lone := bodied(b, 20) // the offender, alone, no guard co-located
	tr2 := appgoal.NewGoalTracker()
	hunter2 := guarding(bodied(a, 20), domain.LocationID("post"))
	grantGuardPursuit(tr2, hunter2, lone.ID, stale, now)
	p2 := &TickProcessor{goalTracker: tr2}
	p2.refreshPursuitTrail(map[domain.ActorID]*actor.Actor{hunter2.ID: hunter2, lone.ID: lone}, now)
	if loc := tr2.Active(hunter2.ID).Target.LocationID; loc == nil || *loc != stale {
		t.Errorf("with no guard seeing the offender, the trail stays cold at the last sighting, got %v", loc)
	}
}

// TestPursuitGivesUpWhenTrailColdTooLong: a hunt whose trail stays cold past pursuitPatience is
// ABANDONED — the watch returns to post rather than chase a ghost forever (without this, once
// routine guards joined the hunt the whole watch would desert its posts on any unsolved crime).
func TestPursuitGivesUpWhenTrailColdTooLong(t *testing.T) {
	const world = domain.WorldID("w")
	start := domain.GameTime{Tick: 100}
	scene := domain.LocationID("scene")

	guard := guarding(bodied(scene, 20), domain.LocationID("post"))
	offender := bodied(domain.LocationID("gone"), 20) // slipped away for good — never seen again
	tr := appgoal.NewGoalTracker()
	grantGuardPursuit(tr, guard, offender.ID, scene, start)
	p := &TickProcessor{goalTracker: tr}
	byID := map[domain.ActorID]*actor.Actor{guard.ID: guard}

	deadline := start.Add(pursuitPatience)

	// Still within patience: the hunt holds.
	if evts := p.expireColdPursuits(domain.NewGameTimeAt(deadline.Tick-1), world, byID); len(evts) != 0 {
		t.Fatalf("a trail still within patience must NOT be given up, got %d beats", len(evts))
	}
	if tr.Active(guard.ID) == nil {
		t.Fatalf("the pursuit must still be active within patience")
	}

	// Past patience with no sighting: the hunt is abandoned, with one terse beat.
	evts := p.expireColdPursuits(domain.NewGameTimeAt(deadline.Tick+1), world, byID)
	if len(evts) != 1 || evts[0].Type != event.EventTypeObservation {
		t.Fatalf("a cold trail past patience must be abandoned with one observation beat, got %v", evts)
	}
	if g := tr.Active(guard.ID); g != nil && g.Type == goaldom.GoalTypeApprehend {
		t.Errorf("the abandoned pursuit must be dropped, but it is still active")
	}
}

// TestSightingRenewsPursuitPatience: a fresh sighting pushes the give-up horizon out, so a
// quarry kept in view is chased indefinitely — only the COLD stretch runs out, not the hunt.
func TestSightingRenewsPursuitPatience(t *testing.T) {
	const world = domain.WorldID("w")
	start := domain.GameTime{Tick: 100}
	b := domain.LocationID("b")

	offender := bodied(b, 20)
	guard := guarding(bodied(b, 20), domain.LocationID("post")) // co-located with the offender → a sighting
	tr := appgoal.NewGoalTracker()
	grantGuardPursuit(tr, guard, offender.ID, domain.LocationID("scene"), start)
	p := &TickProcessor{goalTracker: tr}
	byID := map[domain.ActorID]*actor.Actor{guard.ID: guard, offender.ID: offender}

	// A sighting just before the ORIGINAL deadline renews patience from that moment.
	original := start.Add(pursuitPatience)
	p.refreshPursuitTrail(byID, domain.NewGameTimeAt(original.Tick-1))

	// Past the ORIGINAL deadline but within the RENEWED one: the hunt holds, not abandoned.
	if evts := p.expireColdPursuits(domain.NewGameTimeAt(original.Tick+1), world, byID); len(evts) != 0 {
		t.Fatalf("a sighting must renew patience past the original deadline, got %d give-ups", len(evts))
	}
	if tr.Active(guard.ID) == nil {
		t.Errorf("the renewed pursuit must still be active")
	}
}

// TestApprehendColdTrailSearches: a hunter who has reached the last-known place and found
// it COLD (the offender not in sight) does not trudge back to post — it SEARCHES, wandering
// the vicinity toward where people (and clues) are, until a sighting reheats the trail.
func TestApprehendColdTrailSearches(t *testing.T) {
	now := domain.GameTime{Tick: 100}
	scene, post, market := domain.LocationID("scene"), domain.LocationID("post"), domain.LocationID("market")

	guard := guarding(bodied(scene, 20), post) // at the cold last-known scene; home post is elsewhere
	townsfolk := bodied(market, 20)            // company — the one lively spot the search heads for
	offender := bodied(market, 20)             // slipped into the market crowd (unknown to the guard)

	tr := appgoal.NewGoalTracker()
	grantGuardPursuit(tr, guard, offender.ID, scene, now) // last-known == here → trail is cold
	p := &TickProcessor{goalTracker: tr}
	// The market is the SOLE occupied venue away from the cold scene, so the wandering search
	// has one deterministic target — toward company, where clues and the melted-in quarry are.
	byID := map[domain.ActorID]*actor.Actor{guard.ID: guard, offender.ID: offender, townsfolk.ID: townsfolk}

	dest, forced := p.purposefulDestination(guard, now, byID)
	if dest == post || dest == scene || dest.IsZero() {
		t.Errorf("a cold trail must make the guard SEARCH the vicinity, not return to post or stand still, got %q", dest)
	}
	if dest != market {
		t.Errorf("the search heads toward company (where clues and the quarry are), want %q got %q", market, dest)
	}
	if forced {
		t.Errorf("a cold-trail SEARCH is exploratory dwelling, not forced presence — it must respect venue capacity")
	}
}

// The player seeks redress by command, not by an autonomous drive; a non-StoryNPC
// victim gets no justice goal.
func TestGrantJusticeDrives_SkipsNonStoryNPC(t *testing.T) {
	const (
		world = domain.WorldID("w")
		loc   = domain.LocationID("l")
	)
	now := domain.Tick(50)
	player := bodied(loc, 20)
	player.Type = actor.ActorTypePlayer
	offender := bodied(loc, 20)

	store := &fakeEventStore{events: []*event.GameEvent{
		damageEvent(player.ID, actorPtr(offender.ID), "attack", loc, world, now),
	}}
	tracker := appgoal.NewGoalTracker()
	p := &TickProcessor{eventStore: store, goalTracker: tracker}
	byID := map[domain.ActorID]*actor.Actor{player.ID: player, offender.ID: offender}

	p.grantJusticeDrives(context.Background(), domain.GameTime{Tick: now}, world, byID)
	if tracker.Active(player.ID) != nil {
		t.Error("the player carries no autonomous justice drive")
	}
}

package turn

import (
	"context"
	"sort"
	"strconv"

	appgoal "github.com/dnd-llm/dnd-llm/internal/application/goal"
	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/actor"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	"github.com/dnd-llm/dnd-llm/internal/domain/front"
	goaldom "github.com/dnd-llm/dnd-llm/internal/domain/goal"
	"go.uber.org/zap"
)

// Justice — the law's answer to a crime NO guard saw. The witnessed path
// (lawHueAndCry) handles a guard catching a crime in the act; this is the other
// half, the loop the world lacked: a WRONGED soul who carries a drive to see the
// wrongdoer answer for it.
//
// It fits the world's goal model rather than bolting on physical pathing: a goal
// is abstract PROGRESS that, on fulfilment, lands a REAL Outcome through the shared
// doom port (the same way a front's clock fires its doom). So the victim adopts a
// SEEK-JUSTICE drive against the offender; as they pursue it over ticks (the
// existing goal machinery — the decision layer's pursue_goal, advanceGoal,
// fireGoalOutcome), its fulfilment turns the town and watch against the named
// wrongdoer (ShiftTownDisposition). The unseen crime thus still has teeth, and the
// drive connects the autonomous cycle (a goal) to the law (a marked offender). The
// offender may be another NPC or the PLAYER — make enemies of the wronged and the
// town comes to know you for it.

// justiceMarkDelta is how hard a fulfilled justice-drive turns the town against the
// wrongdoer — a crime's sanction, heavier than mere gossip (defame).
const justiceMarkDelta = -20

// processJusticeReports is the report loop's SECOND leg: a wronged soul who has REACHED
// the guard they sought (stage 1 routed them there) files the crime. The law thus learns
// of a crime NO guard saw — the guard takes the offender onto their confront-on-sight
// ledger (MarkCrimeWitnessed, exactly as a witnessed crime does), the goal's authored
// Outcome lands (the town turns against the wrongdoer), and the seeking ends. Co-location
// is read at the tick's start, so an arrival from the prior tick's movement reports now
// (a one-tick lag, not a miss). Deterministic (sorted) for replay. Returns the guards it
// dirtied (their ledger changed) for the caller to persist.
func (p *TickProcessor) processJusticeReports(ctx context.Context, gameTime domain.GameTime, worldID domain.WorldID, byID map[domain.ActorID]*actor.Actor) ([]*event.GameEvent, map[domain.ActorID]bool) {
	if p.goalTracker == nil {
		return nil, nil
	}
	ids := make([]domain.ActorID, 0, len(byID))
	for id := range byID {
		ids = append(ids, id)
	}
	sort.Slice(ids, func(i, j int) bool { return ids[i] < ids[j] })

	var events []*event.GameEvent
	dirty := map[domain.ActorID]bool{}
	for _, victimID := range ids {
		victim := byID[victimID]
		g := p.goalTracker.Active(victimID)
		if victim == nil || victim.IsDead() || g == nil || g.Type != goaldom.GoalTypeSeekJustice || g.Target.ActorID == nil {
			continue
		}
		guard := byID[*g.Target.ActorID]
		if guard == nil || guard.IsDead() || guard.State.GetCurrentLocation() != victim.State.GetCurrentLocation() {
			continue // not yet reached the law
		}
		if g.Outcome == nil || g.Outcome.Target == "" {
			continue // nothing to report (no offender named) — defensive
		}
		offender := domain.ActorID(g.Outcome.Target)
		// The law learns of the unseen crime: the guard now confronts the offender on sight,
		// just as if they had witnessed it. Marks the guard dirty for the caller to persist.
		actor.MarkCrimeWitnessed(guard, offender)
		dirty[guard.ID] = true
		// And the law ACTS on it: the guard who took the report leaves the post to PURSUE the
		// reported offender (an apprehend drive — the proactive twin of the victim's seek-
		// justice, the loop's third leg). It heads to the offender's LAST-KNOWN place (where
		// they are as the report lands — the freshest the watch has), not their live spot;
		// from there the trail moves only by sighting (refreshPursuitTrail).
		lastKnown := domain.LocationID("")
		if off := byID[offender]; off != nil && off.State != nil {
			lastKnown = off.State.GetCurrentLocation()
		}
		grantGuardPursuit(p.goalTracker, guard, offender, lastKnown, gameTime)

		loc := victim.State.GetCurrentLocation()
		events = append(events, event.NewGameEvent(event.EventTypeObservation, victim.ID, loc, worldID, gameTime.Tick,
			event.ObservationEventData{ActorID: victim.ID, LocationID: loc, Description: "приносит страже жалобу на обидчика"}))
		// The seeking is fulfilled: its authored Outcome lands (the town turns on the
		// wrongdoer), and the drive retires so it neither re-reports nor double-marks.
		events = append(events, p.fireGoalOutcome(ctx, g, loc, worldID, gameTime.Tick)...)
		p.goalTracker.Remove(victimID, g.ID)
		if p.logger != nil {
			p.logger.Debug("justice reported", zap.String("victim", victimID.String()),
				zap.String("guard", guard.ID.String()), zap.String("offender", offender.String()))
		}
	}
	return events, dirty
}

// apprehendFear is how hard being CAUGHT by the law marks an offender — a fear of the
// watch strong enough to make them shun guards afterward (past the avoidance spawn mark).
const apprehendFear = 50

// pursuitPatience is how long the watch hunts a COLD trail before giving up: the span,
// measured from the last actual sighting, after which an unseen offender is presumed slipped
// away and the hunters return to their posts. Every fresh sighting pushes this horizon out
// (refreshPursuitTrail), so a quarry kept in view is chased indefinitely — it is the COLD
// stretch that runs out, not the pursuit itself. Without it the whole watch, once roused,
// would abandon its posts forever chasing a ghost (felt only once routine guards joined the
// hunt — a lone StoryNPC captain hid the cost). A duty, not a tally: a deliberate window.
const pursuitPatience = domain.Duration(30 * domain.TicksPerMinute)

// processApprehensions is the report loop's FINAL leg: a pursuing guard who has REACHED
// the offender (stage 3 routed them there) makes the collar. The confrontation lands — a
// beat surfaces, the offender feels the law's grip (a lasting fear of the watch, so a
// caught NPC comes to shun guards), and the apprehend drive completes (the catch IS its
// fulfilment, not a progress timeout), returning the guard to their rounds. The mirror of
// processJusticeReports, from the law's side reaching the wrongdoer. Deterministic (sorted).
func (p *TickProcessor) processApprehensions(ctx context.Context, gameTime domain.GameTime, worldID domain.WorldID, byID map[domain.ActorID]*actor.Actor) ([]*event.GameEvent, map[domain.ActorID]bool) {
	if p.goalTracker == nil {
		return nil, nil
	}
	ids := make([]domain.ActorID, 0, len(byID))
	for id := range byID {
		ids = append(ids, id)
	}
	sort.Slice(ids, func(i, j int) bool { return ids[i] < ids[j] })

	var events []*event.GameEvent
	dirty := map[domain.ActorID]bool{}
	for _, guardID := range ids {
		guard := byID[guardID]
		g := p.goalTracker.Active(guardID)
		if guard == nil || guard.IsDead() || g == nil || g.Type != goaldom.GoalTypeApprehend || g.Target.ActorID == nil {
			continue
		}
		offender := byID[*g.Target.ActorID]
		if offender == nil || offender.IsDead() || offender.State.GetCurrentLocation() != guard.State.GetCurrentLocation() {
			continue // not yet caught up to the offender
		}
		// The collar: the offender is TAKEN INTO CUSTODY — held fast (the restraint condition
		// that movement-locks them), so a caught soul is actually detained, not merely scolded.
		// They wrestle loose over ticks the same way any pinned soul does (the existing escape
		// reflex), so detention is bounded, not a frozen state. They also learn to dread the
		// watch; a beat surfaces; the drive completes and the guard returns to their post.
		if offender.State != nil && offender.State.Physical != nil &&
			!offender.State.Physical.Health.HasCondition(actor.ConditionRestrained) {
			offender.State.Physical.ApplyCondition(actor.ConditionRestrained,
				actor.EffectSource{Type: actor.EffectSourceActor, ActorID: &guard.ID}, gameTime)
			dirty[offender.ID] = true
		}
		if instillLawfulFear(offender, guard.ID, apprehendFear) {
			dirty[offender.ID] = true
		}
		loc := guard.State.GetCurrentLocation()
		events = append(events, event.NewGameEvent(event.EventTypeObservation, guard.ID, loc, worldID, gameTime.Tick,
			event.ObservationEventData{ActorID: guard.ID, LocationID: loc, Description: "настигает обидчика и берёт его под стражу"}))
		p.goalTracker.Remove(guardID, g.ID)
		if p.logger != nil {
			p.logger.Debug("offender apprehended", zap.String("guard", guardID.String()), zap.String("offender", offender.ID.String()))
		}
	}
	return events, dirty
}

// instillLawfulFear raises an offender's lasting fear of the guard who collared them — a
// caught soul comes to shun the watch. Set-to-floor (never lowers an already-deeper dread),
// so a repeat collar keeps it pinned. Reports whether it changed anything. The player is
// not driven by fear-AI, so only an NPC offender is marked.
func instillLawfulFear(offender *actor.Actor, guardID domain.ActorID, amount int) bool {
	if offender.Type == actor.ActorTypePlayer || offender.State == nil || offender.State.Social == nil {
		return false
	}
	rel := offender.State.Social.GetRelationship(guardID)
	if rel == nil {
		rel = actor.NewActorRelationship(guardID)
		offender.State.Social.SetRelationship(guardID, rel)
	}
	if rel.Fear >= amount {
		return false
	}
	rel.Fear = amount
	return true
}

// grantGuardPursuit sets a guard onto the trail of a known offender: an APPREHEND drive
// that routes them toward the LAST-KNOWN place the offender was (a crime scene, a sighting)
// — NOT the offender's live position (the law has no telepathy; the trail only moves when a
// sighting refreshes it). The Target carries BOTH: LocationID is where to head, ActorID the
// offender's identity (for the collar and trail-matching). Bounded milestone, so the guard
// returns to rounds once it completes. Granted ONCE per offender — not re-stamped.
func grantGuardPursuit(tracker *appgoal.GoalTracker, guard *actor.Actor, offenderID domain.ActorID, lastKnown domain.LocationID, gameTime domain.GameTime) {
	if tracker == nil || guard == nil {
		return
	}
	if g := tracker.Active(guard.ID); g != nil && g.Type == goaldom.GoalTypeApprehend &&
		g.Target.ActorID != nil && *g.Target.ActorID == offenderID {
		return // already hunting this offender
	}
	off, loc := offenderID, lastKnown
	g := goaldom.NewGoal(guard.ID, goaldom.GoalTypeApprehend,
		aimPhraseForType(goaldom.GoalTypeApprehend), goaldom.PriorityHigh, gameTime)
	g.Target = goaldom.GoalTarget{ActorID: &off}
	if !loc.IsZero() {
		g.Target.LocationID = &loc
	}
	deadline := gameTime.Add(pursuitPatience) // the hunt runs until the trail is cold this long
	g.Deadline = &deadline
	tracker.Add(guard.ID, g)
}

// refreshPursuitTrail is the law's eyes: a pursued offender SEEN by any guard (co-located
// with one) becomes a fresh sighting — every guard hunting them updates their last-known
// place to it. So the watch tracks by what it actually SEES (shared intel), not omniscience:
// while the offender stays in sight the trail stays hot; the moment they slip every guard's
// gaze, the trail freezes at the last sighting and the hunters head there (finding it cold —
// the search that follows is theirs to wander). Deterministic; returns no events, mutates the
// live goals (the tracker holds them by pointer).
func (p *TickProcessor) refreshPursuitTrail(byID map[domain.ActorID]*actor.Actor, gameTime domain.GameTime) {
	if p.goalTracker == nil {
		return
	}
	// Where is each PURSUED offender seen right now? (Co-located with a guard = in the
	// watch's sight.) Built once, then fanned out to every hunter of that offender.
	seenAt := map[domain.ActorID]domain.LocationID{}
	for _, a := range byID {
		g := p.goalTracker.Active(a.ID)
		if a == nil || !isGuardActor(a) || a.IsDead() || g == nil || g.Type != goaldom.GoalTypeApprehend || g.Target.ActorID == nil {
			continue
		}
		offenderID := *g.Target.ActorID
		if _, done := seenAt[offenderID]; done {
			continue
		}
		if off := byID[offenderID]; off != nil && !off.IsDead() && off.State.GetCurrentLocation() == a.State.GetCurrentLocation() {
			seenAt[offenderID] = a.State.GetCurrentLocation() // a guard has eyes on them here
		}
	}
	if len(seenAt) == 0 {
		return
	}
	deadline := gameTime.Add(pursuitPatience) // the sighting reheats the trail: patience renewed
	for _, a := range byID {
		g := p.goalTracker.Active(a.ID)
		if g == nil || g.Type != goaldom.GoalTypeApprehend || g.Target.ActorID == nil {
			continue
		}
		if loc, seen := seenAt[*g.Target.ActorID]; seen {
			// The trail is hot: head to the fresh sighting AND push the give-up horizon out.
			p.goalTracker.RefreshActivePursuit(a.ID, loc, deadline)
		}
	}
}

// expireColdPursuits gives the watch its OUT: a pursuit whose trail has been cold past
// pursuitPatience (no sighting renewed its deadline) is abandoned — the offender is presumed
// slipped away, the hunter drops the chase and returns to their post. Without this an
// unwinnable hunt would hold the whole watch off-post forever. Mirrors processApprehensions
// (the OTHER way a pursuit ends), but on the law's defeat rather than its catch: it drops the
// drive and surfaces a terse beat, no fear instilled (no one was caught).
func (p *TickProcessor) expireColdPursuits(gameTime domain.GameTime, worldID domain.WorldID, byID map[domain.ActorID]*actor.Actor) []*event.GameEvent {
	if p.goalTracker == nil {
		return nil
	}
	ids := make([]domain.ActorID, 0, len(byID))
	for id := range byID {
		ids = append(ids, id)
	}
	sort.Slice(ids, func(i, j int) bool { return ids[i] < ids[j] })

	var events []*event.GameEvent
	for _, guardID := range ids {
		guard := byID[guardID]
		g := p.goalTracker.Active(guardID)
		if guard == nil || guard.IsDead() || g == nil || g.Type != goaldom.GoalTypeApprehend || !g.IsExpired(gameTime) {
			continue
		}
		p.goalTracker.Remove(guardID, g.ID)
		loc := guard.State.GetCurrentLocation()
		events = append(events, event.NewGameEvent(event.EventTypeObservation, guard.ID, loc, worldID, gameTime.Tick,
			event.ObservationEventData{ActorID: guard.ID, LocationID: loc, Description: "теряет след и возвращается к своим обязанностям"}))
		if p.logger != nil {
			p.logger.Debug("pursuit abandoned (cold trail)", zap.String("guard", guardID.String()))
		}
	}
	return events
}

// pickLawward chooses the GUARD a wronged soul heads toward to report a crime — the law
// embodied. It is the seat of justice the victim seeks (the goal routes toward this
// actor's live location). Deterministic (sorted by id) so a replay picks the same lawman;
// excludes the victim and the offender (you do not report to your own attacker, and a
// guard-victim is filtered upstream). nil when the town has no guard to reach.
func pickLawward(byID map[domain.ActorID]*actor.Actor, victimID, offenderID domain.ActorID) *domain.ActorID {
	var guards []domain.ActorID
	for id, a := range byID {
		if id == victimID || id == offenderID {
			continue
		}
		if a == nil || a.IsDead() || !isGuardActor(a) {
			continue
		}
		guards = append(guards, id)
	}
	if len(guards) == 0 {
		return nil
	}
	sort.Slice(guards, func(i, j int) bool { return guards[i] < guards[j] })
	return &guards[0]
}

// hasJusticeDrive reports whether the soul is already pursuing redress, so the
// drive is granted ONCE, not re-stamped every tick the wound stays fresh.
func hasJusticeDrive(tracker *appgoal.GoalTracker, id domain.ActorID) bool {
	if tracker == nil {
		return false
	}
	g := tracker.Active(id)
	return g != nil && g.Type == goaldom.GoalTypeSeekJustice
}

// grantJusticeDrives gives each soul WRONGED this tick — a StoryNPC, not the watch
// itself, still standing — a lasting drive to see the offender answer, whose
// fulfilment marks the wrongdoer to the town. The immediate reflex (flee or strike
// back) handled the moment; this is the pursuit it leaves behind. The goal's Outcome
// carries the real world change (landed later, on fulfilment, by fireGoalOutcome);
// here a closed status beat names the resolve taken.
func (p *TickProcessor) grantJusticeDrives(ctx context.Context, gameTime domain.GameTime, worldID domain.WorldID, byID map[domain.ActorID]*actor.Actor) []*event.GameEvent {
	if p.goalTracker == nil {
		return nil
	}
	victims := freshStrikeVictims(ctx, p.eventStore, worldID, gameTime.Tick)
	var events []*event.GameEvent
	for victimID, offenderID := range victims {
		victim := byID[victimID]
		if victim == nil || victim.Type != actor.ActorTypeStoryNPC || victim.IsDead() || isGuardActor(victim) {
			continue // the player seeks redress by command; the watch already wields the law; the dead seek nothing
		}
		if hasJusticeDrive(p.goalTracker, victimID) {
			continue
		}
		off := offenderID
		g := goaldom.NewGoal(victimID, goaldom.GoalTypeSeekJustice,
			aimPhraseForType(goaldom.GoalTypeSeekJustice), goaldom.PriorityHigh, gameTime)
		// Seek justice = go to the LAW. The goal's pursuit-target is a GUARD (the law
		// embodied), so the existing goal-movement (purposefulDestination) carries the
		// victim toward them over ticks — the report loop's first leg. WHO answers (the
		// offender) lives in the Outcome below, not the target: two roles, two fields, so
		// the victim heads to the guard, never toward the one they accuse. No guard about
		// → no destination (the goal still grants and accrues; the town has no law to reach).
		if lawward := pickLawward(byID, victimID, off); lawward != nil {
			g.Target = goaldom.GoalTarget{ActorID: lawward}
		}
		g.Outcome = &front.Consequence{
			Type:   front.ConsequenceShiftTownDisposition,
			Target: string(off),
			Detail: strconv.Itoa(justiceMarkDelta),
		}
		p.goalTracker.Add(victimID, g)

		loc := victim.State.GetCurrentLocation()
		events = append(events, event.NewGameEvent(event.EventTypeObservation, victim.ID, loc, worldID, gameTime.Tick,
			event.ObservationEventData{ActorID: victim.ID, LocationID: loc, Description: "затаивает решимость добиться правосудия"}))
		if p.logger != nil {
			p.logger.Debug("justice drive granted", zap.String("victim", victimID.String()), zap.String("offender", off.String()))
		}
	}
	return events
