)

// vowProgressLog builds a fake store whose log anchors genesis at tick 1 and records the player's
// vow at `progress` (the fold reads it back). Mirrors production: a GoalProgressed per pursuit.
func vowProgressLog(world domain.WorldID, player domain.ActorID, vowID goaldom.GoalID, progress float64) *frontFakeStore {
	return &frontFakeStore{events: []*event.GameEvent{
		event.NewGameEvent(event.EventTypeFrontStarted, domain.ActorID(world), "", world, 1,
			event.FrontStartedEventData{FrontKey: "anchor"}), // earliest event → genesis anchor
		event.NewGameEvent(event.EventTypeGoalProgressed, player, "", world, 5,
			event.GoalProgressEventData{ActorID: player, GoalID: string(vowID), GoalType: string(goaldom.GoalTypeVow), Progress: progress}),
	}}
}

// TestDefuseVowRelatedFronts: fulfilling a vow ENDS the live fronts the director aimed at its
// subject (so the world stops surfacing portents of the problem the player just fixed), and leaves
// unrelated fronts alone. Scoped by vowRelevance (lead at the vow's place), symmetric with aiming.
func TestDefuseVowRelatedFronts(t *testing.T) {
	const world = domain.WorldID("w")
	docks := domain.NewLocationID()
	elsewhere := domain.NewLocationID()
	vow := locVow(docks)

	related := &front.Def{Key: "river", Leads: []front.Lead{{Location: docks}}, Doom: front.Consequence{Type: front.ConsequenceRuinLocation}}
	unrelated := &front.Def{Key: "market", Leads: []front.Lead{{Location: elsewhere}}, Doom: front.Consequence{Type: front.ConsequenceRuinLocation}}

	store := &frontFakeStore{events: []*event.GameEvent{
		event.NewGameEvent(event.EventTypeFrontStarted, domain.ActorID(world), "", world, 1, event.FrontStartedEventData{FrontKey: "river"}),  // earliest → genesis anchor
		event.NewGameEvent(event.EventTypeFrontStarted, domain.ActorID(world), "", world, 2, event.FrontStartedEventData{FrontKey: "market"}),
	}}
	svc := &Service{events: store, frontDefs: map[string]*front.Def{"river": related, "market": unrelated}, logger: zap.NewNop()}
	svc.defuseVowRelatedFronts(context.Background(), Scene{WorldID: world, Tick: 10}, vow)

	resolved := map[string]bool{}
	for _, e := range store.events {
		if d, ok := e.Data.(event.FrontResolvedEventData); ok {
			resolved[d.FrontKey] = true
		}
	}
	if !resolved["river"] {
		t.Error("a live front about the vow's subject (a lead at the docks) must defuse when the vow is fulfilled")
	}
	if resolved["market"] {
		t.Error("a front unrelated to the vow must NOT be defused")
	}
}

// TestEnsurePlayerVow_CompletedDoesNotRegrant guards against re-finishing a done quest: once the
// vow reached full progress THIS incarnation, ensurePlayerVow must NOT re-grant it — a re-granted
// full vow re-fulfils on the next engagement, re-applying its boon and re-surfacing the climax
// («Причалы оживают» twice, the live bug). A partly-pursued vow, by contrast, resumes.
func TestEnsurePlayerVow_CompletedDoesNotRegrant(t *testing.T) {
	const world = domain.WorldID("w")
	player := domain.NewActorID()
	vow := goaldom.NewGoal("", goaldom.GoalTypeVow, "вернуть пристани жизнь", goaldom.PriorityHigh, domain.NewGameTime())

	done := &Service{goals: appgoal.NewGoalTracker(), events: vowProgressLog(world, player, vow.ID, 1.0),
		vowTemplates: []*goaldom.Goal{vow}, doom: &recordingDoom{}, logger: zap.NewNop()}
	done.ensurePlayerVow(context.Background(), Scene{PlayerID: player, WorldID: world, Tick: 6})
	if g := done.goals.Active(player); g != nil {
		t.Errorf("a vow already fulfilled this incarnation must NOT be re-granted, got %q", g.Description)
	}

	// Control: a vow only PARTLY pursued resumes at its folded progress (the legitimate re-grant path).
	partly := &Service{goals: appgoal.NewGoalTracker(), events: vowProgressLog(world, player, vow.ID, 0.6),
		vowTemplates: []*goaldom.Goal{vow}, doom: &recordingDoom{}, logger: zap.NewNop()}
	partly.ensurePlayerVow(context.Background(), Scene{PlayerID: player, WorldID: world, Tick: 6})
	if g := partly.goals.Active(player); g == nil || g.Progress != 0.6 {
		t.Errorf("a partly-pursued vow must resume at its folded progress (0.6), got %v", g)
	}
}

// TestAdvancePlayerVow_FulfilledSurfacesBoon guards the quest CLIMAX: a fulfilled vow must
// RETURN its authored boon narration (so Commit weaves it into the player's feed), not only
// apply the boon mechanically. The live bug this guards: the river quest completed (docks
// restored) but the «Причалы оживают» payoff was invisible because advancePlayerVow was void.
func TestAdvancePlayerVow_FulfilledSurfacesBoon(t *testing.T) {
	player := domain.NewActorID()
	loc := domain.NewLocationID()

	goals := appgoal.NewGoalTracker()
	vow := goaldom.NewGoal(player, goaldom.GoalTypeVow, "вернуть пристани жизнь", goaldom.PriorityHigh, domain.NewGameTime())
	vow.Target = goaldom.GoalTarget{LocationID: &loc}
	vow.Outcome = &front.Consequence{Type: front.ConsequenceRestoreLocation, Target: string(loc), Narration: "Причалы оживают."}
	goals.Add(player, vow)

	// No frontDefs → vowPursued falls to structural engagement; the scene stands AT the vow's
	// place, so every turn engages it. Five 0.2 steps fill the vow; the fifth fulfils.
	svc := &Service{goals: goals, doom: &recordingDoom{}, logger: zap.NewNop()}
	scene := Scene{PlayerID: player, Location: loc, WorldID: domain.WorldID("w"), Tick: 5}

	var boon string
	for i := 0; i < 5; i++ {
		boon = svc.advancePlayerVow(context.Background(), scene)
	}
	if boon != "Причалы оживают." {
		t.Errorf("a fulfilled vow must return its authored boon narration for the feed, got %q", boon)
	}
}

// TestVowPursued_ImpotentDeedMakesNoProgress guards the deed-impotent disconnect: a turn that
// engaged the vow's subject but was ruled an honest MATERIAL FAILURE (no means) must NOT advance
// the vow — otherwise the quest crept up invisibly while the player read «нет средства». The same
// engagement WITHOUT the failure still advances (investigation and accomplished remedies pass).
func TestVowPursued_ImpotentDeedMakesNoProgress(t *testing.T) {
	loc := domain.NewLocationID()
	vow := locVow(loc)
	svc := &Service{logger: zap.NewNop()} // no frontDefs, no cues → structural engagement at the place

	at := Scene{Location: loc, WorldID: domain.WorldID("w"), Tick: 5}
	if !svc.vowPursued(context.Background(), vow, at) {
		t.Fatal("a turn engaging the vow's subject should advance it")
	}

	failed := at
	failed.DeedImpotent = true
	if svc.vowPursued(context.Background(), vow, failed) {
		t.Error("an impotent deed (honest material failure) must make no vow progress")
	}
}

func locVow(loc domain.LocationID) *goaldom.Goal {
	g := goaldom.NewGoal("", goaldom.GoalTypeVow, "save the place", goaldom.PriorityHigh, domain.NewGameTime())
	g.Target = goaldom.GoalTarget{LocationID: &loc}
	return g
}

func actorVow(id domain.ActorID) *goaldom.Goal {
	g := goaldom.NewGoal("", goaldom.GoalTypeVow, "stand by them", goaldom.PriorityHigh, domain.NewGameTime())
	g.Target = goaldom.GoalTarget{ActorID: &id}
	return g
}

// A front about the vow's subject scores higher — the director aims escalation at the player's drive.
func TestVowRelevance(t *testing.T) {
	here := domain.NewLocationID()
	driver := domain.NewActorID()
	atVowPlace := &front.Def{Leads: []front.Lead{{Location: here}}}
	drivenByVowActor := &front.Def{Driver: driver}
	unrelated := &front.Def{Leads: []front.Lead{{Location: domain.NewLocationID()}}}

	if vowRelevance(atVowPlace, nil) != 0 {
		t.Error("no vow → no bonus")
	}
	if vowRelevance(atVowPlace, locVow(here)) <= 0 {
		t.Error("a lead at the vow's place should earn a bonus")
	}
	if vowRelevance(drivenByVowActor, actorVow(driver)) <= 0 {
		t.Error("a front driven by the vow's person should earn a bonus")
	}
	if vowRelevance(unrelated, locVow(here)) != 0 {
		t.Error("a front unrelated to the vow earns nothing")
	}
}

// The vow advances when the player engages its subject: with the person, at the place, or naming it.
func TestVowSubjectEngaged(t *testing.T) {
	npc := domain.NewActorID()
	place := domain.NewLocationID()
	elsewhere := domain.NewLocationID()

	av := actorVow(npc)
	if !vowSubjectEngaged(av, Scene{CoLocated: []*actor.Actor{{ID: npc}}}) {
		t.Error("an NPC vow engages when the NPC is co-located")
	}
	if !vowSubjectEngaged(av, Scene{Mentions: []string{string(npc)}}) {
		t.Error("an NPC vow engages when the NPC is named")
	}
	if vowSubjectEngaged(av, Scene{Location: elsewhere}) {
		t.Error("an NPC vow does not engage on an unrelated scene")
	}

	lv := locVow(place)
	if !vowSubjectEngaged(lv, Scene{Location: place}) {
		t.Error("a place vow engages when the player is there")
	}
	if !vowSubjectEngaged(lv, Scene{Mentions: []string{string(place)}}) {
		t.Error("a place vow engages when the place is named")
	}
	if vowSubjectEngaged(lv, Scene{Location: elsewhere}) {
		t.Error("a place vow does not engage elsewhere")
	}
}

// vowPursuitCues gathers the concrete lead/remedy cues of fronts bearing on the vow's
// subject (and nothing from unrelated fronts) — the threads by which the vow actually
// advances, so progress is achievement, not presence.
func TestVowPursuitCues(t *testing.T) {
	here := domain.NewLocationID()
	s := &Service{}
	s.SetFronts([]*front.Def{
		{
			Key:    "river",
			Leads:  []front.Lead{{Location: here, Cue: "осмотреть воду у причалов"}},
			Remedy: front.Remedy{Cue: "убрать груз с русла"},
		},
		{
			Key:   "elsewhere",
			Leads: []front.Lead{{Location: domain.NewLocationID(), Cue: "расспросить на рынке"}},
		},
	})

	cues := s.vowPursuitCues(locVow(here))
	has := func(c string) bool {
		for _, x := range cues {
			if x == c {
				return true
			}
		}
		return false
	}
	if !has("осмотреть воду у причалов") {
		t.Error("the lead cue of a front at the vow's place should be a pursuit cue")
	}
	if !has("убрать груз с русла") {
		t.Error("the remedy cue of a relevant front should be a pursuit cue")
	}
	if has("расспросить на рынке") {
		t.Error("an unrelated front's cue must not be a pursuit cue")
	}
	if len(cues) != 2 {
		t.Errorf("expected exactly the two relevant cues, got %v", cues)
	}

	// A vow whose subject no front bears on yields no cues — vowPursued then falls back
	// to structural engagement rather than stranding it.
	if cues := s.vowPursuitCues(locVow(domain.NewLocationID())); len(cues) != 0 {
		t.Errorf("a vow with no related front has no pursuit cues, got %v", cues)
	}
}

// TestRaiseEngagedFronts: ANY dormant authored front whose thread the player takes this turn is
// WOKEN (FrontStarted), so its resolution runs the same turn regardless of the director's pacing —
// the quest-resolution-gated-by-pacing fix, for EVERY quest (not only the player's vow). A front
// whose on-place lead the player did not engage, and an already-started one, are left dormant.
func TestRaiseEngagedFronts(t *testing.T) {
	const world = domain.WorldID("w")
	docks := domain.NewLocationID()

	// river: engaged this turn (its lead subject grounded at the player's place) → must raise.
	river := &front.Def{Key: "river", Leads: []front.Lead{{Location: docks, Subject: "river_tihvod"}}}
	// bell: a DIFFERENT quest, not the player's vow, ALSO engaged this turn (its subject grounded) →
	// must raise too (the fix is universal across quests, not vow-special-cased).
	bell := &front.Def{Key: "bell", Leads: []front.Lead{{Location: docks, Subject: "old_bell"}}}
	// crossing: its on-place lead was NOT engaged (subject not grounded) → stays dormant.
	crossing := &front.Def{Key: "crossing", Leads: []front.Lead{{Location: docks, Subject: "brod"}}}
	// market: lead elsewhere → not engaged here → stays dormant.
	market := &front.Def{Key: "market", Leads: []front.Lead{{Location: domain.NewLocationID(), Subject: "stall"}}}

	store := &frontFakeStore{events: []*event.GameEvent{
		event.NewGameEvent(event.EventTypeFrontStarted, domain.ActorID(world), "", world, 1, event.FrontStartedEventData{FrontKey: "anchor"}),
	}}
	svc := &Service{
		events:    store,
		frontDefs: map[string]*front.Def{"river": river, "bell": bell, "crossing": crossing, "market": market},
		logger:    zap.NewNop(),
		// cues nil: engaged leads match by deterministic membership before any classifier call.
	}
	// The player grounded BOTH the river and the bell this turn (a deed naming both).
	scene := Scene{Location: docks, Mentions: []string{"river_tihvod", "old_bell"}, WorldID: world, Tick: 5}

	svc.raiseEngagedFronts(context.Background(), scene)

	raised := map[string]bool{}
	for _, e := range store.events {
		if d, ok := e.Data.(event.FrontStartedEventData); ok {
			raised[d.FrontKey] = true
		}
	}
	if !raised["river"] {
		t.Error("an engaged dormant front must be raised by the player's engagement")
	}
	if !raised["bell"] {
		t.Error("a NON-vow quest the player engages must ALSO be raised — the fix is universal")
	}
	if raised["crossing"] {
		t.Error("a front whose on-place lead was not engaged must stay dormant")
	}
	if raised["market"] {
		t.Error("a front engaged nowhere here must stay dormant")
	}

	// Idempotent: a second pass does not re-raise an already-started front.
	before := len(store.events)
	svc.raiseEngagedFronts(context.Background(), scene)
	if len(store.events) != before {
		t.Error("an already-raised front must not be raised again")
	}
}

// TestFulfillVowFromRemedy: remedying the front the player's vow bears on COMPLETES the vow — the
// real fix is the milestone. The authored Outcome lands (boon prose returned for the feed) and the
// goal finishes. A front the vow does not bear on fulfils nothing.
func TestFulfillVowFromRemedy(t *testing.T) {
	const world = domain.WorldID("w")
	player := domain.NewActorID()
	docks := domain.NewLocationID()

	vow := locVow(docks)
	vow.ActorID = player
	vow.Outcome = &front.Consequence{Type: front.ConsequenceRestoreLocation, Target: string(docks), Narration: "Причалы оживают."}
	goals := appgoal.NewGoalTracker()
	goals.Add(player, vow)

	store := &frontFakeStore{events: []*event.GameEvent{
		event.NewGameEvent(event.EventTypeFrontStarted, domain.ActorID(world), "", world, 1, event.FrontStartedEventData{FrontKey: "anchor"}),
	}}
	doom := &recordingDoom{}
	svc := &Service{goals: goals, events: store, doom: doom, frontDefs: map[string]*front.Def{}, logger: zap.NewNop()}
	scene := Scene{PlayerID: player, Location: docks, WorldID: world, Tick: 9}

	// An irrelevant front fulfils nothing.
	irrelevant := &front.Front{Def: &front.Def{Key: "market", Leads: []front.Lead{{Location: domain.NewLocationID()}}}}
	if got := svc.fulfillVowFromRemedy(context.Background(), scene, irrelevant); got != "" {
		t.Errorf("remedying an unrelated front must not fulfil the vow, got %q", got)
	}
	if g := goals.Active(player); g == nil || g.Progress >= 1.0 {
		t.Fatal("the vow must still be active after an unrelated remedy")
	}

	// The vow's own front: remedying it completes the vow and returns the payoff prose.
	river := &front.Front{Def: &front.Def{Key: "river", Leads: []front.Lead{{Location: docks}}}}
	got := svc.fulfillVowFromRemedy(context.Background(), scene, river)
	if got != "Причалы оживают." {
		t.Errorf("remedying the vow's front must return its payoff prose, got %q", got)
	}
	if g := goals.Active(player); g != nil {
		t.Errorf("the vow must be fulfilled (no longer active), got %q", g.Description)
	}
	landed := false
	for _, c := range doom.applied {
		if c.Type == front.ConsequenceRestoreLocation && c.Target == string(docks) {
			landed = true
		}
	}
	if !landed {
		t.Error("the vow's authored Outcome (restore the docks) must land as a real world change")
	}
}

// TestAdvancePlayerVow_RemedyGatedDoesNotFulfilOnSoftEngagement: a vow whose quest carries a remedy
// must NOT complete on soft references alone — investigation creeps progress toward a CEILING but
// never to the finish (the fix completes it). Guards the «обет фулфилится мягким engagement» seam.
func TestAdvancePlayerVow_RemedyGatedDoesNotFulfilOnSoftEngagement(t *testing.T) {
	const world = domain.WorldID("w")
	player := domain.NewActorID()
	docks := domain.NewLocationID()

	vow := locVow(docks)
	vow.ActorID = player
	vow.Outcome = &front.Consequence{Type: front.ConsequenceRestoreLocation, Target: string(docks), Narration: "Причалы оживают."}
	goals := appgoal.NewGoalTracker()
	goals.Add(player, vow)

	// A relevant front WITH a remedy → the vow is remedy-gated.
	river := &front.Def{
		Key:    "river",
		Leads:  []front.Lead{{Location: docks, Subject: "river_tihvod"}},
		Remedy: front.Remedy{Cue: "расчистить русло", Narration: "heal"},
	}
	store := &frontFakeStore{events: []*event.GameEvent{
		event.NewGameEvent(event.EventTypeFrontStarted, domain.ActorID(world), "", world, 1, event.FrontStartedEventData{FrontKey: "anchor"}),
	}}
	doom := &recordingDoom{}
	svc := &Service{goals: goals, events: store, doom: doom, frontDefs: map[string]*front.Def{"river": river}, logger: zap.NewNop()}
	// Investigation grounds the river's lead subject every turn (vowPursued by membership, no cues).
	scene := Scene{PlayerID: player, Location: docks, Mentions: []string{"river_tihvod"}, WorldID: world, Tick: 5}

	for i := 0; i < 12; i++ {
		if boon := svc.advancePlayerVow(context.Background(), scene); boon != "" {
			t.Fatalf("soft investigation must never surface a fulfilment boon, got %q at step %d", boon, i)
		}
	}
	g := goals.Active(player)
	if g == nil {
		t.Fatal("a remedy-gated vow must stay active under pure investigation (never auto-fulfils)")
	}
	if g.Progress >= 1.0 {
		t.Errorf("investigation must cap progress short of completion, got %v", g.Progress)
	}
	if g.Progress != vowHeadwayCeil {
		t.Errorf("investigation should creep to the headway ceiling %v, got %v", vowHeadwayCeil, g.Progress)
	}
	for _, c := range doom.applied {
		if c.Type == front.ConsequenceRestoreLocation {
			t.Error("the vow's Outcome must NOT land on soft engagement — only the remedy completes it")
		}
	}
}

package db

import (
	"context"
	"database/sql"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	_ "modernc.org/sqlite"
)

// Open opens the embedded SQLite database at path and returns a ready *sql.DB,
// configured for durable single-process use. Every pooled connection is set up via
// DSN pragmas (modernc applies each `_pragma` on connect — no per-connection hook needed):
//   - busy_timeout: wait, don't fail, on a momentarily-locked write.
//   - foreign_keys ON: the schema leans on ON DELETE CASCADE (reseed wipes, world teardown);
//     SQLite resets this per connection, so it must be in the DSN, not set once.
//   - journal_mode WAL: concurrent reads alongside the single writer; survives a clean crash.
//   - synchronous FULL: fsync the WAL on every commit, so an unclean kill cannot tear it.
//     The cost (a flush per commit) is irrelevant for a local single-player game whose every
//     turn already blocks seconds on the LLM.
//
// Engine: modernc.org/sqlite — SQLite's actual C source transpiled to pure Go (no CGO), so the
// build stays CGO-free while we get SQLite's battle-tested WAL crash recovery (a torn WAL is
// truncated on reopen, not panicked on). Replaced turso.tech/database/tursogo, whose Rust engine
// was beta and corrupted the file on an unclean kill.
//
// path ":memory:" (or "file::memory:…") opens an ephemeral database (tests). A file path has its
// parent directory created if missing and gets WAL/synchronous; an in-memory db has no file to
// journal or fsync, and is pinned to a single connection so the pool can't hand out separate
// empty databases (each :memory: connection is otherwise its own database).
func Open(ctx context.Context, path string, busyTimeout time.Duration) (*sql.DB, error) {
	memory := path == ":memory:" || strings.HasPrefix(path, "file::memory:")
	if !memory {
		if dir := filepath.Dir(path); dir != "" && dir != "." {
			if err := os.MkdirAll(dir, 0o755); err != nil {
				return nil, fmt.Errorf("create db dir %q: %w", dir, err)
			}
		}
	}

	ms := int(busyTimeout / time.Millisecond)
	if ms <= 0 {
		ms = 5000
	}

	pragmas := []string{
		fmt.Sprintf("_pragma=busy_timeout(%d)", ms),
		"_pragma=foreign_keys(ON)",
	}
	if !memory {
		pragmas = append(pragmas, "_pragma=journal_mode(WAL)", "_pragma=synchronous(FULL)")
	}
	sep := "?"
	if strings.Contains(path, "?") {
		sep = "&"
	}
	dsn := path + sep + strings.Join(pragmas, "&")

	sqlDB, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("open sqlite db %q: %w", path, err)
	}
	if memory {
		// One connection → one in-memory database for the whole *sql.DB, so migrations applied
		// on one connection are visible to every later query (otherwise the pool would scatter
		// the schema across distinct, empty in-memory databases).
		sqlDB.SetMaxOpenConns(1)
	}
	if err := sqlDB.PingContext(ctx); err != nil {
		sqlDB.Close()
		return nil, fmt.Errorf("open sqlite db %q: %w", path, err)
	}
	return sqlDB, nil
}

