package dbjson

import (
	"reflect"
	"testing"
)

type payload struct {
	Name  string `json:"name,omitempty"`
	Count int    `json:"count,omitempty"`
}

// JSON[T] is for NOT NULL columns: it always Values to JSON bytes (never SQL NULL) and Scans
// text/blob/empty back into the concrete T.
func TestJSON_RoundTrip(t *testing.T) {
	src := JSON[payload]{V: payload{Name: "anvil", Count: 3}}
	v, err := src.Value()
	if err != nil {
		t.Fatalf("Value: %v", err)
	}
	b, ok := v.([]byte)
	if !ok {
		t.Fatalf("Value returned %T, want []byte", v)
	}

	var dst JSON[payload]
	if err := dst.Scan(b); err != nil {
		t.Fatalf("Scan: %v", err)
	}
	if !reflect.DeepEqual(dst.V, src.V) {
		t.Fatalf("round-trip mismatch: got %+v, want %+v", dst.V, src.V)
	}

	// Empty/absent payload decodes to the zero value, never an error (a NOT NULL column that was
	// stored as "" must not blow up a reader).
	var fromEmpty JSON[payload]
	if err := fromEmpty.Scan([]byte(nil)); err != nil {
		t.Fatalf("Scan empty: %v", err)
	}
	if fromEmpty.V != (payload{}) {
		t.Fatalf("empty Scan: got %+v, want zero", fromEmpty.V)
	}
}

// Null[T] is for NULLABLE columns: SQL NULL ⇄ Valid=false round-trips both ways, and a present
// value carries the typed payload with Valid=true.
func TestNull_NullRoundTrip(t *testing.T) {
	// A nil driver.Value (how the pure-Go SQLite driver hands back SQL NULL) → Valid=false.
	var n Null[payload]
	if err := n.Scan(nil); err != nil {
		t.Fatalf("Scan nil: %v", err)
	}
	if n.Valid {
		t.Fatalf("Scan nil: Valid=true, want false")
	}
	// An invalid Null Values back to SQL NULL, not to a JSON "null" literal.
	v, err := n.Value()
	if err != nil {
		t.Fatalf("Value: %v", err)
	}
	if v != nil {
		t.Fatalf("invalid Null Value = %v (%T), want nil (SQL NULL)", v, v)
	}
}

func TestNull_ValueRoundTrip(t *testing.T) {
	src := Null[payload]{V: payload{Name: "bridge", Count: 7}, Valid: true}
	v, err := src.Value()
	if err != nil {
		t.Fatalf("Value: %v", err)
	}
	b := v.([]byte)

	var dst Null[payload]
	if err := dst.Scan(string(b)); err != nil { // drivers may hand back text as string
		t.Fatalf("Scan string: %v", err)
	}
	if !dst.Valid || !reflect.DeepEqual(dst.V, src.V) {
		t.Fatalf("round-trip mismatch: got valid=%v %+v, want valid=true %+v", dst.Valid, dst.V, src.V)
	}
}

// The open-payload variant used for the dormant coordination columns must round-trip too.
func TestNull_OpenMap(t *testing.T) {
	src := Null[map[string]any]{V: map[string]any{"reason": "merge", "confidence": 0.5}, Valid: true}
	v, err := src.Value()
	if err != nil {
		t.Fatalf("Value: %v", err)
	}
	var dst Null[map[string]any]
	if err := dst.Scan(v); err != nil {
		t.Fatalf("Scan: %v", err)
	}
	if !dst.Valid || dst.V["reason"] != "merge" {
		t.Fatalf("open-map round-trip lost data: %+v", dst.V)
	}
}

package postgres

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"sync"
	"time"

	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	"github.com/dnd-llm/dnd-llm/internal/infrastructure/persistence/dbcols"
	"github.com/dnd-llm/dnd-llm/internal/infrastructure/persistence/dbjson"
	"github.com/dnd-llm/dnd-llm/internal/infrastructure/persistence/sqlcdb"
	"github.com/google/uuid"
	"go.uber.org/zap"
)

// subscriberEntry holds information about a subscription.
type subscriberEntry struct {
	criteria event.StreamCriteria
	handler  event.EventHandler
}

// SQLCEventStore implements the EventStore interface using sqlc-generated code.
type SQLCEventStore struct {
	db          *sql.DB
	queries     *sqlcdb.Queries
	logger      *zap.Logger
	subscribers map[string][]subscriberEntry
	mu          sync.RWMutex
}

// NewSQLCEventStore creates a new SQLC-backed event store. logger may be nil.
func NewSQLCEventStore(db *sql.DB, logger *zap.Logger) *SQLCEventStore {
	if logger == nil {
		logger = zap.NewNop()
	}
	return &SQLCEventStore{
		db:          db,
		queries:     sqlcdb.New(db),
		logger:      logger,
		subscribers: make(map[string][]subscriberEntry),
	}
}

// Append adds a new event to the event store.
func (es *SQLCEventStore) Append(ctx context.Context, e *event.GameEvent) error {
	if err := e.Validate(); err != nil {
		return fmt.Errorf("invalid event: %w", err)
	}

	tx, err := es.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("begin transaction: %w", err)
	}
	defer tx.Rollback()

	qtx := es.queries.WithTx(tx)

	// Serialize event data
	eventData, err := json.Marshal(e.Data)
	if err != nil {
		return fmt.Errorf("marshal event data: %w", err)
	}

	// Get tick value
	tickValue := int64(e.Tick)

	// IDs are TEXT at the SQL boundary; domain id types are strings underneath.
	eventID := string(e.ID)

	// Create event params
	params := sqlcdb.CreateEventParams{
		ID:         eventID,
		Type:       string(e.Type),
		ActorID:    string(e.ActorID),
		TargetID:   actorIDPtr(e.TargetID),
		LocationID: string(e.LocationID),
		WorldID:    string(e.WorldID),
		Tick:       tickValue,
		Data:       eventData,
		Visibility: string(e.Visibility),
		CausedBy:   eventIDPtr(e.CausedBy),
		Metadata:   eventMetadataToCol(e.Metadata),
		CreatedAt:  e.CreatedAt,
	}

	_, err = qtx.CreateEvent(ctx, params)
	if err != nil {
		return fmt.Errorf("insert event: %w", err)
	}

	// Calculate stream keys and insert into event streams
	streams := es.calculateStreams(e)
	for _, streamKey := range streams {
		_, err = qtx.CreateEventStream(ctx, sqlcdb.CreateEventStreamParams{
			StreamID:  streamKey,
			EventID:   eventID,
			Tick:      tickValue,
			CreatedAt: e.CreatedAt,
		})
		if err != nil {
			return fmt.Errorf("insert into stream %s: %w", streamKey, err)
		}
	}

	if err := tx.Commit(); err != nil {
		return fmt.Errorf("commit transaction: %w", err)
	}

	// Notify subscribers asynchronously
	go es.notifySubscribers(e)

	return nil
}

// AppendBatch adds multiple events in a single transaction.
func (es *SQLCEventStore) AppendBatch(ctx context.Context, events []*event.GameEvent) error {
	if len(events) == 0 {
		return nil
	}

	// Validate all events
	for i, e := range events {
		if err := e.Validate(); err != nil {
			return fmt.Errorf("invalid event at index %d: %w", i, err)
		}
	}

	tx, err := es.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("begin transaction: %w", err)
	}
	defer tx.Rollback()

	qtx := es.queries.WithTx(tx)

	for _, e := range events {
		// Serialize event data
		eventData, err := json.Marshal(e.Data)
		if err != nil {
			return fmt.Errorf("marshal event data for %s: %w", e.ID, err)
		}

		// Get tick value
		tickValue := int64(e.Tick)
		eventID := string(e.ID)

		// Create event
		params := sqlcdb.CreateEventParams{
			ID:         eventID,
			Type:       string(e.Type),
			ActorID:    string(e.ActorID),
			TargetID:   actorIDPtr(e.TargetID),
			LocationID: string(e.LocationID),
			WorldID:    string(e.WorldID),
			Tick:       tickValue,
			Data:       eventData,
			Visibility: string(e.Visibility),
			CausedBy:   eventIDPtr(e.CausedBy),
			Metadata:   eventMetadataToCol(e.Metadata),
			CreatedAt:  e.CreatedAt,
		}

		_, err = qtx.CreateEvent(ctx, params)
		if err != nil {
			return fmt.Errorf("insert event %s: %w", e.ID, err)
		}

		// Insert into streams
		streams := es.calculateStreams(e)
		for _, streamKey := range streams {
			_, err = qtx.CreateEventStream(ctx, sqlcdb.CreateEventStreamParams{
				StreamID:  streamKey,
				EventID:   eventID,
				Tick:      tickValue,
				CreatedAt: e.CreatedAt,
			})
			if err != nil {
				return fmt.Errorf("insert event %s into stream %s: %w", e.ID, streamKey, err)
			}
		}
	}

	if err := tx.Commit(); err != nil {
		return fmt.Errorf("commit transaction: %w", err)
	}

	// Notify subscribers asynchronously
	for _, e := range events {
		go es.notifySubscribers(e)
	}

	return nil
}

// GetEventByID retrieves a specific event by its ID.
func (es *SQLCEventStore) GetEventByID(ctx context.Context, id domain.EventID) (*event.GameEvent, error) {
	dbEvent, err := es.queries.GetEventByID(ctx, string(id))
	if err == sql.ErrNoRows {
		return nil, fmt.Errorf("event not found: %s", id)
	}
	if err != nil {
		return nil, fmt.Errorf("query event: %w", err)
	}

	return es.dbEventToGameEvent(dbEvent)
}

// GetEventStream retrieves events matching the given criteria.
func (es *SQLCEventStore) GetEventStream(ctx context.Context, criteria event.StreamCriteria) ([]*event.GameEvent, error) {
	limit := int64(1000)
	if criteria.Limit > 0 {
		limit = int64(criteria.Limit)
	}
	offset := int64(criteria.Offset)

	var dbEvents []*sqlcdb.Event
	var err error

	// Use the most specific query based on criteria
	switch {
	case criteria.WorldID != nil && criteria.ActorID != nil &&
		(criteria.FromTick != nil || criteria.ToTick != nil || len(criteria.EventTypes) > 0):
		// The actor-scoped windowed read: same discipline as the world window
		// below — types and ticks pushed down together, so LIMIT bites the
		// window, not the actor's whole history.
		var fromTick int64
		if criteria.FromTick != nil {
			fromTick = int64(*criteria.FromTick)
		}
		dbEvents, err = es.queries.ListEventsByActorTickWindow(ctx, sqlcdb.ListEventsByActorTickWindowParams{
			WorldID:   string(*criteria.WorldID),
			ActorID:   string(*criteria.ActorID),
			Types:     eventTypesJSON(criteria.EventTypes),
			FromTick:  fromTick,
			ToTick:    nullTick(criteria.ToTick),
			RowLimit:  limit,
			RowOffset: offset,
		})
	case criteria.WorldID != nil && criteria.ActorID != nil:
		worldID := string(*criteria.WorldID)
		actorID := string(*criteria.ActorID)
		dbEvents, err = es.queries.ListEventsByWorldAndActor(ctx, sqlcdb.ListEventsByWorldAndActorParams{
			WorldID: worldID,
			ActorID: actorID,
			Limit:   limit,
			Offset:  offset,
		})
	case criteria.WorldID != nil && criteria.LocationID != nil:
		worldID := string(*criteria.WorldID)
		locationID := string(*criteria.LocationID)
		dbEvents, err = es.queries.ListEventsByWorldAndLocation(ctx, sqlcdb.ListEventsByWorldAndLocationParams{
			WorldID:    worldID,
			LocationID: locationID,
			Limit:      limit,
			Offset:     offset,
		})
	case criteria.WorldID != nil && (criteria.FromTick != nil || criteria.ToTick != nil || len(criteria.EventTypes) > 0):
		// The windowed read: types and the tick window are pushed down to SQL
		// together. Splitting them across queries silently turns LIMIT into
		// "the oldest N rows of the whole log" — conversation history, weaver
		// signals and goal folds all read through here and all broke that way
		// once the log outgrew one LIMIT page.
		var fromTick int64
		if criteria.FromTick != nil {
			fromTick = int64(*criteria.FromTick)
		}
		dbEvents, err = es.queries.ListEventsByWorldTickWindow(ctx, sqlcdb.ListEventsByWorldTickWindowParams{
			WorldID:   string(*criteria.WorldID),
			Types:     eventTypesJSON(criteria.EventTypes),
			FromTick:  fromTick,
			ToTick:    nullTick(criteria.ToTick),
			RowLimit:  limit,
			RowOffset: offset,
		})
	case criteria.WorldID != nil && criteria.Visibility != nil:
		worldID := string(*criteria.WorldID)
		dbEvents, err = es.queries.ListEventsByWorldAndVisibility(ctx, sqlcdb.ListEventsByWorldAndVisibilityParams{
			WorldID:    worldID,
			Visibility: string(*criteria.Visibility),
			Limit:      limit,
			Offset:     offset,
		})
	case criteria.ParticipantID != nil:
		participantID := string(*criteria.ParticipantID)
		dbEvents, err = es.queries.ListEventsByParticipant(ctx, sqlcdb.ListEventsByParticipantParams{
			ActorID: participantID,
			Limit:   limit,
			Offset:  offset,
		})
	case criteria.WorldID != nil:
		worldID := string(*criteria.WorldID)
		dbEvents, err = es.queries.ListEventsByWorld(ctx, sqlcdb.ListEventsByWorldParams{
			WorldID: worldID,
			Limit:   limit,
			Offset:  offset,
		})
	case criteria.ActorID != nil:
		actorID := string(*criteria.ActorID)
		dbEvents, err = es.queries.ListEventsByActor(ctx, sqlcdb.ListEventsByActorParams{
			ActorID: actorID,
			Limit:   limit,
			Offset:  offset,
		})
	case criteria.LocationID != nil:
		locationID := string(*criteria.LocationID)
		dbEvents, err = es.queries.ListEventsByLocation(ctx, sqlcdb.ListEventsByLocationParams{
			LocationID: locationID,
			Limit:      limit,
			Offset:     offset,
		})
	case len(criteria.EventTypes) == 1:
		dbEvents, err = es.queries.ListEventsByType(ctx, sqlcdb.ListEventsByTypeParams{
			Type:   string(criteria.EventTypes[0]),
			Limit:  limit,
			Offset: offset,
		})
	default:
		// Fallback to listing all events (filtered in-memory)
		dbEvents, err = es.queries.ListAllEvents(ctx, sqlcdb.ListAllEventsParams{
			Limit:  limit,
			Offset: offset,
		})
	}

	if err != nil {
		return nil, fmt.Errorf("query events: %w", err)
	}

	// Convert to domain events and apply in-memory filters for criteria not in SQL.
	// A row that fails to decode (a payload shape from an older build that typed
	// decoding no longer accepts) is skipped with a warning rather than failing
	// the whole read: the event log is immutable, so one bad historical row must
	// degrade that one event — not poison every replay, perception and memory
	// read whose window covers it.
	events := make([]*event.GameEvent, 0, len(dbEvents))
	for _, dbEvent := range dbEvents {
		gameEvent, err := es.dbEventToGameEvent(dbEvent)
		if err != nil {
			es.logger.Warn("event store: skipping undecodable event row",
				zap.String("event_id", dbEvent.ID),
				zap.String("type", dbEvent.Type),
				zap.Error(err))
			continue
		}

		// Apply in-memory filtering for criteria not covered by SQL
		if criteria.Matches(gameEvent) {
			events = append(events, gameEvent)
		}
	}

	return events, nil
}

// GetEventConnections retrieves all causal connections for an event.
func (es *SQLCEventStore) GetEventConnections(ctx context.Context, id domain.EventID) ([]event.EventConnection, error) {
	eventID := string(id)
	dbConns, err := es.queries.GetEventConnections(ctx, sqlcdb.GetEventConnectionsParams{
		FromEventID: eventID,
		ToEventID:   eventID,
	})
	if err != nil {
		return nil, fmt.Errorf("query connections: %w", err)
	}

	connections := make([]event.EventConnection, 0, len(dbConns))
	for _, dbConn := range dbConns {
		conn, err := es.dbConnToEventConnection(dbConn)
		if err != nil {
			return nil, err
		}
		connections = append(connections, conn)
	}

	return connections, nil
}

// UpdateConnections updates the causal connections for an event.
func (es *SQLCEventStore) UpdateConnections(ctx context.Context, id domain.EventID, links []event.EventConnection) error {
	tx, err := es.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("begin transaction: %w", err)
	}
	defer tx.Rollback()

	qtx := es.queries.WithTx(tx)

	eventID := string(id)

	// Delete existing connections from this event
	if err := qtx.DeleteEventConnectionsFrom(ctx, eventID); err != nil {
		return fmt.Errorf("delete existing connections: %w", err)
	}

	// Insert new connections
	for _, link := range links {
		fromEventID := string(link.FromEventID)
		toEventID := string(link.ToEventID)

		_, err = qtx.CreateEventConnection(ctx, sqlcdb.CreateEventConnectionParams{
			FromEventID:    fromEventID,
			ToEventID:      toEventID,
			ConnectionType: string(link.Type),
			Weight:         link.Weight,
			Metadata:       connMetaToCol(link.Metadata),
			CreatedAt:      link.CreatedAt,
		})
		if err != nil {
			return fmt.Errorf("insert connection: %w", err)
		}
	}

	return tx.Commit()
}

// Subscribe subscribes to events matching the criteria.
func (es *SQLCEventStore) Subscribe(ctx context.Context, criteria event.StreamCriteria, handler event.EventHandler) (event.Unsubscribe, error) {
	streamKey := es.criteriaToKey(criteria)

	entry := subscriberEntry{
		criteria: criteria,
		handler:  handler,
	}

	es.mu.Lock()
	es.subscribers[streamKey] = append(es.subscribers[streamKey], entry)
	es.mu.Unlock()

	// Return unsubscribe function
	return func() {
		es.mu.Lock()
		defer es.mu.Unlock()

		entries := es.subscribers[streamKey]
		for i, e := range entries {
			if criteriaEqual(e.criteria, criteria) {
				es.subscribers[streamKey] = append(entries[:i], entries[i+1:]...)
				break
			}
		}
	}, nil
}

// Replay replays all events matching the criteria through the handler.
func (es *SQLCEventStore) Replay(ctx context.Context, criteria event.StreamCriteria, handler event.EventHandler) error {
	events, err := es.GetEventStream(ctx, criteria)
	if err != nil {
		return fmt.Errorf("get event stream: %w", err)
	}

	for _, e := range events {
		if err := handler(ctx, e); err != nil {
			return fmt.Errorf("handler error at event %s: %w", e.ID, err)
		}
	}

	return nil
}

// CreateSnapshot creates a snapshot of an aggregate's state.
func (es *SQLCEventStore) CreateSnapshot(ctx context.Context, aggregateID uuid.UUID, version int64, data []byte) error {
	_, err := es.queries.CreateSnapshot(ctx, sqlcdb.CreateSnapshotParams{
		AggregateID:   aggregateID.String(),
		AggregateType: "unknown", // Generic type for now
		Version:       version,
		Data:          data,
		CreatedAt:     time.Now(),
	})
	if err != nil {
		return fmt.Errorf("insert snapshot: %w", err)
	}
	return nil
}

// GetLatestSnapshot retrieves the most recent snapshot for an aggregate.
func (es *SQLCEventStore) GetLatestSnapshot(ctx context.Context, aggregateID uuid.UUID) (*event.Snapshot, error) {
	dbSnapshot, err := es.queries.GetLatestSnapshot(ctx, aggregateID.String())
	if err == sql.ErrNoRows {
		return nil, fmt.Errorf("snapshot not found for aggregate %s", aggregateID)
	}
	if err != nil {
		return nil, fmt.Errorf("query snapshot: %w", err)
	}

	aggID, _ := uuid.Parse(dbSnapshot.AggregateID)
	return &event.Snapshot{
		AggregateID:   aggID,
		AggregateType: dbSnapshot.AggregateType,
		Version:       dbSnapshot.Version,
		Data:          dbSnapshot.Data,
		CreatedAt:     dbSnapshot.CreatedAt,
	}, nil
}

// DeleteOldSnapshots deletes snapshots older than the given version.
func (es *SQLCEventStore) DeleteOldSnapshots(ctx context.Context, aggregateID uuid.UUID, keepVersion int64) error {
	err := es.queries.DeleteOldSnapshots(ctx, sqlcdb.DeleteOldSnapshotsParams{
		AggregateID: aggregateID.String(),
		Version:     keepVersion,
	})
	if err != nil {
		return fmt.Errorf("delete old snapshots: %w", err)
	}
	return nil
}

// CountEvents counts events matching the given criteria.
func (es *SQLCEventStore) CountEvents(ctx context.Context, criteria event.StreamCriteria) (int, error) {
	var count int64
	var err error

	// Use specific count query based on criteria
	switch {
	case criteria.WorldID != nil:
		worldID := string(*criteria.WorldID)
		count, err = es.queries.CountEventsByWorld(ctx, worldID)
	case criteria.ActorID != nil:
		actorID := string(*criteria.ActorID)
		count, err = es.queries.CountEventsByActor(ctx, actorID)
	case criteria.LocationID != nil:
		locationID := string(*criteria.LocationID)
		count, err = es.queries.CountEventsByLocation(ctx, locationID)
	default:
		// Fallback: count by fetching all matching events (less efficient)
		events, fetchErr := es.GetEventStream(ctx, criteria)
		if fetchErr != nil {
			return 0, fetchErr
		}
		return len(events), nil
	}

	if err != nil {
		return 0, fmt.Errorf("count events: %w", err)
	}

	return int(count), nil
}

// MaxTick returns the highest tick recorded for the world across the whole log
// (all incarnations share it), or 0 when the world has never ticked.
func (es *SQLCEventStore) MaxTick(ctx context.Context, worldID domain.WorldID) (domain.Tick, error) {
	maxTick, err := es.queries.MaxTickByWorld(ctx, string(worldID))
	if err != nil {
		return 0, fmt.Errorf("max tick by world: %w", err)
	}
	// COALESCE(MAX(tick), 0) comes back as an untyped interface from the SQLite
	// driver; normalise to int64.
	var tick int64
	switch v := maxTick.(type) {
	case int64:
		tick = v
	case float64:
		tick = int64(v)
	}
	return domain.Tick(tick), nil
}

// Helper methods

// calculateStreams calculates all stream keys for an event.
func (es *SQLCEventStore) calculateStreams(e *event.GameEvent) []string {
	streams := []string{
		"main",
		fmt.Sprintf("world:%s", e.WorldID),
		fmt.Sprintf("actor:%s", e.ActorID),
		fmt.Sprintf("location:%s", e.LocationID),
		fmt.Sprintf("type:%s", e.Type),
	}

	if e.TargetID != nil && !e.TargetID.IsZero() {
		streams = append(streams, fmt.Sprintf("actor:%s", *e.TargetID))
	}

	return streams
}

// criteriaToKey creates a unique key for subscription criteria.
func (es *SQLCEventStore) criteriaToKey(criteria event.StreamCriteria) string {
	if criteria.WorldID != nil {
		return fmt.Sprintf("world:%s", *criteria.WorldID)
	}
	if criteria.ActorID != nil {
		return fmt.Sprintf("actor:%s", *criteria.ActorID)
	}
	if criteria.LocationID != nil {
		return fmt.Sprintf("location:%s", *criteria.LocationID)
	}
	return "main"
}

// notifySubscribers notifies all matching subscribers about a new event.
func (es *SQLCEventStore) notifySubscribers(e *event.GameEvent) {
	es.mu.RLock()
	defer es.mu.RUnlock()

	for _, entries := range es.subscribers {
		for _, entry := range entries {
			if entry.criteria.Matches(e) {
				go func(h event.EventHandler) {
					ctx := context.Background()
					_ = h(ctx, e)
				}(entry.handler)
			}
		}
	}
}

// dbEventToGameEvent converts a database event to a domain event.
func (es *SQLCEventStore) dbEventToGameEvent(dbEvent *sqlcdb.Event) (*event.GameEvent, error) {
	e := &event.GameEvent{
		ID:         domain.EventID(dbEvent.ID),
		Type:       event.EventType(dbEvent.Type),
		ActorID:    domain.ActorID(dbEvent.ActorID),
		LocationID: domain.LocationID(dbEvent.LocationID),
		WorldID:    domain.WorldID(dbEvent.WorldID),
		Tick:       domain.Tick(dbEvent.Tick),
		Visibility: domain.Visibility(dbEvent.Visibility),
		CreatedAt:  dbEvent.CreatedAt,
	}

	// Handle nullable fields (TEXT columns -> *string)
	if dbEvent.TargetID != nil && *dbEvent.TargetID != "" {
		targetID := domain.ActorID(*dbEvent.TargetID)
		e.TargetID = &targetID
	}

	if dbEvent.CausedBy != nil && *dbEvent.CausedBy != "" {
		causedBy := domain.EventID(*dbEvent.CausedBy)
		e.CausedBy = &causedBy
	}

	// Metadata: a strictly-typed nullable column — present only when Valid (no manual unmarshal).
	if dbEvent.Metadata.Valid {
		m := dbEvent.Metadata.V
		e.Metadata = &m
	}

	// Unmarshal event data
	eventData, err := unmarshalEventData(e.Type, dbEvent.Data)
	if err != nil {
		return nil, fmt.Errorf("unmarshal event data: %w", err)
	}
	e.Data = eventData

	return e, nil
}

// dbConnToEventConnection converts a database connection to a domain connection.
func (es *SQLCEventStore) dbConnToEventConnection(dbConn *sqlcdb.EventConnection) (event.EventConnection, error) {
	conn := event.EventConnection{
		FromEventID: domain.EventID(dbConn.FromEventID),
		ToEventID:   domain.EventID(dbConn.ToEventID),
		Type:        event.ConnectionType(dbConn.ConnectionType),
		Weight:      dbConn.Weight,
		CreatedAt:   dbConn.CreatedAt,
	}

	if dbConn.Metadata.Valid {
		conn.Metadata = dbConn.Metadata.V
	}

	return conn, nil
}

// Helper functions for criteria conversion

// actorIDPtr / eventIDPtr turn an optional domain id into the *string the SQL
// boundary uses for nullable TEXT columns (nil = SQL NULL).
func actorIDPtr(id *domain.ActorID) *string {
	if id == nil || id.IsZero() {
		return nil
	}
	s := string(*id)
	return &s
}

func eventIDPtr(id *domain.EventID) *string {
	if id == nil || id.IsZero() {
		return nil
	}
	s := string(*id)
	return &s
}

// eventTypesJSON encodes the optional event-type filter as a JSON array string
// for json_each() in the windowed reads; nil means "no type filter".
func eventTypesJSON(types []event.EventType) interface{} {
	if len(types) == 0 {
		return nil
	}
	arr := make([]string, len(types))
	for i, t := range types {
		arr[i] = string(t)
	}
	data, err := json.Marshal(arr)
	if err != nil {
		return nil
	}
	return string(data)
}

// nullTick passes an optional upper tick bound as int64 or nil.
func nullTick(t *domain.Tick) interface{} {
	if t == nil {
		return nil
	}
	return int64(*t)
}

// eventMetadataToCol wraps optional coordination metadata for the strictly-typed events.metadata
// column: nil → SQL NULL (Valid=false), present → the typed payload. The column type
// (dbjson.Null[event.EventMetadata]) marshals it at the DB boundary, so no JSON bytes pass here.
func eventMetadataToCol(m *event.EventMetadata) dbcols.EventMetadata {
	if m == nil {
		return dbcols.EventMetadata{}
	}
	return dbcols.EventMetadata{V: *m, Valid: true}
}

// connMetaToCol wraps a connection's open metadata map for the nullable connection.metadata
// column: nil → SQL NULL, present → the map marshaled at the DB boundary.
func connMetaToCol(m map[string]any) dbjson.Null[map[string]any] {
	if m == nil {
		return dbjson.Null[map[string]any]{}
	}
	return dbjson.Null[map[string]any]{V: m, Valid: true}
}

// criteriaEqual checks if two criteria are functionally equivalent.
func criteriaEqual(a, b event.StreamCriteria) bool {
	// Compare WorldID
	if (a.WorldID == nil) != (b.WorldID == nil) {
		return false
	}
	if a.WorldID != nil && *a.WorldID != *b.WorldID {
		return false
	}

	// Compare ActorID
	if (a.ActorID == nil) != (b.ActorID == nil) {
		return false
	}
	if a.ActorID != nil && *a.ActorID != *b.ActorID {
		return false
	}

	// Compare LocationID
	if (a.LocationID == nil) != (b.LocationID == nil) {
		return false
	}
	if a.LocationID != nil && *a.LocationID != *b.LocationID {
		return false
	}

	// Compare ParticipantID
	if (a.ParticipantID == nil) != (b.ParticipantID == nil) {
		return false
	}
	if a.ParticipantID != nil && *a.ParticipantID != *b.ParticipantID {
		return false
	}

	return true
}

// unmarshalEventData reconstructs the concrete EventData for a stored event.
// It delegates to event.UnmarshalEventData (the single source of truth for
// event-data typing) so that consumers which type-switch on the concrete data —
// memory formation, narration — receive the real typed payload rather than a
// generic map that would silently degrade them.
func unmarshalEventData(eventType event.EventType, data []byte) (event.EventData, error) {
	if len(data) == 0 {
		data = []byte("{}")
	}
	return event.UnmarshalEventData(eventType, data)
}

package dbjson

import (
	"reflect"
	"testing"
)

type payload struct {
	Name  string `json:"name,omitempty"`
	Count int    `json:"count,omitempty"`
}

// JSON[T] is for NOT NULL columns: it always Values to JSON bytes (never SQL NULL) and Scans
// text/blob/empty back into the concrete T.
func TestJSON_RoundTrip(t *testing.T) {
	src := JSON[payload]{V: payload{Name: "anvil", Count: 3}}
	v, err := src.Value()
	if err != nil {
		t.Fatalf("Value: %v", err)
	}
	b, ok := v.([]byte)
	if !ok {
		t.Fatalf("Value returned %T, want []byte", v)
	}

	var dst JSON[payload]
	if err := dst.Scan(b); err != nil {
		t.Fatalf("Scan: %v", err)
	}
	if !reflect.DeepEqual(dst.V, src.V) {
		t.Fatalf("round-trip mismatch: got %+v, want %+v", dst.V, src.V)
	}

	// Empty/absent payload decodes to the zero value, never an error (a NOT NULL column that was
	// stored as "" must not blow up a reader).
	var fromEmpty JSON[payload]
	if err := fromEmpty.Scan([]byte(nil)); err != nil {
		t.Fatalf("Scan empty: %v", err)
	}
	if fromEmpty.V != (payload{}) {
		t.Fatalf("empty Scan: got %+v, want zero", fromEmpty.V)
	}
}

// Null[T] is for NULLABLE columns: SQL NULL ⇄ Valid=false round-trips both ways, and a present
// value carries the typed payload with Valid=true.
func TestNull_NullRoundTrip(t *testing.T) {
	// A nil driver.Value (how the pure-Go SQLite driver hands back SQL NULL) → Valid=false.
	var n Null[payload]
	if err := n.Scan(nil); err != nil {
		t.Fatalf("Scan nil: %v", err)
	}
	if n.Valid {
		t.Fatalf("Scan nil: Valid=true, want false")
	}
	// An invalid Null Values back to SQL NULL, not to a JSON "null" literal.
	v, err := n.Value()
	if err != nil {
		t.Fatalf("Value: %v", err)
	}
	if v != nil {
		t.Fatalf("invalid Null Value = %v (%T), want nil (SQL NULL)", v, v)
	}
}

func TestNull_ValueRoundTrip(t *testing.T) {
	src := Null[payload]{V: payload{Name: "bridge", Count: 7}, Valid: true}
	v, err := src.Value()
	if err != nil {
		t.Fatalf("Value: %v", err)
	}
	b := v.([]byte)

	var dst Null[payload]
	if err := dst.Scan(string(b)); err != nil { // drivers may hand back text as string
		t.Fatalf("Scan string: %v", err)
	}
	if !dst.Valid || !reflect.DeepEqual(dst.V, src.V) {
		t.Fatalf("round-trip mismatch: got valid=%v %+v, want valid=true %+v", dst.Valid, dst.V, src.V)
	}
}

// The open-payload variant used for the dormant coordination columns must round-trip too.
func TestNull_OpenMap(t *testing.T) {
	src := Null[map[string]any]{V: map[string]any{"reason": "merge", "confidence": 0.5}, Valid: true}
	v, err := src.Value()
	if err != nil {
		t.Fatalf("Value: %v", err)
	}
	var dst Null[map[string]any]
	if err := dst.Scan(v); err != nil {
		t.Fatalf("Scan: %v", err)
	}
	if !dst.Valid || dst.V["reason"] != "merge" {
		t.Fatalf("open-map round-trip lost data: %+v", dst.V)
	}
}

package postgres

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"sync"
	"time"

	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	"github.com/dnd-llm/dnd-llm/internal/infrastructure/persistence/dbcols"
	"github.com/dnd-llm/dnd-llm/internal/infrastructure/persistence/dbjson"
	"github.com/dnd-llm/dnd-llm/internal/infrastructure/persistence/sqlcdb"
	"github.com/google/uuid"
	"go.uber.org/zap"
)

// subscriberEntry holds information about a subscription.
type subscriberEntry struct {
	criteria event.StreamCriteria
	handler  event.EventHandler
}

// SQLCEventStore implements the EventStore interface using sqlc-generated code.
type SQLCEventStore struct {
	db          *sql.DB
	queries     *sqlcdb.Queries
	logger      *zap.Logger
	subscribers map[string][]subscriberEntry
	mu          sync.RWMutex
}

// NewSQLCEventStore creates a new SQLC-backed event store. logger may be nil.
func NewSQLCEventStore(db *sql.DB, logger *zap.Logger) *SQLCEventStore {
	if logger == nil {
		logger = zap.NewNop()
	}
	return &SQLCEventStore{
		db:          db,
		queries:     sqlcdb.New(db),
		logger:      logger,
		subscribers: make(map[string][]subscriberEntry),
	}
}

// Append adds a new event to the event store.
func (es *SQLCEventStore) Append(ctx context.Context, e *event.GameEvent) error {
	if err := e.Validate(); err != nil {
		return fmt.Errorf("invalid event: %w", err)
	}

	tx, err := es.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("begin transaction: %w", err)
	}
	defer tx.Rollback()

	qtx := es.queries.WithTx(tx)

	// Serialize event data
	eventData, err := json.Marshal(e.Data)
	if err != nil {
		return fmt.Errorf("marshal event data: %w", err)
	}

	// Get tick value
	tickValue := int64(e.Tick)

	// IDs are TEXT at the SQL boundary; domain id types are strings underneath.
	eventID := string(e.ID)

	// Create event params
	params := sqlcdb.CreateEventParams{
		ID:         eventID,
		Type:       string(e.Type),
		ActorID:    string(e.ActorID),
		TargetID:   actorIDPtr(e.TargetID),
		LocationID: string(e.LocationID),
		WorldID:    string(e.WorldID),
		Tick:       tickValue,
		Data:       eventData,
		Visibility: string(e.Visibility),
		CausedBy:   eventIDPtr(e.CausedBy),
		Metadata:   eventMetadataToCol(e.Metadata),
		CreatedAt:  e.CreatedAt,
	}

	_, err = qtx.CreateEvent(ctx, params)
	if err != nil {
		return fmt.Errorf("insert event: %w", err)
	}

	// Calculate stream keys and insert into event streams
	streams := es.calculateStreams(e)
	for _, streamKey := range streams {
		_, err = qtx.CreateEventStream(ctx, sqlcdb.CreateEventStreamParams{
			StreamID:  streamKey,
			EventID:   eventID,
			Tick:      tickValue,
			CreatedAt: e.CreatedAt,
		})
		if err != nil {
			return fmt.Errorf("insert into stream %s: %w", streamKey, err)
		}
	}

	if err := tx.Commit(); err != nil {
		return fmt.Errorf("commit transaction: %w", err)
	}

	// Notify subscribers asynchronously
	go es.notifySubscribers(e)

	return nil
}

// AppendBatch adds multiple events in a single transaction.
func (es *SQLCEventStore) AppendBatch(ctx context.Context, events []*event.GameEvent) error {
	if len(events) == 0 {
		return nil
	}

	// Validate all events
	for i, e := range events {
		if err := e.Validate(); err != nil {
			return fmt.Errorf("invalid event at index %d: %w", i, err)
		}
	}

	tx, err := es.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("begin transaction: %w", err)
	}
	defer tx.Rollback()

	qtx := es.queries.WithTx(tx)

	for _, e := range events {
		// Serialize event data
		eventData, err := json.Marshal(e.Data)
		if err != nil {
			return fmt.Errorf("marshal event data for %s: %w", e.ID, err)
		}

		// Get tick value
		tickValue := int64(e.Tick)
		eventID := string(e.ID)

		// Create event
		params := sqlcdb.CreateEventParams{
			ID:         eventID,
			Type:       string(e.Type),
			ActorID:    string(e.ActorID),
			TargetID:   actorIDPtr(e.TargetID),
			LocationID: string(e.LocationID),
			WorldID:    string(e.WorldID),
			Tick:       tickValue,
			Data:       eventData,
			Visibility: string(e.Visibility),
			CausedBy:   eventIDPtr(e.CausedBy),
			Metadata:   eventMetadataToCol(e.Metadata),
			CreatedAt:  e.CreatedAt,
		}

		_, err = qtx.CreateEvent(ctx, params)
		if err != nil {
			return fmt.Errorf("insert event %s: %w", e.ID, err)
		}

		// Insert into streams
		streams := es.calculateStreams(e)
		for _, streamKey := range streams {
			_, err = qtx.CreateEventStream(ctx, sqlcdb.CreateEventStreamParams{
				StreamID:  streamKey,
				EventID:   eventID,
				Tick:      tickValue,
				CreatedAt: e.CreatedAt,
			})
			if err != nil {
				return fmt.Errorf("insert event %s into stream %s: %w", e.ID, streamKey, err)
			}
		}
	}

	if err := tx.Commit(); err != nil {
		return fmt.Errorf("commit transaction: %w", err)
	}

	// Notify subscribers asynchronously
	for _, e := range events {
		go es.notifySubscribers(e)
	}

	return nil
}

// GetEventByID retrieves a specific event by its ID.
func (es *SQLCEventStore) GetEventByID(ctx context.Context, id domain.EventID) (*event.GameEvent, error) {
	dbEvent, err := es.queries.GetEventByID(ctx, string(id))
	if err == sql.ErrNoRows {
		return nil, fmt.Errorf("event not found: %s", id)
	}
	if err != nil {
		return nil, fmt.Errorf("query event: %w", err)
	}

	return es.dbEventToGameEvent(dbEvent)
}

// GetEventStream retrieves events matching the given criteria.
func (es *SQLCEventStore) GetEventStream(ctx context.Context, criteria event.StreamCriteria) ([]*event.GameEvent, error) {
	limit := int64(1000)
	if criteria.Limit > 0 {
		limit = int64(criteria.Limit)
	}
	offset := int64(criteria.Offset)

	var dbEvents []*sqlcdb.Event
	var err error

	// Use the most specific query based on criteria
	switch {
	case criteria.WorldID != nil && criteria.ActorID != nil &&
		(criteria.FromTick != nil || criteria.ToTick != nil || len(criteria.EventTypes) > 0):
		// The actor-scoped windowed read: same discipline as the world window
		// below — types and ticks pushed down together, so LIMIT bites the
		// window, not the actor's whole history.
		var fromTick int64
		if criteria.FromTick != nil {
			fromTick = int64(*criteria.FromTick)
		}
		dbEvents, err = es.queries.ListEventsByActorTickWindow(ctx, sqlcdb.ListEventsByActorTickWindowParams{
			WorldID:   string(*criteria.WorldID),
			ActorID:   string(*criteria.ActorID),
			Types:     eventTypesJSON(criteria.EventTypes),
			FromTick:  fromTick,
			ToTick:    nullTick(criteria.ToTick),
			RowLimit:  limit,
			RowOffset: offset,
		})
	case criteria.WorldID != nil && criteria.ActorID != nil:
		worldID := string(*criteria.WorldID)
		actorID := string(*criteria.ActorID)
		dbEvents, err = es.queries.ListEventsByWorldAndActor(ctx, sqlcdb.ListEventsByWorldAndActorParams{
			WorldID: worldID,
			ActorID: actorID,
			Limit:   limit,
			Offset:  offset,
		})
	case criteria.WorldID != nil && criteria.LocationID != nil:
		worldID := string(*criteria.WorldID)
		locationID := string(*criteria.LocationID)
		dbEvents, err = es.queries.ListEventsByWorldAndLocation(ctx, sqlcdb.ListEventsByWorldAndLocationParams{
			WorldID:    worldID,
			LocationID: locationID,
			Limit:      limit,
			Offset:     offset,
		})
	case criteria.WorldID != nil && (criteria.FromTick != nil || criteria.ToTick != nil || len(criteria.EventTypes) > 0):
		// The windowed read: types and the tick window are pushed down to SQL
		// together. Splitting them across queries silently turns LIMIT into
		// "the oldest N rows of the whole log" — conversation history, weaver
		// signals and goal folds all read through here and all broke that way
		// once the log outgrew one LIMIT page.
		var fromTick int64
		if criteria.FromTick != nil {
			fromTick = int64(*criteria.FromTick)
		}
		dbEvents, err = es.queries.ListEventsByWorldTickWindow(ctx, sqlcdb.ListEventsByWorldTickWindowParams{
			WorldID:   string(*criteria.WorldID),
			Types:     eventTypesJSON(criteria.EventTypes),
			FromTick:  fromTick,
			ToTick:    nullTick(criteria.ToTick),
			RowLimit:  limit,
			RowOffset: offset,
		})
	case criteria.WorldID != nil && criteria.Visibility != nil:
		worldID := string(*criteria.WorldID)
		dbEvents, err = es.queries.ListEventsByWorldAndVisibility(ctx, sqlcdb.ListEventsByWorldAndVisibilityParams{
			WorldID:    worldID,
			Visibility: string(*criteria.Visibility),
			Limit:      limit,
			Offset:     offset,
		})
	case criteria.ParticipantID != nil:
		participantID := string(*criteria.ParticipantID)
		dbEvents, err = es.queries.ListEventsByParticipant(ctx, sqlcdb.ListEventsByParticipantParams{
			ActorID: participantID,
			Limit:   limit,
			Offset:  offset,
		})
	case criteria.WorldID != nil:
		worldID := string(*criteria.WorldID)
		dbEvents, err = es.queries.ListEventsByWorld(ctx, sqlcdb.ListEventsByWorldParams{
			WorldID: worldID,
			Limit:   limit,
			Offset:  offset,
		})
	case criteria.ActorID != nil:
		actorID := string(*criteria.ActorID)
		dbEvents, err = es.queries.ListEventsByActor(ctx, sqlcdb.ListEventsByActorParams{
			ActorID: actorID,
			Limit:   limit,
			Offset:  offset,
		})
	case criteria.LocationID != nil:
		locationID := string(*criteria.LocationID)
		dbEvents, err = es.queries.ListEventsByLocation(ctx, sqlcdb.ListEventsByLocationParams{
			LocationID: locationID,
			Limit:      limit,
			Offset:     offset,
		})
	case len(criteria.EventTypes) == 1:
		dbEvents, err = es.queries.ListEventsByType(ctx, sqlcdb.ListEventsByTypeParams{
			Type:   string(criteria.EventTypes[0]),
			Limit:  limit,
			Offset: offset,
		})
	default:
		// Fallback to listing all events (filtered in-memory)
		dbEvents, err = es.queries.ListAllEvents(ctx, sqlcdb.ListAllEventsParams{
			Limit:  limit,
			Offset: offset,
		})
	}

	if err != nil {
		return nil, fmt.Errorf("query events: %w", err)
	}

	// Convert to domain events and apply in-memory filters for criteria not in SQL.
	// A row that fails to decode (a payload shape from an older build that typed
	// decoding no longer accepts) is skipped with a warning rather than failing
	// the whole read: the event log is immutable, so one bad historical row must
	// degrade that one event — not poison every replay, perception and memory
	// read whose window covers it.
	events := make([]*event.GameEvent, 0, len(dbEvents))
	for _, dbEvent := range dbEvents {
		gameEvent, err := es.dbEventToGameEvent(dbEvent)
		if err != nil {
			es.logger.Warn("event store: skipping undecodable event row",
				zap.String("event_id", dbEvent.ID),
				zap.String("type", dbEvent.Type),
				zap.Error(err))
			continue
		}

		// Apply in-memory filtering for criteria not covered by SQL
		if criteria.Matches(gameEvent) {
			events = append(events, gameEvent)
		}
	}

	return events, nil
}

// GetEventConnections retrieves all causal connections for an event.
func (es *SQLCEventStore) GetEventConnections(ctx context.Context, id domain.EventID) ([]event.EventConnection, error) {
	eventID := string(id)
	dbConns, err := es.queries.GetEventConnections(ctx, sqlcdb.GetEventConnectionsParams{
		FromEventID: eventID,
		ToEventID:   eventID,
	})
	if err != nil {
		return nil, fmt.Errorf("query connections: %w", err)
	}

	connections := make([]event.EventConnection, 0, len(dbConns))
	for _, dbConn := range dbConns {
		conn, err := es.dbConnToEventConnection(dbConn)
		if err != nil {
			return nil, err
		}
		connections = append(connections, conn)
	}

	return connections, nil
}

// UpdateConnections updates the causal connections for an event.
func (es *SQLCEventStore) UpdateConnections(ctx context.Context, id domain.EventID, links []event.EventConnection) error {
	tx, err := es.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("begin transaction: %w", err)
	}
	defer tx.Rollback()

	qtx := es.queries.WithTx(tx)

	eventID := string(id)

	// Delete existing connections from this event
	if err := qtx.DeleteEventConnectionsFrom(ctx, eventID); err != nil {
		return fmt.Errorf("delete existing connections: %w", err)
	}

	// Insert new connections
	for _, link := range links {
		fromEventID := string(link.FromEventID)
		toEventID := string(link.ToEventID)

		_, err = qtx.CreateEventConnection(ctx, sqlcdb.CreateEventConnectionParams{
			FromEventID:    fromEventID,
			ToEventID:      toEventID,
			ConnectionType: string(link.Type),
			Weight:         link.Weight,
			Metadata:       connMetaToCol(link.Metadata),
			CreatedAt:      link.CreatedAt,
		})
		if err != nil {
			return fmt.Errorf("insert connection: %w", err)
		}
	}

	return tx.Commit()
}

// Subscribe subscribes to events matching the criteria.
func (es *SQLCEventStore) Subscribe(ctx context.Context, criteria event.StreamCriteria, handler event.EventHandler) (event.Unsubscribe, error) {
	streamKey := es.criteriaToKey(criteria)

	entry := subscriberEntry{
		criteria: criteria,
		handler:  handler,
	}

	es.mu.Lock()
	es.subscribers[streamKey] = append(es.subscribers[streamKey], entry)
	es.mu.Unlock()

	// Return unsubscribe function
	return func() {
		es.mu.Lock()
		defer es.mu.Unlock()

		entries := es.subscribers[streamKey]
		for i, e := range entries {
			if criteriaEqual(e.criteria, criteria) {
				es.subscribers[streamKey] = append(entries[:i], entries[i+1:]...)
				break
			}
		}
	}, nil
}

// Replay replays all events matching the criteria through the handler.
func (es *SQLCEventStore) Replay(ctx context.Context, criteria event.StreamCriteria, handler event.EventHandler) error {
	events, err := es.GetEventStream(ctx, criteria)
	if err != nil {
		return fmt.Errorf("get event stream: %w", err)
	}

	for _, e := range events {
		if err := handler(ctx, e); err != nil {
			return fmt.Errorf("handler error at event %s: %w", e.ID, err)
		}
	}

	return nil
}

// CreateSnapshot creates a snapshot of an aggregate's state.
func (es *SQLCEventStore) CreateSnapshot(ctx context.Context, aggregateID uuid.UUID, version int64, data []byte) error {
	_, err := es.queries.CreateSnapshot(ctx, sqlcdb.CreateSnapshotParams{
		AggregateID:   aggregateID.String(),
		AggregateType: "unknown", // Generic type for now
		Version:       version,
		Data:          data,
		CreatedAt:     time.Now(),
	})
	if err != nil {
		return fmt.Errorf("insert snapshot: %w", err)
	}
	return nil
}

// GetLatestSnapshot retrieves the most recent snapshot for an aggregate.
func (es *SQLCEventStore) GetLatestSnapshot(ctx context.Context, aggregateID uuid.UUID) (*event.Snapshot, error) {
	dbSnapshot, err := es.queries.GetLatestSnapshot(ctx, aggregateID.String())
	if err == sql.ErrNoRows {
		return nil, fmt.Errorf("snapshot not found for aggregate %s", aggregateID)
	}
	if err != nil {
		return nil, fmt.Errorf("query snapshot: %w", err)
	}

	aggID, _ := uuid.Parse(dbSnapshot.AggregateID)
	return &event.Snapshot{
		AggregateID:   aggID,
		AggregateType: dbSnapshot.AggregateType,
		Version:       dbSnapshot.Version,
		Data:          dbSnapshot.Data,
		CreatedAt:     dbSnapshot.CreatedAt,
	}, nil
}

// DeleteOldSnapshots deletes snapshots older than the given version.
func (es *SQLCEventStore) DeleteOldSnapshots(ctx context.Context, aggregateID uuid.UUID, keepVersion int64) error {
	err := es.queries.DeleteOldSnapshots(ctx, sqlcdb.DeleteOldSnapshotsParams{
		AggregateID: aggregateID.String(),
		Version:     keepVersion,
	})
	if err != nil {
		return fmt.Errorf("delete old snapshots: %w", err)
	}
	return nil
}

// CountEvents counts events matching the given criteria.
func (es *SQLCEventStore) CountEvents(ctx context.Context, criteria event.StreamCriteria) (int, error) {
	var count int64
	var err error

	// Use specific count query based on criteria
	switch {
	case criteria.WorldID != nil:
		worldID := string(*criteria.WorldID)
		count, err = es.queries.CountEventsByWorld(ctx, worldID)
	case criteria.ActorID != nil:
		actorID := string(*criteria.ActorID)
		count, err = es.queries.CountEventsByActor(ctx, actorID)
	case criteria.LocationID != nil:
		locationID := string(*criteria.LocationID)
		count, err = es.queries.CountEventsByLocation(ctx, locationID)
	default:
		// Fallback: count by fetching all matching events (less efficient)
		events, fetchErr := es.GetEventStream(ctx, criteria)
		if fetchErr != nil {
			return 0, fetchErr
		}
		return len(events), nil
	}

	if err != nil {
		return 0, fmt.Errorf("count events: %w", err)
	}

	return int(count), nil
}

// MaxTick returns the highest tick recorded for the world across the whole log
// (all incarnations share it), or 0 when the world has never ticked.
func (es *SQLCEventStore) MaxTick(ctx context.Context, worldID domain.WorldID) (domain.Tick, error) {
	maxTick, err := es.queries.MaxTickByWorld(ctx, string(worldID))
	if err != nil {
		return 0, fmt.Errorf("max tick by world: %w", err)
	}
	// COALESCE(MAX(tick), 0) comes back as an untyped interface from the SQLite
	// driver; normalise to int64.
	var tick int64
	switch v := maxTick.(type) {
	case int64:
		tick = v
	case float64:
		tick = int64(v)
	}
	return domain.Tick(tick), nil
}

// Helper methods

// calculateStreams calculates all stream keys for an event.
func (es *SQLCEventStore) calculateStreams(e *event.GameEvent) []string {
	streams := []string{
		"main",
		fmt.Sprintf("world:%s", e.WorldID),
		fmt.Sprintf("actor:%s", e.ActorID),
		fmt.Sprintf("location:%s", e.LocationID),
		fmt.Sprintf("type:%s", e.Type),
	}

	if e.TargetID != nil && !e.TargetID.IsZero() {
		streams = append(streams, fmt.Sprintf("actor:%s", *e.TargetID))
	}

	return streams
}

// criteriaToKey creates a unique key for subscription criteria.
func (es *SQLCEventStore) criteriaToKey(criteria event.StreamCriteria) string {
	if criteria.WorldID != nil {
		return fmt.Sprintf("world:%s", *criteria.WorldID)
	}
	if criteria.ActorID != nil {
		return fmt.Sprintf("actor:%s", *criteria.ActorID)
	}
	if criteria.LocationID != nil {
		return fmt.Sprintf("location:%s", *criteria.LocationID)
	}
	return "main"
}

// notifySubscribers notifies all matching subscribers about a new event.
func (es *SQLCEventStore) notifySubscribers(e *event.GameEvent) {
	es.mu.RLock()
	defer es.mu.RUnlock()

	for _, entries := range es.subscribers {
		for _, entry := range entries {
			if entry.criteria.Matches(e) {
				go func(h event.EventHandler) {
					ctx := context.Background()
					_ = h(ctx, e)
				}(entry.handler)
			}
		}
	}
}

// dbEventToGameEvent converts a database event to a domain event.
func (es *SQLCEventStore) dbEventToGameEvent(dbEvent *sqlcdb.Event) (*event.GameEvent, error) {
	e := &event.GameEvent{
		ID:         domain.EventID(dbEvent.ID),
		Type:       event.EventType(dbEvent.Type),
		ActorID:    domain.ActorID(dbEvent.ActorID),
		LocationID: domain.LocationID(dbEvent.LocationID),
		WorldID:    domain.WorldID(dbEvent.WorldID),
		Tick:       domain.Tick(dbEvent.Tick),
		Visibility: domain.Visibility(dbEvent.Visibility),
		CreatedAt:  dbEvent.CreatedAt,
	}

	// Handle nullable fields (TEXT columns -> *string)
	if dbEvent.TargetID != nil && *dbEvent.TargetID != "" {
		targetID := domain.ActorID(*dbEvent.TargetID)
		e.TargetID = &targetID
	}

	if dbEvent.CausedBy != nil && *dbEvent.CausedBy != "" {
		causedBy := domain.EventID(*dbEvent.CausedBy)
		e.CausedBy = &causedBy
	}

	// Metadata: a strictly-typed nullable column — present only when Valid (no manual unmarshal).
	if dbEvent.Metadata.Valid {
		m := dbEvent.Metadata.V
		e.Metadata = &m
	}

	// Unmarshal event data
	eventData, err := unmarshalEventData(e.Type, dbEvent.Data)
	if err != nil {
		return nil, fmt.Errorf("unmarshal event data: %w", err)
	}
	e.Data = eventData

	return e, nil
}

// dbConnToEventConnection converts a database connection to a domain connection.
func (es *SQLCEventStore) dbConnToEventConnection(dbConn *sqlcdb.EventConnection) (event.EventConnection, error) {
	conn := event.EventConnection{
		FromEventID: domain.EventID(dbConn.FromEventID),
		ToEventID:   domain.EventID(dbConn.ToEventID),
		Type:        event.ConnectionType(dbConn.ConnectionType),
		Weight:      dbConn.Weight,
		CreatedAt:   dbConn.CreatedAt,
	}

	if dbConn.Metadata.Valid {
		conn.Metadata = dbConn.Metadata.V
	}

	return conn, nil
}

// Helper functions for criteria conversion

// actorIDPtr / eventIDPtr turn an optional domain id into the *string the SQL
// boundary uses for nullable TEXT columns (nil = SQL NULL).
func actorIDPtr(id *domain.ActorID) *string {
	if id == nil || id.IsZero() {
		return nil
	}
	s := string(*id)
	return &s
}

func eventIDPtr(id *domain.EventID) *string {
	if id == nil || id.IsZero() {
		return nil
	}
	s := string(*id)
	return &s
}

// eventTypesJSON encodes the optional event-type filter as a JSON array string
// for json_each() in the windowed reads; nil means "no type filter".
func eventTypesJSON(types []event.EventType) interface{} {
	if len(types) == 0 {
		return nil
	}
	arr := make([]string, len(types))
	for i, t := range types {
		arr[i] = string(t)
	}
	data, err := json.Marshal(arr)
	if err != nil {
		return nil
	}
	return string(data)
}

// nullTick passes an optional upper tick bound as int64 or nil.
func nullTick(t *domain.Tick) interface{} {
	if t == nil {
		return nil
	}
	return int64(*t)
}

// eventMetadataToCol wraps optional coordination metadata for the strictly-typed events.metadata
// column: nil → SQL NULL (Valid=false), present → the typed payload. The column type
// (dbjson.Null[event.EventMetadata]) marshals it at the DB boundary, so no JSON bytes pass here.
func eventMetadataToCol(m *event.EventMetadata) dbcols.EventMetadata {
	if m == nil {
		return dbcols.EventMetadata{}
	}
	return dbcols.EventMetadata{V: *m, Valid: true}
}

// connMetaToCol wraps a connection's open metadata map for the nullable connection.metadata
// column: nil → SQL NULL, present → the map marshaled at the DB boundary.
func connMetaToCol(m map[string]any) dbjson.Null[map[string]any] {
	if m == nil {
		return dbjson.Null[map[string]any]{}
	}
	return dbjson.Null[map[string]any]{V: m, Valid: true}
}

// criteriaEqual checks if two criteria are functionally equivalent.
func criteriaEqual(a, b event.StreamCriteria) bool {
	// Compare WorldID
	if (a.WorldID == nil) != (b.WorldID == nil) {
		return false
	}
	if a.WorldID != nil && *a.WorldID != *b.WorldID {
		return false
	}

	// Compare ActorID
	if (a.ActorID == nil) != (b.ActorID == nil) {
		return false
	}
	if a.ActorID != nil && *a.ActorID != *b.ActorID {
		return false
	}

	// Compare LocationID
	if (a.LocationID == nil) != (b.LocationID == nil) {
		return false
	}
	if a.LocationID != nil && *a.LocationID != *b.LocationID {
		return false
	}

	// Compare ParticipantID
	if (a.ParticipantID == nil) != (b.ParticipantID == nil) {
		return false
	}
	if a.ParticipantID != nil && *a.ParticipantID != *b.ParticipantID {
		return false
	}

	return true
}

// unmarshalEventData reconstructs the concrete EventData for a stored event.
// It delegates to event.UnmarshalEventData (the single source of truth for
// event-data typing) so that consumers which type-switch on the concrete data —
// memory formation, narration — receive the real typed payload rather than a
// generic map that would silently degrade them.
func unmarshalEventData(eventType event.EventType, data []byte) (event.EventData, error) {
	if len(data) == 0 {
		data = []byte("{}")
	}
	return event.UnmarshalEventData(eventType, data)
}

