	"testing"

	dnddb "github.com/dnd-llm/dnd-llm/db"
	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/location"
	"github.com/dnd-llm/dnd-llm/internal/infrastructure/persistence"
	"github.com/dnd-llm/dnd-llm/internal/infrastructure/persistence/dbcols"
	"github.com/dnd-llm/dnd-llm/internal/infrastructure/persistence/sqlcdb"
)

// TestLocationStateRoundTrip is the A3-location guard: the typed location.LocationStateData must
// survive a full save → SQL JSON column → load round-trip with every cross-cutting axis intact
// (topology, access, prop fund, description, capacity), no axis degrading to []any.
func TestLocationStateRoundTrip(t *testing.T) {
	ctx := context.Background()
	database, err := dnddb.Open(ctx, filepath.Join(t.TempDir(), "loc.db"), 0)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer database.Close()
	if _, err := dnddb.Apply(ctx, database); err != nil {
		t.Fatalf("apply: %v", err)
	}
	// The state store parses location/world IDs as UUIDs, so use real ones.
	worldID := domain.NewWorldID()
	locID := domain.NewLocationID()
	// locations.world_id has an FK to worlds(id).
	if _, err := sqlcdb.New(database).CreateWorld(ctx, sqlcdb.CreateWorldParams{
		ID: worldID.String(), Name: "W", Status: "active",
		Parameters: dbcols.WorldGenParameters{}, StateData: dbcols.WorldState{},
	}); err != nil {
		t.Fatalf("create world: %v", err)
	}

	store := NewSQLCStateStore(database)
	want := &persistence.LocationState{
		ID:      locID,
		WorldID: worldID,
		Name:    "Караульня",
		Type:    "barracks",
		State: location.LocationStateData{
			Adjacency:      []location.Edge{{To: "square", Via: "door"}, {To: "street", Via: "window", Aliases: []string{"окно"}}},
			AccessNorm:     location.AccessRestricted,
			AccessActors:   []domain.ActorID{"capt-1"},
			AccessFactions: []string{"Стража"},
			Props:          []location.Prop{{Name: "Факел", Gist: "смоляной", Thermal: "горит"}},
			Furnished:      true,
			Description:    "крепкий бревенчатый сруб",
			Origin:         "weaver",
			Seats:          6,
			StandingRoom:   8,
			Aliases:        []string{"казарма", "караулка"},
		},
	}
	if err := store.SaveLocationState(ctx, want); err != nil {
		t.Fatalf("save: %v", err)
	}

	got, err := store.LoadLocationState(ctx, want.ID)
	if err != nil {
		t.Fatalf("load: %v", err)
	}

	gs := got.State
	if len(gs.Adjacency) != 2 || gs.Adjacency[0].To != "square" || gs.Adjacency[1].Via != "window" || len(gs.Adjacency[1].Aliases) != 1 {
		t.Errorf("adjacency round-trip lost: %#v", gs.Adjacency)
	}
	if gs.AccessNorm != location.AccessRestricted || len(gs.AccessActors) != 1 || gs.AccessActors[0] != "capt-1" || len(gs.AccessFactions) != 1 {
		t.Errorf("access axis: %+v", gs)
	}
	if len(gs.Props) != 1 || gs.Props[0].Name != "Факел" || gs.Props[0].Thermal != "горит" {
		t.Errorf("prop fund round-trip lost (no []any degradation expected): %#v", gs.Props)
	}
	if !gs.Furnished || gs.Description != want.State.Description || gs.Origin != "weaver" {
		t.Errorf("content axes: furnished=%v desc=%q origin=%q", gs.Furnished, gs.Description, gs.Origin)
	}
	if gs.Seats != 6 || gs.StandingRoom != 8 || len(gs.Aliases) != 2 {
		t.Errorf("capacity/aliases: seats=%d standing=%d aliases=%v", gs.Seats, gs.StandingRoom, gs.Aliases)
	}

	// The typed readers must read the loaded struct, not a stale map.
	if a := location.AccessFromState(gs); !a.Permits("capt-1", "") {
		t.Error("AccessFromState after load did not permit the allowlisted actor")
	}
	if edges := location.AdjacencyFromState(gs); len(edges) != 2 || !edges[0].Sanctioned() {
		t.Errorf("AdjacencyFromState after load: %#v", edges)
	}
}

package location

import (
	"slices"

	"github.com/dnd-llm/dnd-llm/internal/domain"
)

// AccessNorm is the closed social rule a place sets for WHO IT IS FOR — the
// place-side half of the reception field (the actor-side half being whether the
// allowlist names them). The core reads belonging from norm × allowlist and
// never from free text; an authored string outside this set reads as the open
// default upstream, so a typo degrades to "public", never panics.
//
// The norms form a ladder of closure: public/commercial admit any stranger
// (a passer-by, a customer); communal/private/restricted admit only those the
// allowlist names, and an unpermitted presence reads as intrusion (private) or
// trespass (restricted). See ai-docs/concept — reception field.
type AccessNorm string

const (
	// AccessPublic is open to anyone — a square, a street. A stranger is simply a
	// passer-by; the place sets no bar. The default for an unauthored place.
	AccessPublic AccessNorm = "public"
	// AccessCommercial is open to anyone WITH BUSINESS — a market, a shop, a
	// tavern. A stranger is a welcome customer.
	AccessCommercial AccessNorm = "commercial"
	// AccessCommunal belongs to a community — a guild hall, a temple. Members pass
	// freely; an outsider is tolerated but watched.
	AccessCommunal AccessNorm = "communal"
	// AccessPrivate is someone's own ground — a home, a workshop-dwelling. Only the
	// owner and invited guests belong; an uninvited stranger is an intrusion.
	AccessPrivate AccessNorm = "private"
	// AccessRestricted is barred to outsiders by authority — a guardhouse, a
	// captain's quarters. An unpermitted presence is a trespass.
	AccessRestricted AccessNorm = "restricted"
)

// Valid reports whether the norm is a known value. The loader uses it as the loud
// guard against an authored typo; the runtime reader treats anything invalid as
// the open default.
func (n AccessNorm) Valid() bool {
	switch n {
	case AccessPublic, AccessCommercial, AccessCommunal, AccessPrivate, AccessRestricted:
		return true
	default:
		return false
	}
}

// AdmitsStrangers reports whether the norm lets an unknown actor in WITHOUT a
// place on the allowlist — the open norms (public, commercial). The closed norms
// (communal, private, restricted) admit only those the allowlist names; an
// unknown/invalid norm reads as open. This is the place-side of "may I be here?".
func (n AccessNorm) AdmitsStrangers() bool {
	return n != AccessCommunal && n != AccessPrivate && n != AccessRestricted
}

// Access is a place's authored reception rule: the norm plus the allowlist of who
// is admitted regardless of the norm — by individual (AllowActors, resolved to
// actor IDs at load) or by faction (AllowFactions). Because the allowlist holds
// IDs and faction keys, the runtime belonging check compares closed values, never
// re-reads free-text names (the deterministic-core boundary).
type Access struct {
	Norm          AccessNorm
	AllowActors   []domain.ActorID
	AllowFactions []string
}

// Admits reports whether an actor (by ID and faction) is on this place's
// allowlist — named individually, or a member of an allowed faction. It answers
// only "is this actor explicitly permitted?"; the norm is consulted separately
// (see Permits). An empty faction never matches a faction entry.
func (a Access) Admits(id domain.ActorID, faction string) bool {
	if slices.Contains(a.AllowActors, id) {
		return true
	}
	return faction != "" && slices.Contains(a.AllowFactions, faction)
}

// Permits reports whether an actor may be here at all — the place-level
// permission axis of belonging: an open norm admits anyone, a closed norm admits
// only those the allowlist names. Perceiver-independent (it is about the place's
// rule, not who is watching), so it is shared across all co-located observers.
func (a Access) Permits(id domain.ActorID, faction string) bool {
	return a.Norm.AdmitsStrangers() || a.Admits(id, faction)
}

// DefaultAccess is the open rule for a place with no authored access — public,
// empty allowlist. Most places (streets, squares) need no authoring and fall here.
func DefaultAccess() Access {
	return Access{Norm: AccessPublic}
}

// AccessFromState reconstructs a location's reception rule from its State JSON —
// the single reader both the tick registry and the player turn share, so neither
// re-parses the keys. An absent/invalid norm reads as the open default (public),
// so an unauthored place is simply open; the allowlist is read back as ids/faction
// keys (the loader already resolved them, no name re-parsing).
func AccessFromState(s LocationStateData) Access {
	norm := s.AccessNorm
	if !norm.Valid() {
		norm = AccessPublic
	}
	return Access{Norm: norm, AllowActors: s.AccessActors, AllowFactions: s.AccessFactions}
}

