// fakeLocReader serves one location's stored state (where its prop fund lives).
type fakeLocReader struct{ state location.LocationStateData }

func (f *fakeLocReader) LoadLocationState(_ context.Context, loc domain.LocationID) (*persistence.LocationState, error) {
	return &persistence.LocationState{ID: loc, State: f.state}, nil
}

// TestLatentKindler_ReachesNextFlammableProp: the fire crystallizes and ignites
// the first flammable prop not already in play, skips the non-flammable one and
// the one already materialized here, and reports "no more fuel" once every
// flammable prop of the place is alight.
func TestLatentKindler_ReachesNextFlammableProp(t *testing.T) {
	world := domain.WorldID("w")
	loc := domain.NewLocationID()

	repo := newFakeRepo()
	cryst := NewCrystallizer(repo, nil, nil, nil, nil, nil)
	mut := NewMutator(repo, nil, nil)

	// The stool is already crystallized and present here (the present-entity tier
	// owns it) — the latent reach must skip it by name.
	stool := &entity.Entity{
		ID: domain.NewEntityID(), WorldID: world, Kind: entity.KindItem,
		Name: "Табурет", Gist: "грубый трёхногий табурет",
	}
	if err := repo.Save(context.Background(), stool); err != nil {
		t.Fatal(err)
	}
	_ = repo.AddLink(context.Background(), entity.Link{
		EntityID: stool.ID, LinkType: entity.LinkLocatedAt,
		SubjectType: entity.SubjectLocation, SubjectID: loc.String(),
	})

	fund := []Prop{
		// A tallow candle: flammable by its THERMAL axis (горит), and a fire SOURCE on
		// the orthogonal source axis — neither is the «fire» category any more.
		{Name: "Сальная свеча", Gist: "оплывшая свеча", Category: "misc", Source: entity.MeansFire, Thermal: entity.ThermalIgnites},
		{Name: "Кружка эля", Gist: "глиняная кружка", Category: "drink"},          // inert: not kindling
		{Name: "Табурет", Gist: "грубый табурет", Thermal: entity.ThermalIgnites}, // already present
	}
	locs := &fakeLocReader{state: location.LocationStateData{Props: fund}}
	kindler := NewLatentKindler(locs, repo, cryst, mut, nil)

	got, err := kindler.KindleNext(context.Background(), world, loc, 5)
	if err != nil {
		t.Fatalf("KindleNext: %v", err)
	}
	if got != "Сальная свеча" {
		t.Fatalf("fire must reach the first flammable, not-yet-present prop, got %q", got)
	}

	// The candle is now a materialized, BURNING entity.
	var candle *entity.Entity
	for _, e := range repo.entities {
		if e.Name == "Сальная свеча" {
			candle = e
		}
	}
	if candle == nil {
		t.Fatal("the candle must have crystallized into an entity")
	}
	if candle.StateText(entity.StateHazard) == "" {
		t.Errorf("the candle must be a STANDING fire (hazard set), state=%v", candle.State)
	}

	// A second reach finds no more latent fuel: the candle is now present (skipped),
	// the stool was already present, the ale never burns.
	got2, err := kindler.KindleNext(context.Background(), world, loc, 6)
	if err != nil {
		t.Fatalf("KindleNext (2nd): %v", err)
	}
	if got2 != "" {
		t.Errorf("the place is out of latent fuel — nothing more must catch, got %q", got2)
	}
}

