	infrallm "github.com/dnd-llm/dnd-llm/internal/infrastructure/llm"
)

// ── feasibility: the «can an ordinary body do this?» probe (ClassifyFeasibility) ──
// The grounding layer behind the project's named core limit — an open deed pipeline
// confabulates ANY claimed feat as success (live cycle-26: «взмываю в небо» → narrated
// flight + invented «магия твоей левитации»). Map the CLASS by PHYSICS:
//   обыденное      — any able body, no risk
//   сноровка       — a fit/trained body, with effort + real failure risk (→ a check)
//   сверхъестественное — beyond a normal body without magic (→ core gates on the gift)
// Plus the FALSE FRIENDS that decide the layer's worth: a magical-SOUNDING flavour word
// over a mundane act («взмахом руки гашу факел») must stay mundane, NOT supernatural.
// Held-out from feasibilityPrompt (which names DIFFERENT feats of each class).
type feasCase struct {
	utterance string
	want      string
}

var feasCases = []feasCase{
	// обыденное — an able body, no effort/risk
	{"подбираю с пола оброненную монету", extraction.FeasMundane},
	{"затворяю ставню от ветра", extraction.FeasMundane},
	{"грею озябшие ладони у очага", extraction.FeasMundane},
	{"киваю торговцу в знак согласия", extraction.FeasMundane},
	// сноровка — a fit/trained body, effort + failure risk
	{"перепрыгиваю через широкий ров", extraction.FeasAthletic},
	{"взбираюсь по обледенелой стене амбара", extraction.FeasAthletic},
	{"пробегаю по скользкому бревну над обрывом", extraction.FeasAthletic},
	{"вышибаю плечом запертую дверь", extraction.FeasAthletic},
	// сверхъестественное — beyond a normal body without magic
	{"взмываю высоко в небо и парю над городом", extraction.FeasSupernatural},
	{"поднимаю воду из реки силой мысли", extraction.FeasSupernatural},
	{"обращаюсь в огромного дракона", extraction.FeasSupernatural},
	{"поворачиваю время вспять одним желанием", extraction.FeasSupernatural},
	// Классификатор ВЕРНО метит и те сверхъест. деяния, что в рантайме роутятся в НЕ-freeform хэндлеры
	// (телепорт→move, невидимость→regulation) и потому ОБХОДЯТ doFreeform-гейт: дыра в РОУТИНГЕ гейта,
	// НЕ в классификаторе (см. TODO non-freeform-routing; полное закрытие = central-gate). Held-out.
	{"переношусь в мгновение ока к городским воротам", extraction.FeasSupernatural}, // телепорт
	{"делаюсь невидимым для всех глаз", extraction.FeasSupernatural},                // невидимость
	// FALSE FRIENDS — magical-SOUNDING flavour over a MUNDANE/athletic act → NOT supernatural.
	// These decide the layer's worth: it must judge PHYSICS, not the «взмах руки»/«сила воли» wording.
	{"взмахом руки сбиваю пламя со свечи", extraction.FeasMundane},       // «взмахом руки» but just snuffs a candle
	{"собрав всю волю, вскидываю на плечи тяжёлый мешок", extraction.FeasAthletic}, // «всю волю» but a mere heavy lift
	{"поджигаю хворост поднесённым факелом", extraction.FeasMundane},     // fire, but lit by a torch — not by will
	// EDGE — the axis's OPERATIVE boundary (clarified by probing): сверхъестественное means «no check
	// could EVER succeed» (true magic, or a feat NO body survives) → the gate. «Extreme-but-conceivable»
	// athletic (leap a chasm, lift a great weight) stays сноровка — a desperate CHECK fails it via
	// position, same no-confab outcome, so the within-physical gradient need not be split here. Probed:
	// 4B leans сноровка for «leap a house / hoist a cart» (extreme-athletic) and only flags the
	// truly-impossible as сверхъестественное — which is exactly the line the gate needs (catch MIRACLES,
	// let the check handle absurd-but-physical).
	{"просиживаю под водой без воздуха целый час", extraction.FeasSupernatural}, // no body survives → gate
	// EDGE — elaborate but MUNDANE/athletic (skill ≠ magic): a learned craft is not supernatural.
	{"высекаю огонь кремнём и трутом", extraction.FeasMundane},  // в мире без спичек — рутинный навык, не магия
	{"вскрываю висячий замок отмычкой", extraction.FeasAthletic}, // a thief's craft, mundane skill
}

func runFeasibility(ctx context.Context, p infrallm.SchemaCompleter, samples int) {
	pass, total := 0, 0
	for i, c := range feasCases {
		fmt.Printf("\n%s\n#%-2d хотим [%s]\n   «%s»\n%s\n",
			strings.Repeat("═", 90), i+1, c.want, c.utterance, strings.Repeat("─", 90))
		for s := 1; s <= samples; s++ {
			total++
			f, err := extraction.ClassifyFeasibility(ctx, p, c.utterance)
			if err != nil {
				fmt.Printf("  ⃟%d ✗ %v\n", s, err)
				continue
			}
			mark := "✓"
			if f.Class != c.want {
				mark = "✗"
			} else {
				pass++
			}
			fmt.Printf("  ⃟%d  [%s]  %s\n", s, f.Class, mark)
		}
	}
	fmt.Printf("\n%s\n  feasibility: %d ✓ / %d  (%.0f%%)\n", strings.Repeat("═", 90), pass, total, 100*float64(pass)/float64(total))
}

