package knowledge

import (
	"context"
	"strings"
	"testing"

	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
	domllm "github.com/dnd-llm/dnd-llm/internal/domain/llm"
	"github.com/dnd-llm/dnd-llm/internal/infrastructure/search"
	"github.com/google/uuid"
)

// fakeRepo is an in-memory entity.Repository for pack-assembly tests.
type fakeRepo struct {
	entities map[domain.EntityID]*entity.Entity
	links    []entity.Link
}

func newFakeRepo() *fakeRepo {
	return &fakeRepo{entities: map[domain.EntityID]*entity.Entity{}}
}

func (f *fakeRepo) Save(_ context.Context, e *entity.Entity) error {
	f.entities[e.ID] = e
	return nil
}

func (f *fakeRepo) FindByID(_ context.Context, id domain.EntityID) (*entity.Entity, error) {
	e, ok := f.entities[id]
	if !ok {
		return nil, entity.ErrNotFound
	}
	return e, nil
}

func (f *fakeRepo) ListByWorld(_ context.Context, worldID domain.WorldID) ([]*entity.Entity, error) {
	var out []*entity.Entity
	for _, e := range f.entities {
		if e.WorldID == worldID {
			out = append(out, e)
		}
	}
	return out, nil
}

func (f *fakeRepo) ListKnownBy(_ context.Context, worldID domain.WorldID, actorID domain.ActorID, locID domain.LocationID) ([]*entity.Entity, error) {
	seen := map[domain.EntityID]bool{}
	var out []*entity.Entity
	for _, l := range f.links {
		var hit bool
		switch {
		case l.SubjectType == entity.SubjectActor && l.SubjectID == actorID.String() &&
			(l.LinkType == entity.LinkKnows || l.LinkType == entity.LinkOwner):
			hit = true
		case l.SubjectType == entity.SubjectLocation && l.SubjectID == locID.String() && l.LinkType == entity.LinkLocatedAt:
			hit = true
		case l.SubjectType == entity.SubjectWorld && l.SubjectID == worldID.String() && l.LinkType == entity.LinkKnows:
			hit = true
		}
		if hit && !seen[l.EntityID] {
			seen[l.EntityID] = true
			if e, ok := f.entities[l.EntityID]; ok {
				out = append(out, e)
			}
		}
	}
	return out, nil
}

func (f *fakeRepo) ListPresentAt(_ context.Context, _ domain.WorldID, locID domain.LocationID, holders []domain.ActorID) ([]*entity.Entity, error) {
	holderSet := map[string]bool{}
	for _, h := range holders {
		holderSet[h.String()] = true
	}
	seen := map[domain.EntityID]bool{}
	var out []*entity.Entity
	for _, l := range f.links {
		var hit bool
		switch {
		case l.SubjectType == entity.SubjectLocation && l.SubjectID == locID.String() && l.LinkType == entity.LinkLocatedAt:
			hit = true
		case l.SubjectType == entity.SubjectActor && holderSet[l.SubjectID] && l.LinkType == entity.LinkOwner:
			hit = true
		}
		if hit && !seen[l.EntityID] {
			seen[l.EntityID] = true
			if e, ok := f.entities[l.EntityID]; ok {
				out = append(out, e)
			}
		}
	}
	return out, nil
}

func (f *fakeRepo) HazardLocations(_ context.Context, _ domain.WorldID) ([]domain.LocationID, error) {
	return nil, nil
}

func (f *fakeRepo) ListWaresOwnedPresent(_ context.Context, _ domain.WorldID, ownerID domain.ActorID, locID domain.LocationID) ([]*entity.Entity, error) {
	owned := map[domain.EntityID]bool{}
	pinned := map[domain.EntityID]string{}
	for _, l := range f.links {
		if l.SubjectType == entity.SubjectActor && l.LinkType == entity.LinkOwner && l.SubjectID == ownerID.String() {
			owned[l.EntityID] = true
		}
		if l.SubjectType == entity.SubjectLocation && l.LinkType == entity.LinkLocatedAt {
			pinned[l.EntityID] = l.SubjectID
		}
	}
	var out []*entity.Entity
	for id := range owned {
		e, ok := f.entities[id]
		if !ok || e.Value <= 0 {
			continue
		}
		if pin, has := pinned[id]; has && pin != locID.String() {
			continue
		}
		out = append(out, e)
	}
	return out, nil
}

func (f *fakeRepo) ListOwnedPresentAt(_ context.Context, _ domain.WorldID, ownerID domain.ActorID, locID domain.LocationID) ([]*entity.Entity, error) {
	owned := map[domain.EntityID]bool{}
	pinned := map[domain.EntityID]string{}
	for _, l := range f.links {
		if l.SubjectType == entity.SubjectActor && l.LinkType == entity.LinkOwner && l.SubjectID == ownerID.String() {
			owned[l.EntityID] = true
		}
		if l.SubjectType == entity.SubjectLocation && l.LinkType == entity.LinkLocatedAt {
			pinned[l.EntityID] = l.SubjectID
		}
	}
	var out []*entity.Entity
	for id := range owned {
		e, ok := f.entities[id]
		if !ok {
			continue
		}
		if pin, has := pinned[id]; has && pin != locID.String() {
			continue
		}
		out = append(out, e)
	}
	return out, nil
}

func (f *fakeRepo) ListOwnedBy(_ context.Context, _ domain.WorldID, ownerID domain.ActorID) ([]*entity.Entity, error) {
	var out []*entity.Entity
	for _, l := range f.links {
		if l.SubjectType == entity.SubjectActor && l.LinkType == entity.LinkOwner && l.SubjectID == ownerID.String() {
			if e, ok := f.entities[l.EntityID]; ok {
				out = append(out, e)
			}
		}
	}
	return out, nil
}

func (f *fakeRepo) ListLinked(_ context.Context, id domain.EntityID, lt entity.LinkType) ([]*entity.Entity, error) {
	var out []*entity.Entity
	for _, l := range f.links {
		if l.LinkType != lt {
			continue
		}
		if l.SubjectType == entity.SubjectEntity && l.SubjectID == id.String() {
			if e, ok := f.entities[l.EntityID]; ok {
				out = append(out, e)
			}
		}
		if l.EntityID == id && l.SubjectType == entity.SubjectEntity {
			if e, ok := f.entities[domain.EntityID(l.SubjectID)]; ok {
				out = append(out, e)
			}
		}
	}
	return out, nil
}

func (f *fakeRepo) AddLink(_ context.Context, l entity.Link) error {
	f.links = append(f.links, l)
	return nil
}

func (f *fakeRepo) ReplaceSubjectLink(ctx context.Context, l entity.Link) error {
	if err := f.RemoveSubjectLinks(ctx, l.EntityID, l.LinkType); err != nil {
		return err
	}
	return f.AddLink(ctx, l)
}

func (f *fakeRepo) RemoveSubjectLinks(_ context.Context, id domain.EntityID, lt entity.LinkType) error {
	kept := f.links[:0]
	for _, l := range f.links {
		if l.EntityID == id && l.LinkType == lt {
			continue
		}
		kept = append(kept, l)
	}
	f.links = kept
	return nil
}

func (f *fakeRepo) ListLinks(_ context.Context, id domain.EntityID) ([]entity.Link, error) {
	var out []entity.Link
	for _, l := range f.links {
		if l.EntityID == id {
			out = append(out, l)
		}
	}
	return out, nil
}

func (f *fakeRepo) DeleteByWorld(_ context.Context, worldID domain.WorldID) error {
	for id, e := range f.entities {
		if e.WorldID == worldID {
			delete(f.entities, id)
		}
	}
	return nil
}

// testWorld is a fixed scene: the baker knows her bread (which mentions the
// flour), the location holds the ledger, the river is town knowledge.
type testWorld struct {
	repo     *fakeRepo
	searcher *search.EntitySearcher
	worldID  domain.WorldID
	actorID  domain.ActorID
	locID    domain.LocationID
	bread    *entity.Entity
	flour    *entity.Entity
	river    *entity.Entity
	ledger   *entity.Entity
}

func buildTestWorld(t *testing.T) *testWorld {
	t.Helper()
	w := &testWorld{
		repo:    newFakeRepo(),
		worldID: domain.WorldID(uuid.NewString()),
		actorID: domain.ActorID(uuid.NewString()),
		locID:   domain.LocationID(uuid.NewString()),
	}

	mk := func(name, gist, backstory string, kind entity.Kind) *entity.Entity {
		e := &entity.Entity{
			ID: domain.EntityID(uuid.NewString()), WorldID: w.worldID,
			Kind: kind, Name: name, Gist: gist, Backstory: backstory,
			Lifecycle: entity.LifecycleStub, Origin: entity.OriginFixture,
		}
		if backstory != "" {
			e.Lifecycle = entity.LifecycleMaterialized
		}
		w.repo.entities[e.ID] = e
		return e
	}

	w.bread = mk("Хлеб из ночной муки", "Хлеб, который Анна печёт из ночной муки.", "Анна замешивает тесто только на муке ночного помола.", entity.KindItem)
	w.bread.Aliases = []string{"хлеб"}
	w.flour = mk("Ночная мука", "Мука, смолотая в тёмные часы.", "", entity.KindSubstance)
	w.river = mk("Тихводь", "Река, что течёт лишь в темноте.", "", entity.KindFeature)
	w.ledger = mk("Долговая книга Мирры", "Книга долгов всего города.", "", entity.KindItem)

	w.repo.links = []entity.Link{
		{EntityID: w.bread.ID, LinkType: entity.LinkOwner, SubjectType: entity.SubjectActor, SubjectID: w.actorID.String()},
		{EntityID: w.flour.ID, LinkType: entity.LinkKnows, SubjectType: entity.SubjectActor, SubjectID: w.actorID.String()},
		{EntityID: w.ledger.ID, LinkType: entity.LinkLocatedAt, SubjectType: entity.SubjectLocation, SubjectID: w.locID.String()},
		{EntityID: w.river.ID, LinkType: entity.LinkKnows, SubjectType: entity.SubjectWorld, SubjectID: w.worldID.String()},
		// «хлеб упоминает муку»: subject = bread, entity = flour.
		{EntityID: w.flour.ID, LinkType: entity.LinkMentions, SubjectType: entity.SubjectEntity, SubjectID: w.bread.ID.String()},
	}

	w.searcher = search.NewEntitySearcher(nil, search.DefaultEntitySearcherConfig())
	var searchables []domllm.SearchableEntity
	for _, e := range w.repo.entities {
		searchables = append(searchables, searchableFromEntity(e))
	}
	w.searcher.UpdateLocalCache(w.worldID.String(), searchables)
	return w
}

func TestWhoKnows(t *testing.T) {
	w := buildTestWorld(t)
	svc := NewService(w.repo, w.searcher, nil, nil)
	stranger := domain.ActorID(uuid.NewString())
	sc := Scope{WorldID: w.worldID, ActorID: w.actorID, Location: w.locID}

	// Анна владеет хлебом — вопрос о хлебе выделяет её из двоих.
	got := svc.WhoKnows(context.Background(), sc, "что за хлеб из ночной муки", []domain.ActorID{stranger, w.actorID})
	if len(got) != 1 || got[0] != w.actorID {
		t.Errorf("bread question should single out the baker, got %v", got)
	}

	// Река — общегородское знание (knows|world): личного преимущества нет.
	if got := svc.WhoKnows(context.Background(), sc, "расскажи про Тихводь", []domain.ActorID{stranger, w.actorID}); len(got) != 0 {
		t.Errorf("town knowledge must single out nobody, got %v", got)
	}

	// Пустая тема — нет сигнала.
	if got := svc.WhoKnows(context.Background(), sc, "", []domain.ActorID{w.actorID}); got != nil {
		t.Errorf("empty topic must yield nil, got %v", got)
	}
}

func TestBuildPack_Tier0Only(t *testing.T) {
	w := buildTestWorld(t)
	svc := NewService(w.repo, w.searcher, nil, nil)

	pack, err := svc.BuildPack(context.Background(), Scope{WorldID: w.worldID, ActorID: w.actorID, Location: w.locID}, "", Options{})
	if err != nil {
		t.Fatalf("BuildPack: %v", err)
	}
	if len(pack.Focus) != 0 {
		t.Errorf("no topic should mean no focus, got %d", len(pack.Focus))
	}
	if len(pack.Known) != 4 {
		t.Errorf("scope should hold 4 entities (own bread+flour, located ledger, town river), got %d", len(pack.Known))
	}
}

