func TestRenderFacts(t *testing.T) {
	p := &Pack{
		Focus: []Detail{{Name: "Тихводь", Gist: "Река.", Kind: "feature", Backstory: "Течёт ночью.", Condition: "вскрыта багром"}},
		Known: []Fact{{Name: "Колокол", Gist: "Звонит."}, {Name: "Уговор с рекой", Gist: "Предание.", Kind: "lore"}},
	}
	facts := RenderFacts(p)
	if len(facts) != 3 {
		t.Fatalf("want 3 fact lines, got %d", len(facts))
	}
	if !strings.Contains(facts[0], "Течёт ночью") || !strings.Contains(facts[0], "вскрыта багром") {
		t.Errorf("focus line lost backstory/condition: %q", facts[0])
	}
	// The kind rides into the line — a lore fact must be readable as knowledge,
	// not as a physical prop.
	if !strings.Contains(facts[0], "(примечательный объект)") {
		t.Errorf("focus line lost its kind: %q", facts[0])
	}
	if !strings.Contains(facts[2], "(предание)") {
		t.Errorf("lore fact lost its kind: %q", facts[2])
	}
	// A kindless fact renders exactly as before.
	if strings.Contains(facts[1], "(") {
		t.Errorf("kindless fact must not grow a label: %q", facts[1])
	}
	if RenderFacts(nil) != nil {
		t.Error("nil pack must render nothing")
	}
}

func TestLexicalFocusMatchesCaseEndings(t *testing.T) {
	scope := map[domain.EntityID]*entity.Entity{
		"e1": {ID: "e1", Name: "Ночная мука"},
		"e2": {ID: "e2", Name: "Хлеб из ночной муки"},
		"e3": {ID: "e3", Name: "Старый Колокол"},
		"e4": {ID: "e4", Name: "Тихводь", Aliases: []string{"река"}},
	}

	cases := []struct {
		topic string
		want  []string // имена в порядке ранга; пусто = ничего
	}{
		{"откуда берётся ночная мука", []string{"Ночная мука"}},
		{"что за хлеб из ночной муки", []string{"Хлеб из ночной муки", "Ночная мука"}},
		{"расскажи про реку", []string{"Тихводь"}},
		{"что слышно про старый колокол", []string{"Старый Колокол"}},
		{"как пройти к причалам", nil},
	}
	for _, c := range cases {
		got := LexicalFocus(c.topic, scope)
		var names []string
		for _, e := range got {
			names = append(names, e.Name)
		}
		if len(names) != len(c.want) {
			t.Errorf("topic %q: want %v, got %v", c.topic, c.want, names)
			continue
		}
		for i := range names {
			if names[i] != c.want[i] {
				t.Errorf("topic %q: want %v, got %v", c.topic, c.want, names)
				break
			}
		}
	}
}

