// Unconventional-route resolution: a player who NAMES a window/plank takes a deliberate,
// checked crossing the default walk ignores. climbBaseDice/Difficulty set the climb's odds;
// climbFallHarm is the knock a botched climb costs; unconventionalRoutePrefix tags an edge
// candidate so a grounded move is recognised as "through the window", not "to a venue".
const (
	climbBaseDice             = 2
	climbDifficulty           = 1
	climbFallHarm             = 1
	unconventionalRoutePrefix = "vroute:"
)

// actionOutcome is what executing one atomic action produced. Exactly one of
// question/narrative carries the player-facing text; reply rides along for
// speech actions.
//
// Text composition discipline (the load-bearing rule of the Russian pipeline):
// Go composes player-facing text only from closed sets (lexicon phrases,
// authored fixture descriptions) or normalized forms (the parser's infinitive
// contract). Anything needing real grammar around free text goes through the
// narrator LLM — prompts tolerate any wording, the model writes the final
// grammatical text.
type actionOutcome struct {
	narrative string
	question  string
	reply     *NPCLine
	// shop is the merchant's window a browse renders (engine prices); it
	// rides to the UI as a structured panel alongside the text.
	shop *ShopView
	// startedJourney marks a move that set the player WALKING toward a venue (rather than
	// teleporting). The turn loop then auto-walks the route over ticks and narrates where they
	// ended — set even for a one-hop journey so the arrival is always described.
	startedJourney bool
	// supersededByRemedy marks a freeform narrative that the deterministic core ruled IMPOTENT
	// («нет средства») — which a quest REMEDY overrides: if the weaver lands the authored fix for
	// this same deed this turn, its prose is the real outcome and this contradicting «не выходит»
	// narration is dropped (else the feed reads «льда здесь нет … и всё же река отпускает причалы»).
	supersededByRemedy bool
}

// preemptsAsViolence reports whether a deed resolves on the violence path BEFORE the coarse action
// enum is consulted — a grapple or disarm phrased as a plain deed («хватаю и валю», «выбиваю клинок»)
// is violence whatever the action guess flattened it to. Two exclusions: speech is never a blow, and
// a COVERT TAKE (sneaking a thing away — «краду саблю») is a stealth take, not an open blow, even of a
// weapon the violence layer read as a "disarm" — covert acquisition owns the take path (a stealth
// contest that lifts the thing), not overt violence (which knocks it away and rings a hue and cry).
// A covert STRIKE is not a take, so it still resolves here as violence.
func preemptsAsViolence(action extraction.ParsedPlayerAction) bool {
	if action.Action == "talk" || action.Action == "say" {
		return false
	}
	if action.Action == "take" && action.Covert {
		return false
	}
	// A perceived feeling-sway (break up a brawl, settle panic, hearten the cowed) is not a blow —
	// even when phrased with physical force the violence layer reads as a grapple or restrain. The
	// social classifier returns none for genuine harm/subdue (bench-verified), so a real assault
	// still preempts here; only a pacification yields, routing to its own handler downstream.
	if (extraction.SocialMove{Mode: action.SocialMode}).Swaying() {
		return false
	}
	return (extraction.Violence{Mode: action.ViolenceMode}).Attempting()
}

// executeAction validates and executes one atomic action against the current
// turn context.
func (s *TurnService) executeAction(
	ctx context.Context,
	tc *turnContext,
	action extraction.ParsedPlayerAction,
) (*actionOutcome, error) {
	// A deed BEYOND the actor's power — a supernatural feat without the gift — cannot land WHATEVER
	// coarse enum or mode routed it (телепорт→move, невидимость→social, «поражаю молнией»→violence).
	// The feasibility-PREEMPT grounds fabrication at the deed CLASS, ahead of every handler and
	// mode-preempt: the core commits a vain attempt, the narrator renders it, never an invented power.
	// Speech/wait are never feats (the sensor skipped them → Feasibility empty → not gated); fail-open
	// if the sensor erred. canWorkMiracles is the single extension point for an authored gift.
	if action.Feasibility == extraction.FeasSupernatural && !canWorkMiracles(tc.player) {
		return s.narrateBeyondMortalPower(ctx, tc, feasibilityDeed(action, tc.input))
	}
	// A deed carrying a VIOLENCE mode is resolved by the violence path however the coarse action
	// enum read it: a grapple or a disarm phrased as a plain deed («хватаю и валю», «выбиваю
	// клинок») is violence, not freeform or a take. The mode — perceived over the WHOLE reply —
	// is the authority over the framing the action guess flattened (mirror of influence routing).
	// Speech is never a physical blow, so it is excluded and resolves its own (influence) path.
	if preemptsAsViolence(action) {
		return s.doAttack(ctx, tc, action)
	}
	if action.Action != "talk" && action.Action != "say" {
		// The benevolent twin: a deed that TENDS a body (first aid) mends the wounded, however the
		// coarse action enum read it («перевязываю раненого» reads as a freeform deed). The aid mode
		// — perceived over the whole reply — is the authority.
		if (extraction.Aid{Mode: action.AidMode}).Tending() {
			return s.doTend(ctx, tc, action)
		}
		// The covert twin: a deed that DIVERTS onlookers' attention (a thrown stone, a toppled
		// barrel, a commotion) routes to the distract handler however the coarse enum read it. The
		// distract mode — perceived over the whole reply — is the authority.
		if (extraction.Distraction{Mode: action.DistractMode}).Diverting() {
			return s.doDistract(ctx, tc, action)
		}
		// The feeling-swaying sibling: a deed that SWAYS those present toward calm or courage
		// (break up a brawl, settle panic, hearten the cowed) routes to the social-move handler
		// however the coarse enum read it. The sway mode — perceived over the whole reply — is the
		// authority; a genuine blow already preempted above, so this never declaws an attack.
		if (extraction.SocialMove{Mode: action.SocialMode}).Swaying() {
			return s.doSocialMove(ctx, tc, action)
		}
	}

	return s.dispatchByEnum(ctx, tc, action)
}

// dispatchByEnum routes a deed by its coarse-enum kind alone — the switch WITHOUT the mode
// preempts. It is reached normally (no person-directed mode fired) and as the FALL-THROUGH when a
// perceived person-directed mode (violence/aid) turned out to have no co-located patient: the layer
// read force or a gesture on the WORLD (ломаю дверь, скалываю лёд, выволакиваю груз) as a blow or
// first-aid, but with no being present it is a deed on a thing, and the consequence sensor (other →
// doFreeform) is its home. No preempt re-runs here, so a fall-through cannot loop; the enum's own
// «attack» case still routes to doAttack, which dead-ends honestly only when the player EXPLICITLY
// attacked no-one.
func (s *TurnService) dispatchByEnum(ctx context.Context, tc *turnContext, action extraction.ParsedPlayerAction) (*actionOutcome, error) {
	switch action.Action {
	case "move":
		return s.doMove(ctx, tc, action)
	case "talk", "say":
		return s.doTalk(ctx, tc, action)
	case "observe":
		return s.doObserve(ctx, tc, action)
	case "wait":
		return &actionOutcome{narrative: "Ты выжидаешь, наблюдая за жизнью вокруг."}, nil
	case "take":
		return s.doTake(ctx, tc, action)
	case "give":
		return s.doGive(ctx, tc, action)
	case "attack":
		return s.doAttack(ctx, tc, action)
	case "browse":
		return s.doBrowse(ctx, tc, action)
	case "consume":
		return s.doConsume(ctx, tc, action)
	case "other":
		return s.doFreeform(ctx, tc, action)
	default:
		// The grammar makes this impossible; a hit means the enum and this
		// switch have drifted apart.
		return nil, fmt.Errorf("unknown player action type %q", action.Action)
	}
}

// ============================================================================
// move
// ============================================================================

func (s *TurnService) doMove(ctx context.Context, tc *turnContext, action extraction.ParsedPlayerAction) (*actionOutcome, error) {
	here := tc.player.GetCurrentLocation()

	if strings.TrimSpace(action.Where) == "" {
		return &actionOutcome{question: fmt.Sprintf("Куда именно? Отсюда можно добраться: %s.", s.locationListing(tc, here))}, nil
	}

	res, err := s.resolver.Resolve(ctx, tc.worldID, action.Where, extraction.MentionWhere, s.moveCandidates(tc))
	if err != nil {
		return nil, err
	}
	if !res.Grounded {
		// Not a venue — the player may head toward a PERSON («иду к кузнецу»): a person is not a
		// place, but the destination is wherever they ARE. An actor ELSEWHERE names their venue (walk
		// there); one already HERE is a within-place approach the consequence sensor narrates (no
		// journey, no «такого места не знают» dead-end). Only a reference grounding to neither place
		// nor person falls to the honest question.
		if target := s.groundMoveActor(ctx, tc, action.Where); target != nil {
			if dest := target.GetCurrentLocation(); dest != here {
				if conv := s.activeConversation(ctx, tc); conv != nil {
					s.endConversation(ctx, tc, conv)
				}
				s.setPlayerJourney(tc, dest)
				return &actionOutcome{startedJourney: true}, nil
			}
			return s.doFreeform(ctx, tc, action) // already here — the freeform sensor narrates the approach
		}
		return &actionOutcome{question: fmt.Sprintf("Такого места в городе не знают. Можно пойти в: %s.", s.locationListing(tc, here))}, nil
	}

	// A NAMED unconventional crossing (a window, a plank) is a deliberate, CHECKED route the
	// default walk never takes — resolved apart from the venue journey.
	if edge, ok := s.matchUnconventional(tc, res.ID); ok {
		if conv := s.activeConversation(ctx, tc); conv != nil {
			s.endConversation(ctx, tc, conv)
		}
		return s.climbThrough(ctx, tc, edge)
	}

	to := domain.LocationID(res.ID)
	if to == here {
		return &actionOutcome{narrative: fmt.Sprintf("Ты уже здесь — %s.", res.Name)}, nil
	}

	// Уход обрывает разговор: собеседники остаются в прежнем месте. Закрывается
	// ДО движения, чтобы событие конца беседы легло в её локацию.
	if conv := s.activeConversation(ctx, tc); conv != nil {
		s.endConversation(ctx, tc, conv)
	}

	// Отправляемся в ПУТЬ, а не телепортируемся: ставим reach-цель в общий трекер. Игрок
	// шагает по графу венью по одному за тик (advanceJourneys), пока мир тикает — путь
	// проходится несколькими тиками подряд (ProcessTurn ведёт авто-ход), наррируется в конце
	// хода; событие в пути прерывает. Соседняя венью достигается за один шаг.
	s.setPlayerJourney(tc, to)
	return &actionOutcome{startedJourney: true}, nil
}

// groundMoveActor grounds a non-venue move target against the people the player can mean — «иду к
// кузнецу»: the smith is a person, not a place, and the destination is wherever they stand. Returns
// the grounded actor (co-located or elsewhere), or nil when the reference names no one. Reuses the
// turn's cached experiential field, so it adds no extra scope query.
func (s *TurnService) groundMoveActor(ctx context.Context, tc *turnContext, ref string) *actor.Actor {
	field := s.experientialField(ctx, tc)
	res, err := s.resolver.Resolve(ctx, tc.worldID, ref, extraction.MentionWho, s.actorCandidates(field.actors))
	if err != nil || !res.Grounded {
		return nil
	}
	id := domain.ActorID(res.ID)
	for _, a := range field.actors {
		if a.ID == id {
			return a
		}
	}
	return tc.actorByID(id)
}

// moveCandidates are the grounding targets for a move: every venue PLUS the unconventional
// crossings out of the player's current spot (a window, a plank), each offered under the words
// it is named by. Adding the edges here lets the EXISTING grounding perception classify "лезу в
// окно" as a route — no separate classifier, the same closed-candidate grounding the rest uses.
func (s *TurnService) moveCandidates(tc *turnContext) []extraction.Candidate {
	cands := s.locationCandidates(tc)
	for _, e := range s.unconventionalRoutes(tc) {
		cands = append(cands, extraction.Candidate{
			ID:    unconventionalRoutePrefix + string(e.To),
			Name:  e.Aliases[0],
			Forms: e.Aliases,
		})
	}
	return cands
}

// unconventionalRoutes lists the UNCONVENTIONAL crossings out of the player's current venue —
// a window, a plank — that one must deliberately NAME to take (default walking ignores them).
// Read straight from the venue's authored state (both directions are authored, so each venue
// declares its own nameable exits).
func (s *TurnService) unconventionalRoutes(tc *turnContext) []location.Edge {
	loc := tc.locations[tc.player.GetCurrentLocation()]
	if loc == nil {
		return nil
	}
	var out []location.Edge
	for _, e := range location.AdjacencyFromState(loc.State) {
		if !e.Sanctioned() && len(e.Aliases) > 0 {
			out = append(out, e)
		}
	}
	return out
}

// matchUnconventional decodes a grounded move ID back to the unconventional edge it names, if
// any — so doMove can tell "through the window" (a checked climb) from "to a venue" (a walk).
func (s *TurnService) matchUnconventional(tc *turnContext, resID string) (location.Edge, bool) {
	if !strings.HasPrefix(resID, unconventionalRoutePrefix) {
		return location.Edge{}, false
	}
	to := domain.LocationID(strings.TrimPrefix(resID, unconventionalRoutePrefix))
	for _, e := range s.unconventionalRoutes(tc) {
		if e.To == to {
			return e, true
		}
	}
	return location.Edge{}, false
}

// climbThrough resolves a deliberate unconventional crossing: a check (exposed, Risky). A botch
// is a FALL — a knock to the body, and you don't make it; a success slips you THROUGH to the far
// venue, bypassing the sanctioned-only walk. An unsanctioned entry into a barred venue is caught
// by the intrusion reflex on the move's tick (the law confronts), so the consequence is the
// world's, not Go-authored prose.
func (s *TurnService) climbThrough(ctx context.Context, tc *turnContext, edge location.Edge) (*actionOutcome, error) {
	pool := check.PoolFromContest(climbBaseDice, climbDifficulty)
	out := s.checkRoll(check.Seed(tc.tick, "climb", string(tc.player.ID)), pool, check.Risky)
	if !out.Tier.Accomplished() {
		s.commitHarm(ctx, tc, tc.player, climbFallHarm, tc.player.ID) // the fall is a real setback
		// Facts before prose: the slip is a committed OUTCOME the narrator renders — never a
		// Go-authored sentence surfaced raw (код не сочиняет прозу). The terse fact insures the
		// beat if the 4B drops it (the narrow committed-fact-verbatim safety net).
		fact := "Ты срываешься с ненадёжной переправы на полпути, падаешь и остаёшься на прежнем берегу."
		in := s.narrateFactsInput(ctx, tc, "перебраться на другой берег по ненадёжной переправе", []string{fact}, "", false)
		if prose, err := s.narrator.NarratePlayerAction(ctx, in); err == nil && strings.TrimSpace(prose) != "" {
			return &actionOutcome{narrative: prose}, nil
		}
		return &actionOutcome{narrative: fact}, nil
	}
	if err := s.movePlayerTo(ctx, tc, edge.To, "climbing"); err != nil {
		return nil, err
	}
	return &actionOutcome{narrative: s.arrivalText(tc, edge.To)}, nil
}

// movePlayerTo performs a single, immediate location change for the player (an unconventional
// crossing is one edge, not a journey): mutate the context, persist, and journal the move.
func (s *TurnService) movePlayerTo(ctx context.Context, tc *turnContext, to domain.LocationID, method string) error {
	from := tc.player.GetCurrentLocation()
	if ic, ok := tc.player.State.StateContext.(*actor.IdleContext); ok {
		ic.Location = to
	} else {
		tc.player.State.StateContext = &actor.IdleContext{Location: to, Activity: actor.ActivityTypeStanding}
	}
	if err := s.actors.Update(ctx, tc.player); err != nil {
		return fmt.Errorf("persist player location: %w", err)
	}
