// withConfront appends the watch's challenge verbatim after the narrated prose,
// so a crime before the law is always felt — the narrator may colour the deed,
// it may not quietly omit the law's reaction.
func withConfront(narrative string, v *verdict) string {
	if v.lawConfront == "" {
		return narrative
	}
	return strings.TrimSpace(narrative) + "\n" + v.lawConfront
}

// narrateFactsInput assembles the renderer's scene view: the committed facts,
// things physically here (including what co-located holders carry), time of
// day and the world premise. Nil-safe on the knowledge service.
func (s *TurnService) narrateFactsInput(ctx context.Context, tc *turnContext, deed string, facts []string, topic string, materialize bool) appllm.NarrateFactsInput {
	here := tc.player.GetCurrentLocation()
	in := appllm.NarrateFactsInput{
		Deed:         deed,
		Facts:        facts,
		LocationName: tc.locationName(here),
		LocationDesc: tc.locationDescription(here),
		TimeOfDay:    appllm.TimeOfDayRu(int(tc.gameTime.Hour())),
		Premise:      truncateRunes(tc.worldPremise, 280),
	}
	// The ambient sky, when it is worth saying — a strong wind or any falling water (a bare
	// breeze stays unsaid). Deterministic from the clock, a closed-vocab label, not prose.
	if weather := domain.WeatherAt(tc.gameTime, tc.worldID); weather.Notable() {
		in.Weather = weather.Describe()
	}

	holders := []domain.ActorID{tc.player.ID}
	for _, a := range tc.coLocated() {
		holders = append(holders, a.ID)
		in.Witnesses = append(in.Witnesses, a.Identity.Name)
		addGender(&in, a)
	}

	if s.knowledge == nil {
		return in
	}
	scene, err := s.knowledge.BuildScene(ctx, knowledge.Scope{
		WorldID:  tc.worldID,
		ActorID:  tc.player.ID,
		Location: here,
	}, holders, topic, knowledge.Options{Materialize: materialize})
	if err != nil {
		s.logger.Warn("narrator scene failed", zap.Error(err))
		return in
	}
	in.Scene = scene
	return in
}

// verdictNarrationInput builds the renderer's view for a committed verdict and
// drops the deed's target from the witness list: the victim is named by the
// fact itself («Изольт отшатывается»), not "watching", so the names the narrator
// sees match the grounded witness count and it can't reconcile a list of four
// against a fact of three («все трое — A, B, C и D»).
func (s *TurnService) verdictNarrationInput(ctx context.Context, tc *turnContext, deed string, v *verdict, topic string) appllm.NarrateFactsInput {
	in := s.narrateFactsInput(ctx, tc, deed, v.facts, topic, false)
	if v.targetNPC != nil {
		in.Witnesses = excludeName(in.Witnesses, v.targetNPC.Identity.Name)
	}
	return in
}

// addGender pins a co-located actor's grammatical gender on the narrator input,
// keyed by name, so Russian agreement is anchored rather than guessed. A no-op for
// GenderUnknown (the prompt then omits it rather than asserting a guess).
func addGender(in *appllm.NarrateFactsInput, a *actor.Actor) {
	if a == nil || a.Identity == nil {
		return
	}
	g := a.Identity.Gender.AgreementRu()
	if g == "" {
		return
	}
	if in.Genders == nil {
		in.Genders = map[string]string{}
	}
	in.Genders[a.Identity.Name] = g
}

// excludeName returns names without drop, preserving order.
func excludeName(names []string, drop string) []string {
	out := make([]string, 0, len(names))
	for _, n := range names {
		if n != drop {
			out = append(out, n)
		}
	}
	return out
}

// knowledgePack assembles the knowledge pack for one prompt through the given
// actor's eyes (nil-safe: no knowledge service → nil pack, prompts render
// without the knowledge sections).
func (s *TurnService) knowledgePack(ctx context.Context, tc *turnContext, viewer domain.ActorID, topic string, materialize bool) *knowledge.Pack {
	if s.knowledge == nil {
		return nil
	}
	pack, err := s.knowledge.BuildPack(ctx, knowledge.Scope{
		WorldID:  tc.worldID,
		ActorID:  viewer,
		Location: tc.player.GetCurrentLocation(),
	}, topic, knowledge.Options{Materialize: materialize})
	if err != nil {
		s.logger.Warn("knowledge pack failed", zap.Error(err))
		return nil
	}
	return pack
}

// ============================================================================
// helpers
// ============================================================================

// actorCandidates renders co-located actors as grounding candidates. The note
// is the authored background PLUS the current occupation (closed StateRu
// vocabulary) — the semantic hooks that let the model map «кузнец» to the
// right name and «сидящие за столом» to whoever is actually at the table. Forms
// carry the declined name-forms + authored aliases so a name in any case grounds
// through the structural accelerator without a model call.
func (s *TurnService) actorCandidates(actors []*actor.Actor) []extraction.Candidate {
	out := make([]extraction.Candidate, 0, len(actors))
	for _, a := range actors {
		note := truncateRunes(a.Identity.Background, 80)
		if a.State != nil {
			if doing := appllm.StateRu(a.State.StateType); doing != "" {
				note += "; сейчас " + doing
			}
		}
		out = append(out, extraction.Candidate{
			ID:    string(a.ID),
			Name:  a.Identity.Name,
			Note:  note,
			Forms: s.candidateForms(a.Identity.Name, a.Identity.Aliases),
		})
	}
	return out
}

func actorListing(actors []*actor.Actor) string {
	names := make([]string, 0, len(actors))
	for _, a := range actors {
		names = append(names, a.Identity.Name)
	}
	return strings.Join(names, ", ")
}

func short8(id domain.ActorID) string {
	s := string(id)
	if len(s) > 8 {
		return s[:8]
	}
	return s
}

func truncateRunes(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	return string(r[:n-1]) + "…"
}

// letterCount counts the letters in s — the cheap test that a string carries
// words rather than bare punctuation.
func letterCount(s string) int {
	n := 0
	for _, r := range s {
		if unicode.IsLetter(r) {
			n++
		}
	}
	return n
}

